using HiResClock = std::chrono::high_resolution_clock;
using MicroSec   = std::chrono::duration<double, std::micro>;

// ── Generic wall-clock stage timing (real-time budget check) ────────────────
// T_b = 100ms is the beacon-interval deadline (== PEM_BEACON_INTERVAL_S*1000,
// declared later in this file — hardcoded here, not referenced, purely to
// avoid a forward-declaration/linkage change for that constant; keep the two
// in sync if PEM_BEACON_INTERVAL_S is ever changed from 0.100s).
// Used to check whether each pipeline stage's real wall-clock cost fits
// inside one beacon interval on this hardware — purely observational, never
// alters scores/alerts/control flow. Declared early (before CryptoMeasureX
// below) so those functions, defined ~line 1000, can use it too.
struct PemSimpleStageStats {
    const char* label;
    double   totalMs = 0.0;
    double   maxMs = 0.0;
    uint64_t count = 0;
    uint64_t overBudgetCount = 0;
};

static PemSimpleStageStats g_pem_beacon_send_stats{
    "Beacon-send (DSRC 802.11p + HMAC sign, AttackSendDSRCBeacon)"};
static PemSimpleStageStats g_pem_rsu_forward_stats{
    "RSU-forward (CSMA dispatch, AttackSendRSUToController)"};
static PemSimpleStageStats g_pem_beacon_crypto_stats{
    "Beacon sign/verify crypto (HMAC+Dilithium, CryptoMeasureBeaconSign/Verify)"};
static PemSimpleStageStats g_pem_detection_crypto_stats{
    "Detection crypto (Dilithium verify+threshold-sig, CryptoMeasureDetection)"};
static PemSimpleStageStats g_pem_lkh_crypto_stats{
    "LKH mitigation crypto (LKH revoke+rekey, CryptoMeasureLKH)"};

static void PemRecordSimpleStage(PemSimpleStageStats& s, double elapsedMs)
{
    const double budgetMs = 100.0;   // T_b — see comment above
    s.totalMs += elapsedMs;
    ++s.count;
    if (elapsedMs > s.maxMs) s.maxMs = elapsedMs;
    if (elapsedMs > budgetMs) {
        ++s.overBudgetCount;
        std::cout << "[WARN][t=" << Simulator::Now().GetSeconds() << "] "
                  << s.label << " took " << elapsedMs << " ms, exceeding "
                  << budgetMs << " ms beacon-interval budget (T_b)\n";
    }
}

// RAII helper — records a simple (non-chained) stage's wall-clock time at
// scope exit, covering every return path automatically.
struct PemSimpleStageTimer {
    PemSimpleStageStats& stats_;
    HiResClock::time_point start_ = HiResClock::now();
    explicit PemSimpleStageTimer(PemSimpleStageStats& s) : stats_(s) {}
    ~PemSimpleStageTimer() {
        const double elapsedMs = MicroSec(HiResClock::now() - start_).count() / 1000.0;
        PemRecordSimpleStage(stats_, elapsedMs);
    }
};

// ── Record helper ─────────────────────────────────────────────────────────────
static inline void CryptoRecord(double sim_t, const char *op, double us,
                                 uint32_t nid, const char *evt, bool atk)
{
    if (!enable_crypto_latency) return;
    double sim_end = sim_t + us / 1e6;
    g_crypto_records.push_back({sim_t, sim_end, attack_scenario, op, us, nid, evt, atk ? 1 : 0});
    // latency=2: accumulate into pending delay so the next NS-3 event fires later
    if (g_crypto_inject_delay)
        g_crypto_pending_delay_us += us;
}

// ── Individual operation timers ───────────────────────────────────────────────
// ── TETA-Guard pipeline wrappers — replace all inline crypto stubs ────────────

static double __attribute__((unused)) TimedHmacSign(const uint8_t *msg, size_t len)
{
    // Uses beacon_sign() from hmac_filter.cc (the correct pipeline implementation)
    BeaconMessage bm = {};
    memcpy(bm.vehicle_id, msg, (len < 16 ? len : 16));
    bm.sender_timestamp_ms = 10000u;
    bm.gps_lat = 6.9271f; bm.gps_lon = 79.8612f; bm.rssi_dbm = -70.0f;
    RAND_bytes(bm.nonce, NONCE_LEN);
    auto t0 = HiResClock::now();
    beacon_sign(&bm, g_pipeline_session_key);
    return MicroSec(HiResClock::now() - t0).count();
}

static double __attribute__((unused)) TimedHmacVerify(const uint8_t *msg, size_t len)
{
    // Uses lw_mitigate() from hmac_filter.cc (HMAC verify + freshness + nonce check)
    BeaconMessage bm = {};
    memcpy(bm.vehicle_id, msg, (len < 16 ? len : 16));
    bm.sender_timestamp_ms = 10000u;
    bm.gps_lat = 6.9271f; bm.gps_lon = 79.8612f; bm.rssi_dbm = -70.0f;
    RAND_bytes(bm.nonce, NONCE_LEN);
    beacon_sign(&bm, g_pipeline_session_key);   // produce valid MAC first
    uint64_t recv_ms = 10005u;
    auto t0 = HiResClock::now();
    lw_mitigate(&bm, recv_ms, g_pipeline_session_key, false, &g_pipeline_nonce_cache);
    return MicroSec(HiResClock::now() - t0).count();
}

static double __attribute__((unused)) TimedDilSign(const uint8_t *msg, size_t len)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return 0.0;
    // Uses dilithium5_sign() from dilithium.cc: (msg, len, sk, sig_out, sig_len_out)
    auto t0 = HiResClock::now();
    dilithium5_sign(msg, len,
                    g_dil_sk.data(), g_pipeline_dil_sig, &g_pipeline_dil_sig_len);
    return MicroSec(HiResClock::now() - t0).count();
#else
    return 0.0;
#endif
}

static double __attribute__((unused)) TimedDilVerify(const uint8_t *msg, size_t len)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready || g_pipeline_dil_sig_len == 0) return 0.0;
    // Uses dilithium5_verify() from dilithium.cc: (msg, len, sig, sig_len, pk)
    auto t0 = HiResClock::now();
    dilithium5_verify(msg, len,
                      g_pipeline_dil_sig, g_pipeline_dil_sig_len, g_dil_pk.data());
    return MicroSec(HiResClock::now() - t0).count();
#else
    return 0.0;
#endif
}

static double __attribute__((unused)) TimedHaversine()
{
    // Uses haversine_distance_m() from location_binding.cc (official pipeline impl)
    float lat1 = 6.9271f, lon1 = 79.8612f, lat2 = 6.9298f, lon2 = 79.8640f;
    auto t0 = HiResClock::now();
    volatile float dist = haversine_distance_m(lat1, lon1, lat2, lon2);
    (void)dist;
    return MicroSec(HiResClock::now() - t0).count();
}

// ── KEM fleet-management wrappers ─────────────────────────────────────────────
// TimedKemRegister: kem_register_vehicle() — enrol a vehicle into the RSU
// keystore so the RSU can later encapsulate to it by ID without a fresh keygen.
static double __attribute__((unused)) TimedKemRegister(const uint8_t vid[16], uint32_t leaf_idx,
                                                          uint8_t *sk_vi_out = nullptr)
{
    auto t0 = HiResClock::now();
    kem_register_vehicle(vid, leaf_idx, sk_vi_out);
    return MicroSec(HiResClock::now() - t0).count();
}

// TimedKemLookup: kem_lookup() — RSU retrieves a registered vehicle's key
// record before encapsulation (replaces inline keygen in fleet deployments).
static double __attribute__((unused)) TimedKemLookup(const uint8_t vid[16])
{
    auto t0 = HiResClock::now();
    volatile VehicleKeyRecord *rec = kem_lookup(vid);
    (void)rec;
    return MicroSec(HiResClock::now() - t0).count();
}

// ── LKH status-query wrappers ─────────────────────────────────────────────────
// TimedLkhIsRevoked: lkh_is_revoked() — RSU checks revocation status before
// forwarding a beacon packet (gate dropped packets from revoked nodes).
static double __attribute__((unused)) TimedLkhIsRevoked(const uint8_t vid[16])
{
    if (!g_lkh_ready) return 0.0;
    auto t0 = HiResClock::now();
    volatile bool rev = lkh_is_revoked(&g_lkh_tree, vid);
    (void)rev;
    return MicroSec(HiResClock::now() - t0).count();
}

// TimedLkhGetSessionKey: lkh_get_session_key() — vehicle derives its new
// session key from the refreshed KEK after an LKH revocation broadcast.
static double __attribute__((unused)) TimedLkhGetSessionKey(const uint8_t vid[16])
{
    if (!g_lkh_ready) return 0.0;
    uint8_t key_out[LKH_KEY_LEN];
    auto t0 = HiResClock::now();
    volatile bool ok = lkh_get_session_key(&g_lkh_tree, vid, key_out);
    (void)ok;
    return MicroSec(HiResClock::now() - t0).count();
}

// ── Quorum verification wrapper ───────────────────────────────────────────────
// TimedVerifyQuorum: verify_quorum() — require t-of-n witnesses to independently
// confirm the same link (stronger than single-witness; used in ME detection).
// Builds n=2 synthetic LocationBoundReports from the same cert and calls
// verify_quorum(reports, n=2, t=2, ...) requiring both to pass.
static double __attribute__((unused)) TimedVerifyQuorum()
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return 0.0;
    uint8_t link_id[8] = {0,1,0,2,0,0,0,0};
    const uint32_t N_W = 2;
    LocationBoundReport reports[N_W];
    for (uint32_t i = 0; i < N_W; i++) {
        // rid[1]=0xFE marks this as a synthetic benchmark witness, distinct from
        // any real vehicle_id (which always has rid[1]==0 — see the rid[16]={}
        // pattern used everywhere else). Without this, a synthetic witness whose
        // rid[0] happens to match a real vehicle_id byte value would spuriously
        // inherit that vehicle's CRL revocation status in cert_is_revoked().
        uint8_t rid[16] = {}; rid[0] = (uint8_t)(3 + i); rid[1] = 0xFE;  // V3, V4 as witnesses
        CertificateRecord qcert;
        dilithium5_issue_cert(rid, g_dil_pk.data(), (uint64_t)i * 1000, &qcert);
        create_location_bound_report(
            link_id,
            6.9271f, 79.8612f, -70.0f, 10000u,
            rid, g_dil_sk.data(), g_dil_pk.data(), &qcert,
            &reports[i]);
        reports[i].has_rsu_measurement   = true;
        reports[i].rsu_measured_rssi_dbm = -70.0f;
    }
    auto t0 = HiResClock::now();
    volatile bool ok = verify_quorum(reports, N_W, N_W,
                                     6.9271f, 79.8612f, 10005u);
    (void)ok;
    return MicroSec(HiResClock::now() - t0).count();
#else
    return 0.0;
#endif
}

// ── Threshold signature wrappers ──────────────────────────────────────────────
// dilithium5_sign/verify_thresh use domain separation (TETA_DS_THRESH) so a
// threshold-context signature cannot be replayed as a normal beacon signature.
// Used when the controller co-signs a detection decision before acting on it.
static double __attribute__((unused)) TimedDilSignThresh(const uint8_t *msg, size_t len)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return 0.0;
    uint8_t sig[DILITHIUM5_SIG_LEN]; size_t slen = sizeof(sig);
    auto t0 = HiResClock::now();
    dilithium5_sign_thresh(msg, len, g_dil_sk.data(), sig, &slen);
    return MicroSec(HiResClock::now() - t0).count();
#else
    return 0.0;
#endif
}

static double __attribute__((unused)) TimedDilVerifyThresh(const uint8_t *msg, size_t len)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready || g_pipeline_dil_sig_len == 0) return 0.0;
    // Sign first so we have a valid thresh-domain signature to verify
    uint8_t sig[DILITHIUM5_SIG_LEN]; size_t slen = sizeof(sig);
    dilithium5_sign_thresh(msg, len, g_dil_sk.data(), sig, &slen);
    auto t0 = HiResClock::now();
    volatile bool ok = dilithium5_verify_thresh(msg, len, sig, slen, g_dil_pk.data());
    (void)ok;
    return MicroSec(HiResClock::now() - t0).count();
#else
    return 0.0;
#endif
}

// Forward decls — real definitions live further down (Eq. 3.11 detection block
// / A5 runtime-override globals); needed here so the Algorithm 4 VERIFY_QUORUM
// gate can reuse the exact same distance/RSSI model Stage-0 detection uses.
// PemDistance2d is forward-declared again (identically) at its usual spot
// further down — duplicate function forward decls are fine in C++.
static double PemDistance2d(const Vector& a, const Vector& b);
static double PemGetRcomm();     // returns g_rcomm  (defined right after g_rcomm below)
static double PemGetRssiMin();   // returns g_rssi_min (defined right after g_rssi_min below)

// ── Algorithm 4 (FS-MITIGATE) enforcement gates ───────────────────────────────
// Unlike the Timed*() wrappers above (latency measurement only, result discarded),
// these three functions return the real pass/fail decision and are the actual
// gates PemApplyMitigation() consults before pushing a FlowMod/BlacklistBeacon
// action. Detection scoring (TP/FP/MCC/AUROC) is unaffected — that is decided
// earlier by PemRecordObservation()/Stage-0; these gates only decide whether
// the smart-contract *enforcement* action is allowed to proceed, matching the
// abort semantics of Algorithm 4 lines 8-11 (PBFT) and 21-27 (VERIFY_*).

// PBFT_CONSENSUS(A) — Algorithm 4 line 8 / Eq. 3.47-3.48. Trust-weighted quorum:
// each peer's vote is weighted by its ledger trust score tau_k rather than
// counted equally, matching checkPBFTTrustWeight() in the Go chaincode
// (trust.go) exactly:
//   Accept <=> (sum_{k in P_approve} tau_k) / (sum_{k in P_active} tau_k) > 2/3
// f/q_needed are still reported for diagnostics (classical node-count quorum,
// f = floor((n_peers-1)/3)) but the accept/reject decision is the trust ratio,
// not the raw count — this preserves the Eq. 3.48 safety property that
// Byzantine peers accumulating trust cannot forge consensus on their own.
static bool PemPbftConsensusGate(uint32_t n_peers, uint32_t &f_out, uint32_t &q_needed_out,
                                  double sum_approve_tau, double sum_active_tau)
{
    const uint32_t f = (n_peers >= 1u) ? (n_peers - 1u) / 3u : 0u;
    const uint32_t q_needed = 2u * f + 1u;
    f_out = f; q_needed_out = q_needed;
    if (n_peers < 1u || sum_active_tau <= 0.0) return false;
    return (sum_approve_tau / sum_active_tau) > (2.0 / 3.0);
}

// VERIFY_THRESHOLD_SIG(sigma_v) — Algorithm 4 lines 40-50 / Eq. 3.26.
// Counts real, individually verified ML-DSA-87(Dilithium5) threshold-domain
// signatures (dilithium5_sign_thresh/verify_thresh, TETA_DS_THRESH-separated
// so they cannot be replayed as ordinary beacon signatures) against
// t = floor(n/2)+1. The signed payload is the REAL per-call event data
// (attacker id + decision time), not a fixed placeholder, so distinct
// mitigation events produce distinct signed messages. Without liboqs
// (ALLOW_DILITHIUM_STUB build), Eqs. 3.26-3.28 are documented as simulated —
// this gate degrades to pass-through in that build configuration, consistent
// with that documented behaviour.
static bool PemVerifyThresholdSig(uint32_t n_reporters, uint32_t attacker_id, double t_now,
                                   uint32_t &c_out, uint32_t &t_out)
{
    const uint32_t t = n_reporters / 2u + 1u;
    t_out = t;
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) { c_out = n_reporters; return true; }
    uint32_t c = 0;
    // Real per-event payload: "FS4|<attacker_id>|<t_now_ms>" — differs call to call.
    uint64_t t_now_ms = (uint64_t)std::llround(t_now * 1000.0);
    uint8_t msg[16];
    std::memcpy(msg,     "FS4|", 4);
    std::memcpy(msg + 4, &attacker_id, sizeof(attacker_id));
    std::memcpy(msg + 8, &t_now_ms,    sizeof(t_now_ms));
    for (uint32_t i = 0; i < n_reporters; i++) {
        uint8_t sig[DILITHIUM5_SIG_LEN]; size_t slen = sizeof(sig);
        dilithium5_sign_thresh(msg, sizeof(msg), g_dil_sk.data(), sig, &slen);
        if (dilithium5_verify_thresh(msg, sizeof(msg), sig, slen, g_dil_pk.data()))
            c++;
    }
    c_out = c;
    return c >= t;
#else
    c_out = n_reporters;
    return true;
#endif
}

// =============================================================================
// Phase 2 — real per-reporter signed location-bound evidence (Eq. 3.27-3.28)
// for GENUINE (non-forged) topology observations. This is separate from the
// 9 LW detection signatures (TTW/BSHH/ME) — it exists purely to give
// PemVerifyQuorum (Eq. 3.29-3.30, defined below) real per-reporter evidence
// to evaluate, instead of a fabricated clone.
//
// Declared here (ahead of PemVerifyQuorum) purely for C++ ordering — the
// producer, PemSignGenuineReport(), is defined much later, next to
// PemEmitEvent(), where all its dependencies (kem_lookup, MAX_VEHICLES,
// PEM_BEACON_INTERVAL_S, g_vehicle_dilithium_sk) are already in scope.
// =============================================================================
struct PemGenuineReport {
    LocationBoundReport report;
    double sim_time;
};
static std::map<std::tuple<uint32_t,uint32_t,uint32_t>, PemGenuineReport> g_pem_genuine_reports;

// e_ij identifier — order-independent (min,max) so a V1-sees-V2 report and a
// V2-sees-V1 report about the same physical link land on the same key.
static void PemBuildLinkId(uint32_t a, uint32_t b, uint8_t link_id[8])
{
    uint32_t lo = (a <= b) ? a : b, hi = (a <= b) ? b : a;
    link_id[0] = (uint8_t)((lo >> 8) & 0xFFu);
    link_id[1] = (uint8_t)(lo & 0xFFu);
    link_id[2] = (uint8_t)((hi >> 8) & 0xFFu);
    link_id[3] = (uint8_t)(hi & 0xFFu);
    link_id[4] = link_id[5] = link_id[6] = link_id[7] = 0;
}

// Real per-witness spatial evidence for VERIFY_QUORUM (Eqs. 3.29-3.30). Filled
// from the actual mobility-model positions at the ME call site — the witness's
// real reported position and the real link-endpoint positions, so the gate can
// genuinely reject a witness that is not physically near the link it claims to
// have observed (matching the same geometry Stage-0's ME-S3 signature, sig[8],
// already uses via PemDistance2d/g_rcomm/g_rssi_min).
struct PemQuorumEvidence {
    Vector witness_pos;
    Vector link_src_pos;
    Vector link_dst_pos;
    // Phase 3: real link identity, needed to look up genuinely-signed
    // Phase 2 reports (g_pem_genuine_reports) for this exact physical link.
    uint32_t link_src_id = 0;
    uint32_t link_dst_id = 0;
    // Phase 3: the FULL claimed-reporter set R(eij,t) for this link — every
    // vehicle/entity that claims to have reported this link for this event,
    // real (link_src_id/link_dst_id themselves) and fabricated alike (ME's
    // false witnesses). Eq. 3.30's n and t = floor(n/2)+1 are computed over
    // this set's size, not fleet size and not "count of genuinely-signed
    // ones only" — matching "cross-checks each candidate witness" (Algorithm
    // 4's own description of VERIFY_QUORUM) rather than admitting the link
    // merely because SOME real vehicle once witnessed it.
    std::vector<uint32_t> claimed_reporters;
};

// Local-Cartesian (simulation metres) -> GPS lat/lon, anchored at the same test
// origin (6.9271N, 79.8612E — Colombo) used elsewhere in this file. Flat-earth
// approximation (valid at DSRC/city scale, <<1km): 1 deg lat ~= 111320 m.
static void PemSimToGps(const Vector &pos, float &lat, float &lon)
{
    static const double kAnchorLat = 6.9271, kAnchorLon = 79.8612;
    static const double kMPerDegLat = 111320.0;
    const double lat_rad = kAnchorLat * M_PI / 180.0;
    lat = (float)(kAnchorLat + pos.y / kMPerDegLat);
    lon = (float)(kAnchorLon + pos.x / (kMPerDegLat * std::cos(lat_rad)));
}

// VERIFY_QUORUM(W_v, t) — Algorithm 4 lines 52-66 / Eqs. 3.29-3.30.
//
// Phase 3 rewrite: evaluates the FULL claimed-reporter set R(eij,t) for this
// link (ev->claimed_reporters — every vehicle/entity that claims to have
// reported it, real AND fabricated alike), matching Algorithm 4's own
// description ("VERIFY_QUORUM cross-checks EACH CANDIDATE WITNESS") and
// Eq. 3.30's literal set-builder {Vk : Accept_Vk(eij)=1}, rather than either
// (a) a fabricated clone of one position signed n times with the shared
// demo keypair (the original bug), or (b) an aggregate over only the
// genuinely-signed subset, which would wrongly admit a link merely because
// SOME real vehicle once witnessed it, ignoring how many OTHER claimants on
// the same event were fabricated.
//
// n = |R(eij,t)| (the full claimed set, real + fake), t = floor(n/2)+1.
// For each claimed reporter, Accept_Vk looks up whether THAT reporter has a
// real, genuinely-signed Phase 2 LocationBoundReport for this exact link
// (g_pem_genuine_reports) and if so runs it through verify_single_witness()
// (Eq. 3.29: signature, spatial, RSSI). A fabricated witness (ME's false
// V3/V4, or a malicious RSU/controller impersonating one) never has such a
// report — Phase 2's PemSignGenuineReport only ever signs attackLabel==false
// observations — so it fails Accept_Vk by construction, not by a
// convenient absence check.
// Stateful per-(witness, link, report-version) Accept_Vk decision cache —
// Eq. 3.29's own quorum-round state, mirroring the Eq. 3.17 Nseen pattern
// (a persistent map checked/set in O(1), not a re-verify or O(N) scan).
// verify_single_witness() consumes the report's nonce (Gate E) on its FIRST
// successful evaluation, by design, to stop the SAME signed report being
// replayed into a different aggregate later — but that also means a second
// PemVerifyQuorum call in the same round, re-checking the same still-fresh
// cached report (e.g. two mitigation attempts on the same link within one
// beacon interval), would spuriously read as "already consumed" and flip
// PASS->FAIL for no attack-relevant reason. Caching the decision per
// (reporterId, link, report_sim_time) — the last field pinning it to a
// SPECIFIC signed report version, so a later freshly re-signed report still
// gets its own fresh Accept_Vk call — fixes that without weakening Gate E's
// real anti-replay property against a genuinely different/attacker-supplied
// report.
static std::map<std::tuple<uint32_t,uint32_t,uint32_t,double>, bool> g_pem_quorum_witness_cache;

static bool PemVerifyQuorum(uint32_t n_witnesses, const PemQuorumEvidence *ev,
                             uint32_t &q_out, uint32_t &t_out)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) { t_out = n_witnesses / 2u + 1u; q_out = n_witnesses; return true; }
    if (ev == nullptr || ev->claimed_reporters.empty()) {
        t_out = n_witnesses / 2u + 1u; q_out = 0u; return false;
    }

    const uint32_t n_total = (uint32_t)ev->claimed_reporters.size();
    const uint32_t t = n_total / 2u + 1u;
    t_out = t;

    float link_lat, link_lon;
    PemSimToGps(ev->link_src_pos, link_lat, link_lon);
    const uint64_t recv_ms = (uint64_t)std::llround(Simulator::Now().GetSeconds() * 1000.0);

    uint32_t legit_count = 0;
    for (uint32_t reporterId : ev->claimed_reporters) {
        const PemGenuineReport *w = nullptr;
        auto it1 = g_pem_genuine_reports.find(
            std::make_tuple(reporterId, ev->link_src_id, ev->link_dst_id));
        if (it1 != g_pem_genuine_reports.end()) {
            w = &it1->second;
        } else {
            auto it2 = g_pem_genuine_reports.find(
                std::make_tuple(reporterId, ev->link_dst_id, ev->link_src_id));
            if (it2 != g_pem_genuine_reports.end()) w = &it2->second;
        }
        if (w == nullptr) continue;

        const auto wkey = std::make_tuple(reporterId, ev->link_src_id, ev->link_dst_id,
                                           w->sim_time);
        auto cacheIt = g_pem_quorum_witness_cache.find(wkey);
        bool accepted;
        if (cacheIt != g_pem_quorum_witness_cache.end()) {
            accepted = cacheIt->second;
        } else {
            accepted = verify_single_witness(&w->report, link_lat, link_lon, recv_ms);
            g_pem_quorum_witness_cache[wkey] = accepted;
        }
        if (accepted) legit_count++;
    }

    q_out = legit_count;
    return legit_count >= t;
#else
    t_out = n_witnesses / 2u + 1u;
    q_out = n_witnesses;
    return true;
#endif
}

static double __attribute__((unused)) TimedFreshness()
{
    // Freshness gate embedded in lw_mitigate(); standalone timing uses same logic
    uint64_t recv_ms = 10050u, sender_ms = 10000u;
    auto t0 = HiResClock::now();
    volatile bool ok = ((int64_t)recv_ms - (int64_t)sender_ms) <=
                       (int64_t)FRESHNESS_WINDOW_MS;
    (void)ok;
    return MicroSec(HiResClock::now() - t0).count();
}

static double __attribute__((unused)) TimedLkhRevoke(uint32_t n)
{
    // Uses lkh_revoke_vehicle() from lkh_mgmt.cc — real O(log n) tree revocation
    if (!g_lkh_ready || g_lkh_n_leaves == 0u) return 0.0;
    // Modulo the ACTUAL registered leaf count (g_lkh_n_leaves), not a fixed 16 —
    // otherwise this benchmark could index an unregistered leaf when N_Vehicles < 16.
    uint32_t idx = (n > 0 ? (n - 1) : 0) % g_lkh_n_leaves;
    auto t0 = HiResClock::now();
    lkh_revoke_vehicle(&g_lkh_tree, g_lkh_vids[idx]);
    return MicroSec(HiResClock::now() - t0).count();
}

// ── Location-Binding: create report + verify_single_witness (§3.4.5) ──────────
// Eq. 3.27: m'_Vk = eij ‖ pos_Vk ‖ RSSI_Vk←Vi ‖ τs ‖ nonce
// Eq. 3.28: σ_Vk = Sign(SK_Vk, m'_Vk) — ML-DSA-87 (NIST FIPS 204, Dilithium5)
//           SK_Vk is Vk's LONG-TERM IDENTITY-BOUND SIGNING KEY (not a KEM key).
// Eq. 3.29: Accept_Vk(eij) iff Verify(σ_Vk,PK_Vk)=1 AND d(pos_Vk,eij)≤r_comm AND RSSI≥RSSI_min
// Eq. 3.30: Accept(eij) iff |{Vk: Accept_Vk(eij)=1}| ≥ t
// Uses create_location_bound_report() + verify_single_witness() from
// location_binding.cc.  Returns sign+verify combined µs.
// Each call generates a fresh nonce inside create_location_bound_report(), so
// the nonce-replay guard inside verify_single_witness (Gate E) never fires.
static double __attribute__((unused)) TimedLocationBind()
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return 0.0;
    uint8_t link_id[8]     = {0,1,0,2,0,0,0,0};  // simulated V1↔V2 link
    uint8_t reporter_id[16] = {}; reporter_id[0] = 3;  // V3 as witness

    // Issue a fresh per-call cert so repeated measurements don't reuse the same
    // (vehicle_id, nonce) pair consumed by Gate E.
    CertificateRecord lcert;
    dilithium5_issue_cert(reporter_id, g_dil_pk.data(), 0, &lcert);

    LocationBoundReport report;
    auto t0 = HiResClock::now();
    create_location_bound_report(
        link_id,
        6.9271f, 79.8612f,   // reporter GPS (Colombo test coords)
        -70.0f,              // RSSI from link endpoint
        10000u,              // sender_timestamp_ms
        reporter_id,
        g_dil_sk.data(), g_dil_pk.data(),
        &lcert,
        &report);
    double sign_us = MicroSec(HiResClock::now() - t0).count();

    // Fill RSU-side measurement (required by Gate iii — RSSI plausibility)
    report.has_rsu_measurement    = true;
    report.rsu_measured_rssi_dbm  = -70.0f;

    t0 = HiResClock::now();
    bool ok = verify_single_witness(
        &report,
        6.9271f, 79.8612f,   // link endpoint GPS (same loc → dist=0, passes Gate ii)
        10005u);             // recv_time_ms (within LOCBIND_FRESHNESS_WINDOW_MS)
    double verify_us = MicroSec(HiResClock::now() - t0).count();
    (void)ok;
    return sign_us + verify_us;
#else
    return 0.0;
#endif
}

// ── KEM measurement — ML-KEM-1024 (Kyber-1024) + HQC-5 hybrid pipeline ─────────
// Role (§3.4.2, Eq. 3.15): establishes shared session key K_Vi,nk used for
//   HMAC-SHA256(K_Vi,nk, m') authentication.  This is a KEY ENCAPSULATION
//   MECHANISM — it produces session secrets, NOT signing keys.
// Uses kem_vehicle_keygen / kem_rsu_encapsulate / kem_vehicle_decapsulate from
// kem.cc.  Each step includes ML-DSA-87 (Dilithium5) auth signatures and cert
// checks that are part of the TETA-Guard KEM handshake (Section 3.3 Steps 1,3,4).
// Note: ML-DSA-87 here authenticates the KEM key exchange itself; it does NOT
// produce the location-binding signatures of Eq. 3.28 (those use SK_Vk directly).
static void __attribute__((unused))
MeasureKEM(double sim_t, uint32_t node_id, const char *evt, bool atk)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return;

    // Use the test cert issued during CryptoInitKeys (g_test_cert).
    // A unique nonce is generated inside kem_vehicle_keygen each call,
    // so repeated measurements don't hit the nonce-replay guard.
    KemExchangeState state;
    uint8_t vid[16] = {}; vid[0] = (uint8_t)node_id;
    uint8_t session_key[SESSION_KEY_LEN], session_key2[SESSION_KEY_LEN];

    // Step 0a: RSU enrols vehicle in fleet keystore (fleet management).
    // Capture the real SK_Vi identity key into the vehicle-side-only array
    // so this vehicle (commonly V0, the t=0 "Session_Setup" test vehicle)
    // has a real signing key available, same as every other vehicle
    // registered via CryptoDeriveVehicleSessionKeys() below.
    double reg_us = (node_id < MAX_VEHICLES)
                     ? TimedKemRegister(vid, node_id % 16, g_vehicle_dilithium_sk[node_id])
                     : TimedKemRegister(vid, node_id % 16);
    if (node_id < MAX_VEHICLES) g_vehicle_dilithium_sk_ready[node_id] = true;

    // Step 1: vehicle generates Kyber-1024 + HQC-5 keypair + signs them
    auto t0 = HiResClock::now();
    kem_vehicle_keygen(&state, vid, g_dil_sk.data(), g_dil_pk.data(), &g_test_cert);
    double kg_us = MicroSec(HiResClock::now() - t0).count();

    // Step 2: RSU looks up the vehicle's key record before encapsulation
    double lkp_us = TimedKemLookup(vid);

    // Step 3: RSU verifies cert + keygen sig, encapsulates to both KEMs, HKDF
    t0 = HiResClock::now();
    bool enc_ok = kem_rsu_encapsulate(&state, session_key);
    double enc_us = MicroSec(HiResClock::now() - t0).count();

    // Step 4: vehicle decapsulates Kyber-1024 + HQC-5 ciphertexts, HKDF
    t0 = HiResClock::now();
    bool dec_ok = enc_ok && kem_vehicle_decapsulate(&state, session_key2);
    double dec_us = MicroSec(HiResClock::now() - t0).count();

    (void)dec_ok;
    CryptoRecord(sim_t, "KEM_Register", reg_us, node_id, evt, atk);
    CryptoRecord(sim_t, "KEM_KeyGen",   kg_us,  node_id, evt, atk);
    CryptoRecord(sim_t, "KEM_Lookup",   lkp_us, node_id, evt, atk);
    CryptoRecord(sim_t, "KEM_Encap",    enc_us, node_id, evt, atk);
    CryptoRecord(sim_t, "KEM_Decap",    dec_us, node_id, evt, atk);
    if (enable_crypto_latency == 3) {
        double ts = sim_t;
        g_crypto3_records.push_back({"KEM_KeyGen", evt, node_id, atk?1:0, ts,             ts+kg_us/1e6,  kg_us,  attack_scenario});
        ts += kg_us / 1e6;
        g_crypto3_records.push_back({"KEM_Encap",  evt, node_id, atk?1:0, ts,             ts+enc_us/1e6, enc_us, attack_scenario});
        ts += enc_us / 1e6;
        g_crypto3_records.push_back({"KEM_Decap",  evt, node_id, atk?1:0, ts,             ts+dec_us/1e6, dec_us, attack_scenario});
    }
#endif
}

// ── Initialise keys + measure KEM session setup ───────────────────────────────
// §3.4.2, §3.4.4, §3.4.5 — TWO DISTINCT PRIMITIVE ROLES (not interchangeable):
//
//  ① ML-KEM-1024 (Kyber-1024) + HQC-5 hybrid  →  session key K_Vi,nk  (Eq. 3.15)
//     • Key Encapsulation Mechanism (KEM) — not a signature scheme
//     • Purpose: establish shared secret K_Vi,nk between vehicle Vi and trusted node nk
//     • That secret is then used as the HMAC-SHA256 key for beacon authentication
//     • Implemented in kem.cc (kem_vehicle_keygen / kem_rsu_encapsulate /
//       kem_vehicle_decapsulate); measured by MeasureKEM()
//
//  ② ML-DSA-87 (NIST FIPS 204, liboqs Dilithium5)  →  SK_Vk / PK_Vk  (Eq. 3.28)
//     • Digital signature scheme — not a KEM; does NOT produce session secrets
//     • Purpose: long-term identity-bound signing key for each vehicle Vk
//     • Used in: Eq. 3.28 location-binding signatures σ_Vk = Sign(SK_Vk, m'_Vk)
//                Eq. 3.26 threshold aggregate signature Verify(σ_agg, PK_agg)
//                KEM handshake auth (vehicle signs its own KEM public key)
//     • Implemented via dilithium5_sign / dilithium5_verify / dilithium5_thresh
//       from .crypto_src/dilithium.cc; initialised below
//
//  These two primitives are complementary, not alternatives:
//    ML-KEM  → symmetric session secrets (HMAC keys)
//    ML-DSA-87 → asymmetric identity proofs (PKI signatures)

// ── Real per-vehicle K_{Vi,nk} derivation (Eq. 3.15) ──────────────────────────
// Runs the genuine Section 3.3/3.4.2 bootstrapping once per vehicle at t=0
// ("session keys pre-assumed established at t=0" — teta_guard_filter.h).
// Gap 2.1 fix: this now calls kem_register_vehicle() — the same RSU
// enrolment API TimedKemRegister() uses for latency measurement — for every
// simulated vehicle, instead of reimplementing the handshake steps inline and
// only writing into routing.cc's own g_vehicle_session_keys[] array.
// kem_register_vehicle() performs the full Section 3.4.2 handshake (Dilithium5
// identity keypair -> CA cert -> kem_vehicle_keygen -> kem_rsu_encapsulate ->
// kem_vehicle_decapsulate, comparing both sides' derived keys) AND stores the
// VehicleKeyRecord in the RSU key store (kem.cc's g_keystore), so kem_lookup()
// and revocation now see the real fleet, not just the single test vehicle
// registered inside MeasureKEM(0.0, 0, ...) above. kem_lookup() is checked
// first so that pre-existing slot (vehicle_id==0) is reused rather than
// double-registered. Requires the HQC-5 buffer-size fix in teta_guard_types.h
// (HQC5_PK_LEN/SK_LEN/CT_LEN) to succeed — before that fix every call here
// would fail with "[KEM] REJECT: keygen sig invalid" due to KemExchangeState
// struct corruption.
static void CryptoDeriveVehicleSessionKeys()
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return;
    uint32_t n = (N_Vehicles > 0u) ? N_Vehicles : 1u;
    if (n > MAX_VEHICLES) n = MAX_VEHICLES;
    uint32_t ok_count = 0;
    for (uint32_t i = 0; i < n; i++) {
        uint8_t vid[16] = {};
        vid[0] = (uint8_t)(i & 0xFFu);
        vid[1] = (uint8_t)((i >> 8) & 0xFFu);

        VehicleKeyRecord *rec = kem_lookup(vid);
        // rec pre-existing here only happens for i==0 (registered earlier by
        // MeasureKEM(0.0,0,...)'s TimedKemRegister call, which already
        // captured g_vehicle_dilithium_sk[0]) — so only the fresh-registration
        // branch needs to capture sk_vi itself.
        if (!rec) rec = kem_register_vehicle(vid, i, g_vehicle_dilithium_sk[i]);
        if (rec) {
            memcpy(g_vehicle_session_keys[i], rec->session_key, SESSION_KEY_LEN);
            g_vehicle_session_key_ready[i] = true;
            g_vehicle_dilithium_sk_ready[i] = true;
            ok_count++;
        }
    }
    std::cout << "[KEM] Registered " << ok_count << "/" << n
              << " vehicles with the RSU keystore (ML-KEM-1024 + HQC-5 hybrid, Eq. 3.15 K_{Vi,nk})."
              << " Real per-vehicle Dilithium5 SK_Vi identity keys captured (Eq. 3.27-3.28).\n";
#endif
}

// Returns the real KEM-derived K_{Vi,nk} for vehicle_id if the handshake in
// CryptoDeriveVehicleSessionKeys() succeeded for it; otherwise falls back to
// the same deterministic per-vehicle derivation TetaGuardGetSessionKey() uses
// in teta_guard_filter.h, so sign and verify still agree on a key when
// liboqs is unavailable or vehicle_id is beyond MAX_VEHICLES.
static void CryptoGetVehicleSessionKey(uint32_t vehicle_id, uint8_t out[SESSION_KEY_LEN])
{
    if (vehicle_id < MAX_VEHICLES && g_vehicle_session_key_ready[vehicle_id]) {
        memcpy(out, g_vehicle_session_keys[vehicle_id], SESSION_KEY_LEN);
        return;
    }
    for (uint32_t j = 0; j < SESSION_KEY_LEN; j++)
        out[j] = (uint8_t)((vehicle_id * 37u + j * 13u + 0x5Au) & 0xFFu);
}

// CryptoGetPairwiseSessionKey — real K_{Vi,nk}, genuinely scoped to the
// (vehicle, receiving-node) pair, not just the vehicle. Previously
// TetaGuardGetSessionKey()/CryptoGetVehicleSessionKey() returned one key per
// vehicle regardless of which RSU/controller was verifying — meaning a
// forged event with physical_sender_id == claimed_sender_id == victim_id
// always passed Stage-0's Eq. 3.15 HMAC check purely from the ID match, with
// no dependency on which node actually holds a legitimate session with that
// vehicle. This derives the final verification key as
// HMAC-SHA256(base_key_Vi, receiver_id) — base_key_Vi is unchanged (still
// the real ML-KEM-1024+HQC-5-derived, or deterministic-fallback, per-vehicle
// secret from CryptoGetVehicleSessionKey()); only the derivation step is new.
// A key exfiltrated from vehicle Vi's session with one node does not, by
// itself, produce a valid key for a DIFFERENT verifying node — matching how
// real per-link session keys work. Within a single PemEvent evaluation both
// the claimed- and physical-sender lookups use the same reporter_id (the
// node currently verifying), so this does not change any pass/fail outcome
// for the existing 12 attack scenarios — same-ID-twice still converges to
// the same derived key. It only closes the gap for attacks that would try
// to reuse a key stolen from a different link than the one being verified,
// which none of the current 12 scenarios attempt.
static void CryptoGetPairwiseSessionKey(uint32_t vehicle_id, uint32_t receiver_id,
                                         uint8_t out[SESSION_KEY_LEN])
{
    uint8_t baseKey[SESSION_KEY_LEN];
    CryptoGetVehicleSessionKey(vehicle_id, baseKey);

    uint8_t receiverBytes[4] = {
        (uint8_t)(receiver_id & 0xFFu),
        (uint8_t)((receiver_id >> 8) & 0xFFu),
        (uint8_t)((receiver_id >> 16) & 0xFFu),
        (uint8_t)((receiver_id >> 24) & 0xFFu)
    };
    unsigned mac_len = SESSION_KEY_LEN;
    HMAC(EVP_sha256(), baseKey, SESSION_KEY_LEN, receiverBytes, sizeof(receiverBytes),
         out, &mac_len);
}

static void CryptoInitKeys()
{
    // LKH tree is always initialised regardless of enable_crypto_latency — it is
    // needed by the live revocation path in PemEvaluateEvent (Eq. 3.18).
    // Eq. 3.18: C_revoke = O(log n) for n REGISTERED vehicles — n must track
    // the actual simulated fleet size, not a fixed n=16, or the revocation
    // cost/tree depth reported by this run doesn't correspond to N_Vehicles.
    g_lkh_n_leaves = (N_Vehicles > 0u) ? N_Vehicles : 1u;
    if (g_lkh_n_leaves > MAX_VEHICLES) g_lkh_n_leaves = MAX_VEHICLES;

    memset(g_lkh_keystore, 0, sizeof(g_lkh_keystore));
    memset(g_lkh_vids, 0, sizeof(g_lkh_vids));
    for (uint32_t i = 0; i < g_lkh_n_leaves; i++) {
        g_lkh_vids[i][0] = (uint8_t)i;
        memcpy(g_lkh_keystore[i].vehicle_id, g_lkh_vids[i], 16);
        g_lkh_keystore[i].lkh_leaf_index = i;
    }
    lkh_set_keystore(g_lkh_keystore, g_lkh_n_leaves);
    lkh_init(&g_lkh_tree, (const uint8_t (*)[16])g_lkh_vids, g_lkh_n_leaves);
    g_lkh_ready = true;

#ifdef HAVE_LIBOQS
    if (!enable_crypto_latency) return;
    OQS_SIG *sig = OQS_SIG_new(OQS_SIG_alg_dilithium_5);
    if (!sig) { std::cerr << "[CRYPTO] Dilithium5 not available\n"; return; }
    g_dil_pk.resize(sig->length_public_key);
    g_dil_sk.resize(sig->length_secret_key);
    g_dil_sig.resize(sig->length_signature);
    OQS_SIG_keypair(sig, g_dil_pk.data(), g_dil_sk.data());
    // pre-sign a dummy message so verify calls have a valid signature
    uint8_t dummy[64]; RAND_bytes(dummy, 64);
    size_t slen = sig->length_signature;
    OQS_SIG_sign(sig, g_dil_sig.data(), &slen, dummy, 64, g_dil_sk.data());
    g_dil_sig_len = slen;
    OQS_SIG_free(sig);
    RAND_bytes(g_hmac_key, 32);
    g_crypto_ready = true;
    g_crypto_inject_delay = (enable_crypto_latency >= 2);

    // ── Initialise TETA-Guard pipeline state ──────────────────────────────────
    // HMAC session key
    RAND_bytes(g_pipeline_session_key, SESSION_KEY_LEN);
    // Pre-sign so TimedDilVerify has a valid signature ready
    uint8_t dummy2[64]; RAND_bytes(dummy2, 64);
    dilithium5_sign(dummy2, 64,
                    g_dil_sk.data(), g_pipeline_dil_sig, &g_pipeline_dil_sig_len);
    // CA init + test cert for MeasureKEM and TimedLocationBind
    teta_ca_init();
    {
        uint8_t test_vid[16] = {};  // vehicle_id = 0 for test operations
        dilithium5_issue_cert(test_vid, g_dil_pk.data(), 0, &g_test_cert);
    }
    std::cout << "[CRYPTO] TETA-Guard pipeline initialised:\n"
                 "  [1] ML-DSA-87 / Dilithium5  — SK_Vk long-term signing keys (Eq. 3.28, Eq. 3.26)\n"
                 "      dilithium5_sign / dilithium5_verify / dilithium5_thresh\n"
                 "  [2] HMAC-SHA256(K_Vi,nk, m') — beacon auth using session key (Eq. 3.15)\n"
                 "      beacon_hmac_sign / lw_mitigate  [K_Vi,nk from ML-KEM below]\n"
                 "  [3] ML-KEM-1024 (Kyber-1024) + HQC-5 hybrid — K_Vi,nk session key (Eq. 3.15)\n"
                 "      kem_register / kem_vehicle_keygen / kem_rsu_encapsulate / kem_vehicle_decapsulate\n"
                 "  [4] LKH binary-tree key hierarchy — O(log n) revocation (Eq. 3.18)\n"
                 "      lkh_revoke_vehicle / lkh_is_revoked / lkh_get_session_key  (n="
              << g_lkh_n_leaves << ")\n"
                 "  [5] Location-binding — m'_Vk = eij‖pos‖RSSI‖τs‖nonce, signed ML-DSA-87 (Eq. 3.27–3.30)\n"
                 "      create_location_bound_report / verify_single_witness / verify_quorum\n"
                 "  [6] Haversine distance (GPS consistency gate, Eq. 3.29)\n"
                 "  All modules from .crypto_src/\n";

    // KEM is a session-setup operation — measure once at t=0
    MeasureKEM(0.0, 0, "Session_Setup", false);
    std::cout << "[CRYPTO][t=0] Keys initialised. KEM session measured."
              << (g_crypto_inject_delay ? "  [latency=2: delays injected into sim clock]" : "")
              << "\n";

    // Real per-vehicle K_{Vi,nk} keys for the live beacon sign/verify path.
    CryptoDeriveVehicleSessionKeys();
#endif
}

// ── Per-beacon measurement (call from sign path and verify path) ──────────────
// op_suffix distinguishes scenarios: "TTW"|"BSHH"|"ME"
static void CryptoMeasureBeaconSign(double sim_t, uint32_t nid, const char *suffix, bool atk)
{
    PemSimpleStageTimer __pemBeaconCryptoTimer(g_pem_beacon_crypto_stats);
#ifdef HAVE_LIBOQS
    if (!enable_crypto_latency || !g_crypto_ready) return;
    uint8_t msg[64]; RAND_bytes(msg, 64);
    char op[48];
    snprintf(op, sizeof(op), "HMAC_Sign_%s", suffix);
    CryptoRecord(sim_t, op, TimedHmacSign(msg, 64), nid, "Beacon_Send", atk);
    snprintf(op, sizeof(op), "Dilithium_Sign_%s", suffix);
    CryptoRecord(sim_t, op, TimedDilSign(msg, 64),  nid, "Beacon_Send", atk);
    g_beacon_tx_count++;
#else
    (void)sim_t; (void)nid; (void)suffix; (void)atk;
#endif
}

static void CryptoMeasureBeaconVerify(double sim_t, uint32_t nid, const char *suffix, bool atk)
{
    PemSimpleStageTimer __pemBeaconCryptoTimer(g_pem_beacon_crypto_stats);
#ifdef HAVE_LIBOQS
    if (!enable_crypto_latency || !g_crypto_ready) return;
    uint8_t msg[64]; RAND_bytes(msg, 64);
    char op[48];
    // Gate 0: RSU checks revocation status before processing the beacon
    uint8_t sender_vid[16] = {}; sender_vid[0] = (uint8_t)nid;
    CryptoRecord(sim_t, "LKH_IsRevoked", TimedLkhIsRevoked(sender_vid), nid, "Beacon_Recv", atk);
    snprintf(op, sizeof(op), "HMAC_Verify_%s", suffix);
    CryptoRecord(sim_t, op, TimedHmacVerify(msg, 64), nid, "Beacon_Recv", atk);
    snprintf(op, sizeof(op), "Dilithium_Verify_%s", suffix);
    CryptoRecord(sim_t, op, TimedDilVerify(msg, 64),  nid, "Beacon_Recv", atk);
    g_beacon_rx_count++;
#else
    (void)sim_t; (void)nid; (void)suffix; (void)atk;
#endif
}

// ── Detection gate measurements ───────────────────────────────────────────────
static void CryptoMeasureDetection(double sim_t, uint32_t nid, const char *suffix, bool me_double)
{
    PemSimpleStageTimer __pemDetectionCryptoTimer(g_pem_detection_crypto_stats);
#ifdef HAVE_LIBOQS
    if (!enable_crypto_latency || !g_crypto_ready) return;
    uint8_t msg[64]; RAND_bytes(msg, 64);
    char op[64];
    // Controller re-verifies the reported packet before alerting
    snprintf(op, sizeof(op), "Dilithium_Verify_%s_Det", suffix);
    CryptoRecord(sim_t, op, TimedDilVerify(msg, 64), nid, "Detection", true);
    if (me_double) {
        // ME: two reporters -> two verify calls
        snprintf(op, sizeof(op), "Dilithium_Verify_%s_Det2", suffix);
        CryptoRecord(sim_t, op, TimedDilVerify(msg, 64), nid, "Detection", true);
        // ME detection: verify location-bound reports from echo reporters
        CryptoRecord(sim_t, "LocBind_Verify",  TimedLocationBind(),   nid, "Detection", true);
        // Quorum check: t-of-n witnesses must independently confirm the link
        // (here n=2, t=2 — both echo reporters must pass before alert fires)
        CryptoRecord(sim_t, "LocBind_Quorum",  TimedVerifyQuorum(),   nid, "Detection", true);
    }
    CryptoRecord(sim_t, "Haversine",       TimedHaversine(), nid, "Detection", true);
    CryptoRecord(sim_t, "Freshness_Check", TimedFreshness(), nid, "Detection", true);
    // Controller threshold-signs its detection decision (domain-separated from
    // normal beacon signatures) so downstream nodes can verify the alert came
    // from a legitimate controller, not a forged detection packet.
    CryptoRecord(sim_t, "Thresh_Sign_Det",   TimedDilSignThresh(msg, 64),   nid, "Detection", true);
    CryptoRecord(sim_t, "Thresh_Verify_Det", TimedDilVerifyThresh(msg, 64), nid, "Detection", true);
#else
    (void)sim_t; (void)nid; (void)suffix; (void)me_double;
#endif
}

// ── LKH revocation measurement (post-detection mitigation) ───────────────────
static void CryptoMeasureLKH(double sim_t, uint32_t nid, uint32_t n_vehicles)
{
    PemSimpleStageTimer __pemLkhCryptoTimer(g_pem_lkh_crypto_stats);
    if (!enable_crypto_latency || !g_crypto_ready) return;
    char op[48];
    // n=16 representative for small groups, n=64 for realistic groups
    uint32_t n_rep = (n_vehicles >= 64) ? 64u : 16u;
    snprintf(op, sizeof(op), "LKH_Revoke_n%u", n_rep);
    CryptoRecord(sim_t, op, TimedLkhRevoke(n_rep), nid, "Mitigation", true);
    // After revocation the controller broadcasts KEK updates; each surviving
    // vehicle calls lkh_get_session_key() to derive its new session key.
    // Measure this per-vehicle refresh cost (one representative vehicle, nid+1).
    uint8_t survivor_vid[16] = {};
    survivor_vid[0] = (uint8_t)((nid + 1) % (g_lkh_n_leaves > 0u ? g_lkh_n_leaves : 16u));
    CryptoRecord(sim_t, "LKH_GetSessionKey",
                 TimedLkhGetSessionKey(survivor_vid), nid, "Mitigation", true);
}

// ── Write CSV ─────────────────────────────────────────────────────────────────
static void CryptoWriteL3CSV();   // forward declaration (definition in L3 block below)
// Reports the real Algorithm 3 (Eqs. 3.15-3.17) beacon verification outcome
// from AttackSendDSRCBeacon()/Rx() — runs unconditionally on every routing.cc
// execution (not gated by --latency, unlike the benchmark-only counters
// below), since this is the live wire-level crypto path, not a measurement.
static void CryptoPrintBeaconVerifyStats()
{
    std::cout << "[CRYPTO] Real beacon verify (Algorithm 3, live wire path): "
              << "accept=" << g_beacon_verify_ok_count
              << "  reject=" << g_beacon_verify_fail_count << "\n";
}

static void CryptoWriteLatencyCSV()
{
    if (!enable_crypto_latency || g_crypto_records.empty()) return;

    // Per-event log
    std::ofstream ev("crypto_latency_sumo.csv");
    ev << "sim_time_s,sim_time_end_s,latency_us,attack_scenario,operation,node_id,event_type,is_attack_event\n";
    for (auto &r : g_crypto_records)
        ev << std::fixed << std::setprecision(7)
           << r.sim_time_s   << ","
           << r.sim_time_end_s << ","
           << std::setprecision(4)
           << r.latency_us   << ","
           << r.attack_scen  << ","
           << r.operation    << ","
           << r.node_id      << ","
           << r.event_type   << ","
           << r.is_attack    << "\n";
    ev.close();

    // Per-operation summary (mean ± std)
    std::map<std::string, std::vector<double>> byOp;
    for (auto &r : g_crypto_records) byOp[r.operation].push_back(r.latency_us);

    std::ofstream sm("crypto_latency_summary.csv");
    sm << "operation,count,mean_us,std_us,min_us,max_us\n";
    for (auto &kv : byOp) {
        auto &v = kv.second;
        double sum = 0; for (double x : v) sum += x;
        double mean = sum / v.size();
        double var  = 0; for (double x : v) var += (x-mean)*(x-mean);
        double sd   = (v.size() > 1) ? std::sqrt(var/(v.size()-1)) : 0.0;
        double mn   = *std::min_element(v.begin(), v.end());
        double mx   = *std::max_element(v.begin(), v.end());
        sm << std::fixed << std::setprecision(4)
           << kv.first << "," << v.size() << "," << mean << ","
           << sd << "," << mn << "," << mx << "\n";
    }
    sm.close();

    std::cout << "\n[CRYPTO] crypto_latency_sumo.csv written    ("
              << g_crypto_records.size() << " events)\n";
    std::cout << "[CRYPTO] crypto_latency_summary.csv written  ("
              << byOp.size() << " distinct operations)\n";
    std::cout << "[CRYPTO] Beacon TX signed: " << g_beacon_tx_count
              << "   RX verified: " << g_beacon_rx_count << "\n";
    CryptoWriteL3CSV();  // no-op unless enable_crypto_latency==3
}
