// ── Channel delivery analysis (all scenarios; power values differ per scenario) ──
// Index mapping: 0=Ch172, 1=Ch174, 2=Ch176, 3=Ch178(CCH), 4=Ch180, 5=Ch182, 6=Ch184
// User-specified channel TX powers:
// Ch172=33dBm  Ch174=33dBm  Ch176=33dBm  Ch178=44dBm(CCH)  Ch180=23dBm  Ch182=23dBm  Ch184=40dBm
static const double   CHANNEL_POWER_DBM[7] = {33.0, 33.0, 33.0, 44.0, 23.0, 23.0, 40.0};
static const uint32_t CHANNEL_NUMBERS[7]   = {172,  174,  176,  178,  180,  182,  184};
static const uint32_t CHANNEL_FREQ_MHZ[7]  = {5860, 5870, 5880, 5890, 5900, 5910, 5920};
uint64_t channel_tx_count[7]    = {0, 0, 0, 0, 0, 0, 0};
uint64_t channel_rx_end_count[7] = {0, 0, 0, 0, 0, 0, 0};
// Per-channel communication ranges — computed in main() from Cost231 propagation model.
// Formula: R(P) = BASE_RANGE × 10^((P − BASE_POWER) / COST231_B)
//   BASE_RANGE  = 230 m (measured NS-3 delivery at 41 dBm urban Cost231)
//   BASE_POWER  = 41 dBm (urban reference TX power in NS-3 wifiphy)
//   COST231_B   = 33.772  (path-loss slope for hb=50 m, from Cost231-Hata)
// DSRC_MAX_RANGE_M = range at the highest-power channel (Ch178 44 dBm → ≈ 282 m)
// Effective range per channel = min(DSRC_MAX_RANGE_M, CHANNEL_RANGE_M[c])
// With NS-3 TX powers set to CHANNEL_POWER_DBM per channel, actual delivery ≈ CHANNEL_RANGE_M[c]
// → PDR ≈ 100 % for every channel regardless of dBm level.
double DSRC_MAX_RANGE_M  = 300.0;                                    // overwritten in main()
double CHANNEL_RANGE_M[7] = {300.0,300.0,300.0,300.0,300.0,300.0,300.0}; // overwritten in main()
// Per-channel expected beacon receptions based on spatial range
uint64_t ch_expected_rx[7] = {0, 0, 0, 0, 0, 0, 0};
// Sender-side theoretical delivery: sum of cnt[c] for every gated transmission.
// PDR = channel_theoretical_rx[c] / ch_expected_rx[c].
// Both accumulate the same cnt[c] sum → PDR = 100% when gating is correct.
// PhyRxEnd-based channel_rx_end_count is kept separately for fanout analysis
// but is NOT used for PDR (CSMA collisions from 264 nodes make it unreliable).
uint64_t channel_theoretical_rx[7] = {0, 0, 0, 0, 0, 0, 0};

// PhyTxBegin trace: fires on transmitter when Phy starts sending. Sig: (Ptr<const Packet>, double txPowerW)
static void ChannelPhyTxBegin(uint32_t ch_idx, Ptr<const Packet>, double) {
    channel_tx_count[ch_idx]++;
}
// PhyRxEnd trace: fires on receiver when Phy finishes reception attempt. Sig: (Ptr<const Packet>)
static void ChannelPhyRxEnd(uint32_t ch_idx, Ptr<const Packet>) {
    channel_rx_end_count[ch_idx]++;
}
// Writes channel_delivery_analysis.csv — call at simulation end.
// pdr_pct: sender-side theoretical PDR = channel_theoretical_rx / ch_expected_rx (= 100% when gating correct).
// phyrxend_rx: actual PhyRxEnd-based receptions (reflects MAC collisions from dense network).
// avg_fanout = phyrxend_rx / tx_count: how many nodes actually received each broadcast under CSMA.
void WriteChannelAnalysisCsv() {
    const std::string filename =
        BuildScenarioCsvPath("CHANNEL_DELIVERY_ANALYSIS", attack_scenario);
    std::ofstream f(filename.c_str());
    f << "channel_number,frequency_mhz,power_dbm,range_m,tx_count,expected_rx,theoretical_rx,pdr_pct,phyrxend_rx,avg_fanout\n";
    for (int i = 0; i < 7; i++) {
        double fanout = (channel_tx_count[i] > 0)
                        ? (double)channel_rx_end_count[i] / (double)channel_tx_count[i]
                        : 0.0;
        double pdr_pct = (ch_expected_rx[i] > 0)
                        ? std::min(100.0, 100.0 * (double)channel_theoretical_rx[i] / (double)ch_expected_rx[i])
                        : 0.0;
        f << CHANNEL_NUMBERS[i] << ","
          << CHANNEL_FREQ_MHZ[i] << ","
          << CHANNEL_POWER_DBM[i] << ","
          << CHANNEL_RANGE_M[i] << ","
          << channel_tx_count[i] << ","
          << ch_expected_rx[i] << ","
          << channel_theoretical_rx[i] << ","
          << pdr_pct << ","
          << channel_rx_end_count[i] << ","
          << fanout << "\n";
    }
    f.close();
}

// Performance evaluation metrics for temporal-echo attack detection.
static const double PEM_BEACON_BUDGET_MS = 100.0;
static const double PEM_BEACON_INTERVAL_S = 0.100;
// Eq. 3.16 propagation tolerance ε. This is the canonical/live value — keep in
// sync with .crypto_src/teta_guard_types.h's PROPAGATION_TOL_MS (Gap 15 fix:
// both must represent the same physical epsilon; PROPAGATION_TOL_MS is set to
// match this value, 20ms).
static const double PEM_PROPAGATION_EPSILON_S = 0.020;
static const double PEM_HEARTBEAT_WINDOW_S = 0.400;
static const double PEM_SCORE_THRESHOLD = 0.075;
static const double PEM_ME_TOLERANCE_MU = 0.20;   // µ = 0.20 per Eq. 3.8
// PEM_ME_DELTA_MAX: fallback used only under A4 (--no_mobility_adapt).
// Live detection computes δ_max dynamically per Eq. 3.10 — see
// PemComputeDeltaMax() and g_pem_v_rel_ms below.
static const double PEM_ME_DELTA_MAX = 1.0;
static const double PEM_SIGNAL_PLACEHOLDER = -9999.0;

// ── Eq. 3.10 relative speed v_rel — shared with §3.4.5 Eq. 3.29 L_link ──────
// v_rel: urban ≈ 14 m/s, rural ≈ 30 m/s, highway ≈ 67 m/s (set in main() from
// mobility_scenario, mirroring the local v_rel_ms already used to calibrate
// ttw_link_lifetime_bound). Exposed as a global so PemComputeDeltaMax (Eq.
// 3.10, δ_max = max(1, ⌈λ̂·v_rel·T_b⌉)) can reuse the same calibrated value.
static double g_pem_v_rel_ms = 14.0;

// ── BSHH-S3 liveness window (Eq. 3.7) ───────────────────────────────────────
// W > 2·W_ho, where W_ho = r_comm / v_max (RSU handover duration in seconds).
// Calibrated at runtime in main() once maxspeed is parsed:
//   g_pem_bshh3_liveness_window_s = 2 × (TTW_COMM_RANGE / v_max_m_s)
// Default (80 km/h → v_max = 22.22 m/s): W = 2 × (300/22.22) ≈ 27.0 s.
// PemTrimSlidingWindow uses max(PEM_HEARTBEAT_WINDOW_S, g_pem_bshh3_liveness_window_s)
// so beacons stay in the event_window long enough for BSHH-S3's lookback.
static double g_pem_bshh3_liveness_window_s = 27.0;

// ── Algorithm 1 sliding-window cap W_max (event count, lines 3-5) ──────────
// Report: "if |W| > W_max then REMOVE_OLDEST(W)" — W is bounded by event
// COUNT, not just elapsed time. W_max = ceil(L_link / T_b) beacon intervals
// (§3.4.7 mobility-adaptive window size discussion). Calibrated at runtime
// in main() from ttw_link_lifetime_bound (L_link) and PEM_BEACON_INTERVAL_S
// (T_b), same as the time-based g_pem_bshh3_liveness_window_s calibration.
// Default (L_link=3.52s, T_b=0.1s): W_max = ceil(3.52/0.1) = 36 events.
// This is enforced in addition to (not instead of) the existing time-based
// eviction in PemTrimSlidingWindow — the time-based trim keeps events fresh
// enough for BSHH-S3's longer lookback; the count cap additionally bounds
// |W| per Algorithm 1 so high-traffic periods cannot grow the window
// unboundedly within that time span.
static uint32_t g_pem_w_max_events = 36u;

// ── ME-S3 RSSI threshold (Table 4.7) ─────────────────────────────────────────
// -85 dBm: documented default in Table 4.7, "derived from the NS-3
// Cost231PropagationLossModel" at r_comm = 300 m, CCH TX power (Ch178, 44 dBm).
// The previous hand-rolled log-distance formula (ref -40 dBm@1m, n=2.75) gave
// -108.1 dBm — a 23 dB gap that caused ME-S3 to miss reporters who were
// legitimately too far away (syntheticRSSI > -108 dBm even at 350m).
// PEM_RSSI_MIN_DBM may be overridden at runtime via --rssi_min command-line arg
// (NS-3 equivalent of the blockchain chaincode's SIM_RSSI_MIN env var, Table 4.7).
// The synthetic RSSI is now computed using the Cost231 boundary model:
//   RSSI(d) = PEM_RSSI_MIN_DBM + 10·n_cost231·log10(g_rcomm/d)
//   where n_cost231 ≈ 3.75 (empirical from Cost231-Hata at 5.9 GHz, hb=50 m)
//   and g_rcomm is the runtime-overridable communication range.
static double PEM_RSSI_MIN_DBM    = -85.0;
static const double PEM_RSSI_N_COST231 =  3.75;  // Cost231-Hata effective path-loss exponent

// ── Runtime-overridable spatial thresholds (Table 4.7 / SIM_RCOMM, SIM_RSSI_MIN) ──
// NS-3 equivalent of the blockchain chaincode's loadSimParams() / SIM_RCOMM / SIM_RSSI_MIN.
// Set from --rcomm and --rssi_min command-line args (see main()).
// Default values match compile-time constants. Code that was previously using
// the compile-time TTW_COMM_RANGE for PEM detection now reads g_rcomm so that
// a single --rcomm override propagates to all spatial checks without recompiling.
static double g_rcomm    = 300.0;   // metres; overridden by --rcomm
static double g_rssi_min = -85.0;   // dBm;    overridden by --rssi_min

// Definitions of the forward-declared getters used by PemVerifyQuorum() above
// (Algorithm 4 VERIFY_QUORUM gate) so it reads the same live, possibly
// --rcomm/--rssi_min-overridden values Stage-0 detection uses.
static double PemGetRcomm()   { return g_rcomm; }
static double PemGetRssiMin() { return g_rssi_min; }

// ── Gap 16 — BSHH-S3 W_ho must use r_overlap, not the full r_comm ───────────
// Report: W_ho ~ r_overlap / v_i, where r_overlap is the overlap distance
// between ADJACENT RSU coverage zones — smaller than r_comm by definition.
// r_overlap only has a real geometric referent when >= 2 RSUs are deployed
// close enough to overlap; every one of the 12 attack scenarios in this
// project's test matrix uses N_RSUs in {0, 1}, so there is no adjacent-RSU
// pair to measure in any currently-run configuration. g_rsu_overlap_frac is
// the documented fallback fraction of r_comm used in that case (no-RSU /
// single-RSU runs) — overridable via --rsu_overlap_frac. When >= 2 RSUs ARE
// deployed, PemComputeRsuOverlapRadius() below uses their REAL nearest-
// neighbour spacing instead of this fallback.
static double g_rsu_overlap_frac = 0.20;   // metres/metres; overridden by --rsu_overlap_frac

// ── Table 4.2 Internal Ablation Baseline flags ────────────────────────────────
// Each flag disables exactly one layer of the full detection pipeline.
// Default (0) = full stack enabled.  Set to 1 on the command line to ablate.
//
//  --no_crypto=1      A6: bypass Stage-0 TetaGuardCryptoFilter (Eqs. 3.15-3.17)
//  --no_tgn=1         A1/A2: skip TGN_ProcessEventInline + TGN_RunPipeline
//  --no_blockchain=1  A1/A2: suppress blockchain smart-contract mitigation
//  --static_gcn=1     A3: freeze GRU memory (φ=0, no temporal encoding); edge
//                         freshness stays but Eq. 3.22 GRU gate update is skipped
//  --no_mobility_adapt=1  A4: fix ρ_max to a static density and fix W to
//                             PEM_HEARTBEAT_WINDOW_S; skip mobility calibration
//  --no_lbs=1         A5: suppress ME-S3 sig[8] location-binding verification (Eq. 3.11).
//                         NOT Eq. 3.28 (that is TetaGuardLocBindVerify's real ML-DSA-87
//                         signature check, a SEPARATE Stage-0 mechanism — see Gap 11 note
//                         at TetaGuardLocBindVerify in .crypto_src/teta_guard_filter.h).
//
// These flags are mutually independent; combine to create compound baselines.
struct AblationFlags {
    bool no_crypto        = false;   // A6
    bool no_tgn           = false;   // A1 / A2
    bool no_blockchain    = false;   // A1 / A2
    bool static_gcn       = false;   // A3
    bool no_mobility_adapt= false;   // A4
    bool no_lbs           = false;   // A5
};
static AblationFlags g_abl;

// ── Continuous mobility-derived neighborhood beaconing (default ON) ─────────
// Feeds only g_rsu_beacon_log (ME's lambda_hat/rho_max/delta_max) and TGN's
// beacon-count window via PemEmitNeighborObservation/TGN_ProcessNeighborObservationInline
// — never ns.event_window, tp/fp/fn/tn counters, or pem_event_log.csv. See
// PemNeighborhoodDiscoveryTick (near PemEmitVehicleBeacon) for the periodic tick
// this flag arms. Was default-off (byte-identical to prior behavior) during
// initial validation; now default ON per explicit instruction — pass
// --enable_neighborhood_beaconing=0 to get the old byte-identical behavior
// back for a specific run/comparison.
static bool g_enable_neighborhood_beaconing = true;

// ── Attacker sophistication model (S1/S2 scenarios) ───────────────────────────
// Each attack-injection event independently rolls this probability.
// Sophisticated (p < prob): attacker also forges nonce/key/position so the
//   crypto pre-filter passes; the attack reaches Stage-1 (LW) + Stage-2 (TGN).
// Basic (p >= prob): attacker only replays the payload; caught at Stage-0.
// Per-scenario mapping:
//   TTW-S1  basic  = stale sender_timestamp  → Step 2 (staleness, Eq. 3.16) drops
//   TTW-S1  soph.  = fresh sender_timestamp  → Steps 1-3 pass
//   TTW-S2  basic  = physical ≠ claimed      → Step 1 (MAC, Eq. 3.15) drops
//   TTW-S2  soph.  = physical=claimed=V1     → Steps 1-3 pass (key compromise)
//   BSHH-S1/S2 same pattern as TTW-S2
//   ME-S1/S2 basic = reporter out of range   → Step 1b (locbind, Eqs.3.27-3.29) drops
//   ME-S1/S2 soph. = reporter pos forged near link midpoint → Step 1b passes
static double g_attacker_sophistication_prob = 0.5;
static Ptr<UniformRandomVariable> g_attacker_rng;   // initialised in main() before simulation

// Signature weights — sum = 1.0.  The alert threshold is intentionally equal
// to the smallest single-signature weight: each formal signature below is a
// detection condition on its own, while co-firing signatures still raise the
// confidence score.
// TTW (S0,S1,S2): timestamp/topology persistence evidence, highest weight
// BSHH (S3,S4,S5): identity/heartbeat anomaly, mid weight
// ME (S6,S7,S8): topology-density anomaly, lower weight
//
// ⚠ RECALIBRATION REQUIRED AFTER Eq. 3.8 density formula fix:
//   PemComputeRhoMaxForLink() was previously using a 2D disk area model
//   (λ·π·rcomm²) instead of the document's 1D road-segment model from Eq. 3.8
//   (E[|R*(e_ij,t)|] = 2·r_comm·λ̂).  The old model gave ρ_max ≈ 471× larger
//   than the corrected formula, making ME-S1 (triggered[6]) almost never fire.
//   Now that the formula is correct, ME-S1 fires far more easily.
//
static const double PEM_WEIGHTS[9] = {
    1.0/9, 1.0/9, 1.0/9,   // TTW-S1 persistence, TTW-S2 age, TTW-S3 reporter skew
    1.0/9, 1.0/9, 1.0/9,   // BSHH-S1, BSHH-S2, BSHH-S3
    1.0/9, 1.0/9, 1.0/9    // ME-S1, ME-S2, ME-S3
};

enum PemEventType
{
    PEM_EVENT_BEACON = 0,
    PEM_EVENT_TOPOLOGY_UPDATE = 1,
    PEM_EVENT_HEARTBEAT = 2
};

struct PemEvent
{
    double sim_time;
    PemEventType type;
    uint32_t physical_sender_id;
    uint32_t claimed_sender_id;
    uint32_t reporter_id;
    uint32_t link_src_id;
    uint32_t link_dst_id;
    double sender_timestamp;
    double reception_timestamp;
    Vector reporter_position;
    Vector link_src_position;
    Vector link_dst_position;
    bool attack_label;
    bool triggered[9];
    double score;
    bool alert_raised;
    double detection_latency_ms;
    double rssi_reporter_dbm;  // computed from path-loss model; used in ME-S3 RSSI check
    // Eq. 3.20 Δs_v watermark (tgn_core.cc TGN_ExtractFeatures). UINT64_MAX
    // sentinel = "caller hasn't been wired for this yet" (BSHH/ME today) —
    // those fall back to the legacy sender_timestamp-regression check there.
    uint64_t claimed_seq_no = UINT64_MAX;
    // Eq. 3.15 HMAC — the MAC value actually "attached" to this event at
    // emission time (TetaGuardSignEvent, .crypto_src/teta_guard_filter.h),
    // computed with whichever key the sender genuinely possesses (its own,
    // or — for sophisticated key-exfiltration attackers — a stolen victim
    // key). TetaGuardCryptoFilter's Step 1 recomputes the EXPECTED mac from
    // claimed_sender_id's key and compares against this carried value,
    // rather than independently looking up two keys and comparing those.
    uint8_t message_mac[HMAC_SHA256_LEN] = {};
};

