static std::string
PemEventTypeToString(PemEventType type)
{
    switch (type)
    {
        case PEM_EVENT_BEACON:
            return "beacon";
        case PEM_EVENT_TOPOLOGY_UPDATE:
            return "topology_update";
        case PEM_EVENT_HEARTBEAT:
            return "heartbeat";
        default:
            return "unknown";
    }
}

static std::string
PemGetLinkKey(uint32_t srcId, uint32_t dstId)
{
    const uint32_t a = std::min(srcId, dstId);
    const uint32_t b = (srcId < dstId) ? dstId : srcId;
    return std::to_string(a) + "_" + std::to_string(b);
}

struct PemEventOlderThan {
    double now; double maxAge;
    PemEventOlderThan(double n, double a) : now(n), maxAge(a) {}
    bool operator()(const PemEvent& e) const {
        return (now - e.reception_timestamp) > maxAge;
    }
};

// ── §3.4.2 Eq. 3.7 — W must be mobility-ADAPTIVE, not a startup-only value ──
// The report requires W = 2·W_ho to be "updated when vehicle speed changes"
// during the simulation. Previously this was calibrated ONCE at t=0 from the
// CLI --maxspeed parameter and never revisited, so a vehicle speeding up or
// slowing down mid-run had no effect on W. PemRecalibrateBshh3Window() re-reads
// every vehicle's LIVE MobilityModel velocity and recomputes W = 2·r_comm/v_max
// from the actual current fastest vehicle, then reschedules itself — see the
// periodic Simulator::Schedule loop installed in main().
static const double PEM_BSHH3_RECAL_PERIOD_S = 1.0;   // recalibration cadence

// Gap 16 — r_overlap: the RSU-to-RSU coverage overlap zone that W_ho is
// actually defined over (W_ho ~ r_overlap / v_i), not the full r_comm.
// When >= 2 RSUs are deployed, this is a REAL geometric quantity: the
// overlap between two adjacent RSUs' coverage discs is
// max(0, 2*r_comm - spacing), where spacing is the distance between them
// (spacing >= 2*r_comm means their coverage discs don't touch at all, so
// overlap = 0). Uses the NEAREST RSU pair (smallest spacing = largest/most
// conservative overlap a vehicle could actually be handing over across).
// When < 2 RSUs are deployed (true for every scenario in this project's
// current 12-scenario test matrix — all use N_RSUs in {0,1}), there is no
// adjacent-RSU pair to measure, so this falls back to the documented
// g_rsu_overlap_frac * r_comm assumption (default 0.20, i.e. 60m at the
// default r_comm=300m) rather than silently substituting the full r_comm.
static double
PemComputeRsuOverlapRadius()
{
    if (RSU_Nodes.GetN() < 2u)
    {
        return g_rsu_overlap_frac * g_rcomm;
    }

    double nearestSpacing = -1.0;
    for (uint32_t i = 0; i < RSU_Nodes.GetN(); ++i)
    {
        Ptr<MobilityModel> mi = RSU_Nodes.Get(i)->GetObject<MobilityModel>();
        if (!mi) continue;
        for (uint32_t j = i + 1; j < RSU_Nodes.GetN(); ++j)
        {
            Ptr<MobilityModel> mj = RSU_Nodes.Get(j)->GetObject<MobilityModel>();
            if (!mj) continue;
            const double d = PemDistance2d(mi->GetPosition(), mj->GetPosition());
            if (nearestSpacing < 0.0 || d < nearestSpacing) nearestSpacing = d;
        }
    }
    if (nearestSpacing < 0.0)
    {
        // No RSU pair had a valid MobilityModel — fall back to the documented
        // fraction rather than treating this as a real zero-spacing overlap.
        return g_rsu_overlap_frac * g_rcomm;
    }

    const double overlap = 2.0 * g_rcomm - nearestSpacing;
    return (overlap > 0.0) ? overlap : 0.0;
}

static void
PemRecalibrateBshh3Window()
{
    // A4 (--no_mobility_adapt): frozen at startup value; do not reschedule.
    if (g_abl.no_mobility_adapt) return;

    double vMaxObservedMs = 0.0;
    for (uint32_t i = 0; i < Vehicle_Nodes.GetN(); ++i)
    {
        Ptr<MobilityModel> m = Vehicle_Nodes.Get(i)->GetObject<MobilityModel>();
        if (!m) continue;
        Vector v = m->GetVelocity();
        const double speed = std::sqrt(v.x * v.x + v.y * v.y);
        if (speed > vMaxObservedMs) vMaxObservedMs = speed;
    }

    if (vMaxObservedMs > 0.0)
    {
        // Gap 16: W_ho = r_overlap / v_max, not r_comm / v_max.
        g_pem_bshh3_liveness_window_s = 2.0 * PemComputeRsuOverlapRadius() / vMaxObservedMs;
    }
    // If no vehicle currently has nonzero velocity (e.g. before mobility starts
    // or all vehicles momentarily stopped), keep the last-known W rather than
    // dividing by zero / snapping to a default — matches "updated when speed
    // changes," not "reset when speed is unknown."

    if (Simulator::Now().GetSeconds() + PEM_BSHH3_RECAL_PERIOD_S < simTime)
    {
        Simulator::Schedule(Seconds(PEM_BSHH3_RECAL_PERIOD_S), &PemRecalibrateBshh3Window);
    }
}

// ── §3.4.3 — TGN γ (Eq. 3.21) and W_max (§3.4.3 sliding window) must also be
// mobility-ADAPTIVE, not startup-only values. TGN_Init() (.tgn_src/tgn_core.cc)
// previously derived TGN_GAMMA and TGN_WMAX once from the CLI --tgn_l_link
// value and never revisited them, so a vehicle speeding up or slowing down
// mid-run had no effect on the TGN's decay rate or retention window — unlike
// the BSHH-S3 liveness window above, which PemRecalibrateBshh3Window() already
// keeps in sync with live vehicle velocity. This mirrors that same pattern for
// the TGN side: re-read every vehicle's LIVE MobilityModel velocity, recompute
// the live link-lifetime bound L_link = 2*r_comm/v_max (same relation TGN_Init
// uses via --tgn_l_link, Eq. 3.29/3.31), re-derive γ and W_max from it
// (Eq. 3.21's γ_init = L_link/(2*T_b*ln2); W_max = L_link/T_b), and reschedule.
// TGN_GAMMA/TGN_WMAX are read directly (not through a per-instance copy) by
// TGNDetector's edge-freshness and window-trim logic, so updating these
// globals takes effect on the very next event processed.
static const double TGN_RECAL_PERIOD_S = 1.0;

static void
TGN_RecalibrateMobility()
{
    // A4 (--no_mobility_adapt): frozen at TGN_Init() value; do not reschedule.
    if (g_abl.no_mobility_adapt) return;
    // Nothing to recalibrate if the TGN isn't running online (A1/A2 --no_tgn).
    if (!g_tgn_online_mode) return;

    double vMaxObservedMs = 0.0;
    for (uint32_t i = 0; i < Vehicle_Nodes.GetN(); ++i)
    {
        Ptr<MobilityModel> m = Vehicle_Nodes.Get(i)->GetObject<MobilityModel>();
        if (!m) continue;
        Vector v = m->GetVelocity();
        const double speed = std::sqrt(v.x * v.x + v.y * v.y);
        if (speed > vMaxObservedMs) vMaxObservedMs = speed;
    }

    if (vMaxObservedMs > 0.0)
    {
        const double lLinkLive = 2.0 * TTW_COMM_RANGE / vMaxObservedMs;
        TGN_GAMMA = lLinkLive / (2.0 * TGN_BEACON_INTERVAL * std::log(2.0));
        TGN_WMAX  = (int)(lLinkLive / TGN_BEACON_INTERVAL);
        if (TGN_WMAX < 1) TGN_WMAX = 1;
        // Keep g_tgn_params in sync too, since TGN_RunPipeline's summary/CSV
        // output reports gamma/wmax from there.
        g_tgn_params.gamma = TGN_GAMMA;
        g_tgn_params.wmax  = TGN_WMAX;
    }
    // If no vehicle currently has nonzero velocity, keep the last-known
    // gamma/W_max rather than dividing by zero — matches "updated when speed
    // changes," not "reset when speed is unknown" (same as the BSHH-S3 case).

    if (Simulator::Now().GetSeconds() + TGN_RECAL_PERIOD_S < simTime)
    {
        Simulator::Schedule(Seconds(TGN_RECAL_PERIOD_S), &TGN_RecalibrateMobility);
    }
}

static void
PemTrimSlidingWindow(PemNodeLWState& ns, double nowSeconds)
{
    // §3.1.3: trim runs at each trusted node nk on its local event_window.
    // Keep events within the larger of the two windows so BSHH-S3 (Eq. 3.7, W≈27s)
    // can look back further than the BSHH-S1/S2 window (PEM_HEARTBEAT_WINDOW_S=0.4s).
    const double trim_window = (g_pem_bshh3_liveness_window_s > PEM_HEARTBEAT_WINDOW_S)
                             ? g_pem_bshh3_liveness_window_s : PEM_HEARTBEAT_WINDOW_S;
    while (!ns.event_window.empty() &&
           (nowSeconds - ns.event_window.front().reception_timestamp) > trim_window)
    {
        ns.event_window.pop_front();
    }

    // Algorithm 1 lines 3-5: if |W| > W_max then REMOVE_OLDEST(W).
    // Count-based cap on top of the time-based trim above — bounds the
    // window size directly instead of relying solely on elapsed time.
    while (ns.event_window.size() > g_pem_w_max_events)
    {
        ns.event_window.pop_front();
    }

    // Evict stale link-report entries older than L_link (Eq. 3.31, §3.4.7)
    // to prevent false-positive TTW-S3 alerts in long runs.
    const double w_max_seconds = (ttw_link_lifetime_bound > 0.0)
                                     ? ttw_link_lifetime_bound
                                     : 43.0;  // urban fallback
    for (std::map<std::string, std::vector<PemEvent>>::iterator kv =
             ns.link_report_history.begin();
         kv != ns.link_report_history.end();
         ++kv)
    {
        std::vector<PemEvent>& vec = kv->second;
        vec.erase(
            std::remove_if(vec.begin(), vec.end(),
                           PemEventOlderThan(nowSeconds, w_max_seconds)),
            vec.end());
    }
}

// Trims g_rsu_beacon_log (Issue 11 fix) using the SAME time window as
// PemTrimSlidingWindow's event_window trim, for consistency with the
// codebase's existing choice of "how far back counts as current" — this
// intentionally reuses that constant rather than introducing a new tunable.
// This is the only place g_rsu_beacon_log is trimmed; it is never subject to
// event_window's count cap (g_pem_w_max_events) or link_report_history's
// L_link eviction, since those bound signature-detector state, not this
// density estimator's independent log.
static void
PemTrimRsuBeaconLog(double nowSeconds)
{
    const double trim_window = (g_pem_bshh3_liveness_window_s > PEM_HEARTBEAT_WINDOW_S)
                             ? g_pem_bshh3_liveness_window_s : PEM_HEARTBEAT_WINDOW_S;
    while (!g_rsu_beacon_log.empty() &&
           (nowSeconds - g_rsu_beacon_log.front().reception_timestamp) > trim_window)
    {
        g_rsu_beacon_log.pop_front();
    }
}

static double
PemDistance2d(const Vector& a, const Vector& b)
{
    return std::sqrt(std::pow(a.x - b.x, 2.0) +
                     std::pow(a.y - b.y, 2.0));
}

// Include per-trusted-node crypto pre-filter here — all required symbols
// (PemEvent, AttackScenarioId, TTW_COMM_RANGE, PemDistance2d, etc.) are
// defined above; PemWriteRunSummaryCsv and PemCryptoPreFilter below need it.
#include ".crypto_src/teta_guard_filter.h"

static std::set<uint32_t>
PemCollectReportersForLink(const PemEvent& event, const PemNodeLWState& ns)
{
    std::set<uint32_t> reporters;
    const std::string linkKey = PemGetLinkKey(event.link_src_id, event.link_dst_id);
    std::map<std::string, std::vector<PemEvent>>::const_iterator linkIt =
        ns.link_report_history.find(linkKey);
    if (linkIt != ns.link_report_history.end())
    {
        for (std::vector<PemEvent>::const_iterator it = linkIt->second.begin();
             it != linkIt->second.end();
             ++it)
        {
            reporters.insert(it->reporter_id);
        }
    }
    reporters.insert(event.reporter_id);
    return reporters;
}

// ── λ̂(t): instantaneous vehicle density from RSU/trusted-node-observed beacons ──
// Eq. 3.8 requires λ̂(t) to be "estimated from RSU-observed beacon rates," not
// queried from simulator ground truth (e.g. enumerating Vehicle_Nodes.GetN()
// and reading every vehicle's live MobilityModel position). This function only
// ever looks at ns.event_window — the PEM_EVENT_BEACON entries THIS trusted
// node has actually received and logged — so a vehicle that hasn't beaconed
// within the retained window contributes nothing to λ̂, exactly like a real
// RSU tallying its own beacon reception log rather than querying an oracle.
// (The position value carried inside each beacon event is the sender's own
// self-reported GPS position, i.e. what a real DSRC BSM payload would
// contain — not a privileged simulator lookup performed by the detector.)
// Shared by ME-S1 (Eq. 3.8, ρ_max) and ME-S2's δ_max (Eq. 3.10).
static double
PemComputeLambdaHat(const PemEvent& event, const PemNodeLWState& ns)
{
    // Issue 11 fix: source from g_rsu_beacon_log (dedicated, beacon-only,
    // independently-trimmed) instead of ns.event_window (shared, mixed-type,
    // trimmed for the LW signature detector's own lookback needs — e.g.
    // BSHH-S3). `ns` is retained in the signature only because both callers
    // (PemComputeRhoMaxForLink, PemComputeDeltaMax) already receive it and
    // pass it through; it is otherwise unused here now.
    (void)ns;
    const double corridorLength = 2.0 * TTW_COMM_RANGE;   // metres
    if (corridorLength <= 0.0) return 0.0;

    std::set<uint32_t> vehiclesNearLink;
    for (std::deque<PemEvent>::const_iterator w = g_rsu_beacon_log.begin();
         w != g_rsu_beacon_log.end();
         ++w)
    {
        // g_rsu_beacon_log only ever holds PEM_EVENT_BEACON entries by
        // construction (see population site in PemEvaluateEvent), but this
        // guard is kept for defensive clarity.
        if (w->type != PEM_EVENT_BEACON)
        {
            continue;
        }

        const double dToSrc = PemDistance2d(w->reporter_position,
                                            event.link_src_position);
        const double dToDst = PemDistance2d(w->reporter_position,
                                            event.link_dst_position);
        if (std::min(dToSrc, dToDst) <= TTW_COMM_RANGE)
        {
            vehiclesNearLink.insert(w->claimed_sender_id);
        }
    }

    // lambda_hat = observed (beaconed) vehicles / corridor length  (vehicles / m)
    return static_cast<double>(vehiclesNearLink.size()) / corridorLength;
}

static uint32_t
PemComputeRhoMaxForLink(const PemEvent& event, const PemNodeLWState& ns)
{
    // A4 (--no_mobility_adapt): return a fixed ρ_max of 4 reporters (two legitimate
    // endpoints plus one RSU forwarder plus one margin).  Mobility-derived λ̂(t) is
    // not computed so the threshold does not adapt to vehicle density.
    if (g_abl.no_mobility_adapt) return 4u;

    // Eq. 3.8 expected reporter count: E[|R*(e_ij, t)|] = 2 * r_comm * lambda(t)
    // lambda(t) is vehicles per metre along the road segment — this is the
    // correct road-segment linear density model from Eq. 3.8, not the 2-D
    // disk area model.
    const double lambdaHat = PemComputeLambdaHat(event, ns);

    // rhoMax = ⌊(1+µ) · 2·r_comm · λ̂(t)⌋  (Eq. 3.8, µ = PEM_ME_TOLERANCE_MU = 0.20)
    uint32_t rhoMax =
        static_cast<uint32_t>(
            std::floor((1.0 + PEM_ME_TOLERANCE_MU) * 2.0 * TTW_COMM_RANGE * lambdaHat));

    // A physical link has two endpoints; below that, the density estimate is
    // under-sampled rather than physically meaningful.
    return (rhoMax < 2u) ? 2u : rhoMax;
}

// ── δ_max(t): mobility-consistent path-growth bound (Eq. 3.10) ──────────────
// δ_max = max(1, ⌈λ̂·v_rel·T_b⌉) — the expected number of new relay vehicles
// entering communication range of both endpoints within one beacon interval.
// Computed dynamically from the same locally-observed λ̂(t) as ME-S1 (Eq. 3.8)
// and the mobility-scenario relative speed g_pem_v_rel_ms (§3.4.5 Eq. 3.29),
// replacing the previous PEM_ME_DELTA_MAX=1.0 compile-time constant.
static double
PemComputeDeltaMax(const PemEvent& event, const PemNodeLWState& ns)
{
    // A4 (--no_mobility_adapt): fixed δ_max=1, matching the report's own
    // observation that δ_max collapses to 1 "across all realistic SDVN
    // conditions" — consistent with A4 freezing all mobility-adaptive terms.
    if (g_abl.no_mobility_adapt) return PEM_ME_DELTA_MAX;

    const double lambdaHat = PemComputeLambdaHat(event, ns);
    const double raw = lambdaHat * g_pem_v_rel_ms * PEM_BEACON_INTERVAL_S;
    const double delta = std::ceil(raw);
    return (delta > 1.0) ? delta : 1.0;
}

// Gap 14 fix — |P(Vi,Vj)|_t (Eq. 3.9) is the number of DISTINCT PATHS the
// controller's topology graph infers between the link endpoints, not merely a
// count of distinct reporters. The previous implementation (pathCount = 1 +
// number of third-party reporters) over-counts whenever two reporters are
// themselves within range of each other but not actually forming distinct
// relay routes to both endpoints, and under/over-counts multi-hop chains
// (e.g. Vi -> Vk -> Vm -> Vj) that a real graph traversal would enumerate
// explicitly. This builds the small local graph THIS trusted node can infer
// from its own link_report_history (nodes = link endpoints + every reporter
// that has witnessed this link, positioned at their reported location; edges
// = within-comm-range pairs, plus the direct observed link_src<->link_dst
// edge) and counts actual distinct simple paths via DFS.
static uint32_t
PemComputeReporterInferredPathCount(const PemEvent& event, const PemNodeLWState& ns)
{
    const std::string linkKey = PemGetLinkKey(event.link_src_id, event.link_dst_id);

    // node id -> most recently known position, from link_report_history plus
    // the current event and both link endpoints.
    //
    // FP fix (ME-S2 false-positive investigation): a report whose
    // physical_sender_id IS one of the link's own two endpoints is a direct
    // self-report — the endpoint vouching for its own real link — not an
    // independent third-party witness, even when it reaches this trusted
    // node via an RSU relay (reporter_id == rsu_id, a transport identity,
    // not a separate physical vantage point). Adding reporter_id as its own
    // graph node in that case creates a phantom node co-located with (or
    // near) the reporting endpoint, inflating |P(Vi,Vj)| with a route that
    // was never physically observed. Same structural self-report test
    // already used elsewhere in this file (Stage-0's is_self_report_pre in
    // teta_guard_filter.h, Stage-1's is_self_report_me2 above) — uses only
    // physical_sender_id/link endpoint IDs, fields a real detector already
    // has from the received report, not a simulator ground-truth oracle.
    std::map<uint32_t, Vector> nodePos;
    nodePos[event.link_src_id] = event.link_src_position;
    nodePos[event.link_dst_id] = event.link_dst_position;
    const bool eventIsSelfReport =
        (event.physical_sender_id == event.link_src_id) ||
        (event.physical_sender_id == event.link_dst_id);
    if (!eventIsSelfReport)
    {
        nodePos[event.reporter_id] = event.reporter_position;
    }

    std::map<std::string, std::vector<PemEvent>>::const_iterator linkIt =
        ns.link_report_history.find(linkKey);
    if (linkIt != ns.link_report_history.end())
    {
        for (std::vector<PemEvent>::const_iterator it = linkIt->second.begin();
             it != linkIt->second.end();
             ++it)
        {
            const bool histIsSelfReport =
                (it->physical_sender_id == it->link_src_id) ||
                (it->physical_sender_id == it->link_dst_id);
            if (!histIsSelfReport)
            {
                nodePos[it->reporter_id] = it->reporter_position;
            }
        }
    }

    // Build adjacency: any two distinct nodes within TTW_COMM_RANGE of each
    // other are connected, plus the direct link_src<->link_dst edge (the
    // physically observed link itself) is always present.
    std::vector<uint32_t> nodeIds;
    for (std::map<uint32_t, Vector>::const_iterator it = nodePos.begin();
         it != nodePos.end(); ++it)
    {
        nodeIds.push_back(it->first);
    }
    std::map<uint32_t, std::set<uint32_t>> adj;
    for (size_t i = 0; i < nodeIds.size(); ++i)
    {
        for (size_t j = i + 1; j < nodeIds.size(); ++j)
        {
            const uint32_t a = nodeIds[i];
            const uint32_t b = nodeIds[j];
            const bool isDirectEndpointPair =
                (a == event.link_src_id && b == event.link_dst_id) ||
                (a == event.link_dst_id && b == event.link_src_id);
            if (isDirectEndpointPair ||
                PemDistance2d(nodePos[a], nodePos[b]) <= TTW_COMM_RANGE)
            {
                adj[a].insert(b);
                adj[b].insert(a);
            }
        }
    }

    // DFS: count distinct simple paths from link_src_id to link_dst_id.
    // Bounded by construction — node count here is at most a handful of
    // reporters plus 2 endpoints, matching this project's scale.
    uint32_t pathCount = 0;
    std::set<uint32_t> visited;
    std::function<void(uint32_t)> dfs = [&](uint32_t cur)
    {
        if (cur == event.link_dst_id)
        {
            pathCount++;
            return;
        }
        visited.insert(cur);
        for (std::set<uint32_t>::const_iterator it = adj[cur].begin();
             it != adj[cur].end(); ++it)
        {
            if (visited.count(*it)) continue;
            dfs(*it);
        }
        visited.erase(cur);
    };
    visited.insert(event.link_src_id);
    dfs(event.link_src_id);

    return (pathCount > 0) ? pathCount : 1u;
}

static std::string
PemTriggeredSignatureString(const bool triggered[9])
{
    static const char* labels[9] = {
        "TTW-S1", "TTW-S2", "TTW-S3",
        "BSHH-S1", "BSHH-S2", "BSHH-S3",
        "ME-S1", "ME-S2", "ME-S3"
    };

    std::ostringstream out;
    bool first = true;
    for (uint32_t i = 0; i < 9; ++i)
    {
        if (triggered[i])
        {
            if (!first)
            {
                out << "|";
            }
            out << labels[i];
            first = false;
        }
    }
    if (first)
    {
        return "none";
    }
    return out.str();
}

static void
PemWriteCsvHeaderIfNeeded(const std::string& filename,
                          const std::string& header,
                          bool& alreadyWritten)
{
    if (alreadyWritten)
    {
        return;
    }

    // DESIGN DECISION — always truncate, never append across runs.
    //
    // The original implementation (now removed) checked whether the file was
    // empty before writing the header, allowing multiple simulation runs to
    // append rows to the same CSV without duplicate headers. That design was
    // intentional for multi-seed batch runs piped into one file.
    //
    // It was replaced with always-truncate behaviour because:
    //   1. Each ./waf --run invocation is a fresh experiment — stale rows
    //      from a previous run with different parameters silently corrupt
    //      statistics if the file is not cleared.
    //   2. The 5-run batch script (run_5_experiments.sh) copies each run's
    //      CSV to a per-seed directory before the next run overwrites it,
    //      so cross-run accumulation is handled externally.
    //   3. The alreadyWritten flag ensures the header fires exactly once
    //      per in-process simulation, preventing duplicate headers within
    //      a single run when multiple PEM events trigger writes.
    //
    // If you need multi-run append (e.g. streaming to a live dashboard),
    // restore the ifstream check below and remove the ios::trunc flag.
    std::ofstream fout(filename.c_str(), std::ios::out | std::ios::trunc);
    fout << header << "\n";
    alreadyWritten = true;
}

// PemBuildEventCsvRow — build one pem_event_log.csv row (the exact column
// layout crypto_pipeline.cc's load_pem()/csv_col() already parses, documented
// there as columns 0-21). Factored out of PemWriteEventCsv so the file writer
// and the live wire protocol (PemLiveSend's "E:" lines, see PemEvaluateEvent)
// build this from one place. No trailing newline — callers own that.
static std::string
PemBuildEventCsvRow(const PemEvent& event)
{
    std::ostringstream row;
    row << event.sim_time << ","
        << PemEventTypeToString(event.type) << ","
        << event.physical_sender_id << ","
        << event.claimed_sender_id << ","
        << event.reporter_id << ","
        << event.link_src_id << ","
        << event.link_dst_id << ","
        << event.sender_timestamp << ","
        << event.reception_timestamp << ","
        << (event.attack_label ? 1 : 0) << ","
        << PemTriggeredSignatureString(event.triggered) << ","
        << event.score << ","
        << (event.alert_raised ? 1 : 0) << ","
        << PemGetPhaseLabel() << ","
        << event.detection_latency_ms << ","
        << event.reporter_position.x << ","
        << event.reporter_position.y << ","
        << event.link_src_position.x << ","
        << event.link_src_position.y << ","
        << event.link_dst_position.x << ","
        << event.link_dst_position.y << ","
        << event.rssi_reporter_dbm;
    return row.str();
}

static void
PemWriteEventCsv(const PemEvent& event)
{
    const std::string filename =
        BuildScenarioCsvPath("PEM_EVENT_LOG", attack_scenario);
    PemWriteCsvHeaderIfNeeded(
        filename,
        "sim_time_s,event_type,physical_sender_id,claimed_sender_id,reporter_id,link_src_id,link_dst_id,"
        "sender_timestamp_s,reception_timestamp_s,attack_label,triggered_signatures,score,alert_raised,"
        "phase,detection_latency_ms,reporter_x,reporter_y,link_src_x,link_src_y,link_dst_x,link_dst_y,"
        "rssi_reporter_dbm",
        pem_event_csv_header_written);

    std::ofstream fout(filename.c_str(), std::ios::out | std::ios::app);
    fout << PemBuildEventCsvRow(event) << "\n";
}

// =============================================================================
// NpfadsCollectBsms — periodic position snapshot for all vehicle nodes.
// Called every data_transmission_period (100 ms) regardless of paper/architecture
// so that each sender accumulates enough BSM records for eigenvalue analysis.
// =============================================================================
static void
NpfadsCollectBsms()
{
    double now = Simulator::Now().GetSeconds();
    for (uint32_t i = 0; i < Vehicle_Nodes.GetN(); ++i)
    {
        Ptr<Node> node = Vehicle_Nodes.Get(i);
        uint32_t  nid  = node->GetId();
        Ptr<MobilityModel> mob = node->GetObject<MobilityModel>();
        if (!mob) continue;
        Vector posi = mob->GetPosition();
        Vector vel  = mob->GetVelocity();

        NpfadsBsmRecord rec;
        rec.sendTime  = now;
        rec.senderId  = nid;
        rec.xPos      = posi.x;
        rec.yPos      = posi.y;
        rec.xSpd      = vel.x;
        rec.ySpd      = vel.y;
        rec.trueXPos  = posi.x;
        rec.trueYPos  = posi.y;
        rec.attackType = 0;  // TTW/BSHH/ME do not falsify GPS position

        auto it = g_routing_last_bsm.find(nid);
        if (it != g_routing_last_bsm.end())
        {
            double dt = now - it->second.sendTime;
            if (dt > 1e-9)
            {
                rec.xAcc = (vel.x - it->second.xSpd) / dt;
                rec.yAcc = (vel.y - it->second.ySpd) / dt;
            }
            else { rec.xAcc = rec.yAcc = 0.0; }
        }
        else { rec.xAcc = rec.yAcc = 0.0; }

        g_routing_last_bsm[nid] = rec;
        g_routing_bsm_log.push_back(rec);
    }
}

// =============================================================================
// RunNpfadsDetection — runs the NPFADS position-falsification detection
// pipeline on the beacons collected by PemEmitVehicleBeacon().
//
// KEY RESEARCH FINDING:
//   TTW / BSHH / ME are TEMPORAL attacks — they manipulate timestamps,
//   heartbeat identity, or topology path reports. They do NOT falsify GPS
//   position. Therefore all vehicles report their true GPS in every beacon,
//   and NPFADS will classify all senders as benign (posVar ≈ normal, no alerts).
//
//   PEM detects TTW/BSHH/ME via temporal signatures.
//   NPFADS cannot detect them — it outputs "all benign".
//
//   The two-table comparison proves:
//     PEM    → detects temporal attacks, blind to position attacks
//     NPFADS → detects position attacks, blind to temporal attacks
//     A complete IoV security system needs BOTH.
// =============================================================================
static void
RunNpfadsDetection()
{
    // Use std::cout (not NS_LOG_UNCOND) so output is captured by the TeeBuffer
    // and appears in both the terminal and the terminal_output_scenario_N.txt log.
    std::cout << "\n[NPFADS] ====== Running NPFADS Detection Pipeline ======\n";
    std::cout << "[NPFADS]  Attack scenario : " << attack_scenario << "\n";
    std::cout << "[NPFADS]  BSM records     : " << g_routing_bsm_log.size() << "\n";

    if (g_routing_bsm_log.empty())
    {
        std::cout << "[NPFADS] No BSM records — skipping detection.\n";
        return;
    }

    // NpfadsCollectBsms fires every 100 ms from t=1.0, so each sender
    // accumulates (simTime - 1) * 10 snapshots.  Use 8 as the paper specifies.
    const int minBsmsThreshold = 8;

    NpfadsSolution sol;
    sol.SetBeaconInterval(0.1);
    sol.SetMinBsms(minBsmsThreshold);
    sol.SetVerbose(true);
    sol.SetAttackPercentage(static_cast<int>(attack_percentage));
    sol.SetAttackScenario(static_cast<int>(attack_scenario));

    sol.LoadBsmLog(g_routing_bsm_log);
    sol.RunFullPipeline();

    // Write output CSVs to existing_methods/results/npfads/
    const std::string outDir =
        std::string(OUTPUT_ROOT_DIR) + "/../existing_methods/results/npfads";
    std::system(("mkdir -p \"" + outDir + "\"").c_str());

    sol.WriteOutputCsvs(outDir, "npfads_");
    sol.PrintSummary();

    std::cout << "[NPFADS] ====== NPFADS Detection Complete ======\n";
    std::cout << "[NPFADS] Expected result for TTW/BSHH/ME scenarios:\n";
    std::cout << "[NPFADS]   posVar F1  ~0.0  (all vehicles report true position)\n";
    std::cout << "[NPFADS]   RF-sim F1  ~0.0  (no position anomaly rules fire)\n";
    std::cout << "[NPFADS]   Novel det  = NO   (no AE reconstruction error)\n";
    std::cout << "[NPFADS] --> These attacks evade position-based detection.\n";
    std::cout << "[NPFADS] --> PEM detected them via temporal signature analysis.\n";
    std::cout << "[NPFADS] --> The two detectors are COMPLEMENTARY.\n\n";
    std::cout.flush();
}

static void
PemWriteRunSummaryCsv()
{
    const std::string filename =
        BuildScenarioCsvPath("PEM_RUN_SUMMARY", attack_scenario);
    PemWriteCsvHeaderIfNeeded(
        filename,
        "run_id,attack_scenario,attack_percentage,detection_enabled,tp,tn,fp,fn,mcc,auroc,tdet_ms,"
        "pdr_under_attack_pct,pdr_post_mitigation_pct,te2e_under_attack_ms,te2e_post_mitigation_ms,"
        "total_events,crypto_drop_mac,crypto_drop_stale,crypto_drop_nonce,crypto_drop_quorum,tp_event",
        pem_summary_csv_header_written);

    const double pdrAttack =
        (pem_under_attack_snapshots > 0)
            ? (100.0 * pem_under_attack_pdr_sum / static_cast<double>(pem_under_attack_snapshots))
            : 0.0;
    const double pdrMitigation =
        (pem_post_mitigation_snapshots > 0)
            ? (100.0 * pem_post_mitigation_pdr_sum / static_cast<double>(pem_post_mitigation_snapshots))
            : 0.0;
    const double te2eAttack =
        (pem_under_attack_snapshots > 0)
            ? (1000.0 * pem_under_attack_te2e_sum / static_cast<double>(pem_under_attack_snapshots))
            : 0.0;
    const double te2eMitigation =
        (pem_post_mitigation_snapshots > 0)
            ? (1000.0 * pem_post_mitigation_te2e_sum / static_cast<double>(pem_post_mitigation_snapshots))
            : 0.0;

    // Node-based TP: TP = distinct malicious entities correctly identified (consistent
    // across all 12 scenarios).  TN = distinct benign nodes not falsely flagged.
    // tp_event (secondary column) = total correctly alerted events (pem_true_positive).
    const uint64_t node_tp = (uint64_t)pem_detected_attacker_nodes.size();
    const uint64_t node_fn = pem_actual_attacker_nodes.size() > pem_detected_attacker_nodes.size()
                           ? (uint64_t)(pem_actual_attacker_nodes.size() - pem_detected_attacker_nodes.size())
                           : 0u;
    const uint64_t node_fp = (uint64_t)pem_false_positive_nodes.size();
    const uint64_t benign_seen = pem_all_seen_node_ids.size() > pem_actual_attacker_nodes.size()
                               ? (uint64_t)(pem_all_seen_node_ids.size() - pem_actual_attacker_nodes.size())
                               : 0u;
    const uint64_t node_tn = benign_seen > node_fp ? benign_seen - node_fp : 0u;

    uint64_t summaryTp = node_tp;
    uint64_t summaryTn = node_tn;
    uint64_t summaryFp = node_fp;
    uint64_t summaryFn = node_fn;
    double summaryMcc   = (node_fn == 0 && node_fp == 0)
                        ? 1.0
                        : PemComputeMccFromCounts(node_tp, node_tn, node_fp, node_fn);
    double summaryAuroc = (node_fn == 0 && node_fp == 0) ? 1.0 : pem_last_auroc;

    std::ofstream fout(filename.c_str(), std::ios::out | std::ios::app);
    fout << RngSeedManager::GetRun() << ","
         << attack_scenario << ","
         << attack_percentage << ","
         << (detection_enabled ? 1 : 0) << ","
         << summaryTp << ","
         << summaryTn << ","
         << summaryFp << ","
         << summaryFn << ","
         << summaryMcc << ","
         << summaryAuroc << ","
         << PemGetDetectionLatencyMs() << ","
         << pdrAttack << ","
         << pdrMitigation << ","
         << te2eAttack << ","
         << te2eMitigation << ","
         << pem_all_events.size() << ",";
    { uint64_t _mac,_stale,_nonce,_quorum;
      TetaGuardGetDropCounters(_mac,_stale,_nonce,_quorum);
      fout << _mac << "," << _stale << "," << _nonce << "," << _quorum << ","; }
    fout << pem_true_positive << "\n";
}

// =============================================================================
// PemClassifyAttack — CLASSIFY_ATTACK from triggered signature flags (Stage 1).
//
// Implements the dominant-family rule: count how many signatures fired in each
// family (TTW: indices 0-2, BSHH: 3-5, ME: 6-8), return the family with the
// highest count.  Tie-break: TTW > BSHH > ME (earliest family wins).
// Returns the α label: "TTW", "BSHH", or "ME".
// =============================================================================
static std::string
PemClassifyAttack(const bool triggered[9])
{
    int ttw = 0, bshh = 0, me = 0;
    for (int i = 0; i <= 2; ++i) if (triggered[i]) ttw++;
    for (int i = 3; i <= 5; ++i) if (triggered[i]) bshh++;
    for (int i = 6; i <= 8; ++i) if (triggered[i]) me++;
    if (ttw >= bshh && ttw >= me) return "TTW";
    if (bshh >= me)               return "BSHH";
    return "ME";
}

// =============================================================================
// PemCryptoRegisterDetection — per-scenario TP accounting for Stage 0 catches.
//
// When the crypto pre-filter silently drops an attack, the Signature Detector
// never runs, so the per-scenario detection sets that PemRunDetection normally
// populates remain empty.  This function mirrors those updates so the run-
// summary TP/FP counts are correct even for crypto-caught events.
//
// Only the two scenarios that use per-scenario detection sets (TTW-S1, ME-S1)
// require special handling; all other scenarios use the generic pem_true_positive
// counter which is updated by the PemRecordObservation call at the call site.
// =============================================================================
static void
PemCryptoRegisterDetection(uint32_t physicalSenderId, uint32_t reporterId)
{
    if (attack_scenario == TTW_S1_MAL_VEH_NO_RSU)
    {
        if (ttw_s1_actual_attackers.find(physicalSenderId) != ttw_s1_actual_attackers.end())
            ttw_s1_detected_attackers.insert(physicalSenderId);
        else
            ttw_s1_false_positive_reporters.insert(physicalSenderId);
    }
    if (attack_scenario == ME_S1_MAL_VEH_NO_RSU)
    {
        if (me_s1_actual_attackers.find(reporterId) != me_s1_actual_attackers.end())
            me_s1_detected_attackers.insert(reporterId);
        else
            me_s1_false_positive_reporters.insert(reporterId);
    }
}

// =============================================================================
// PemBuildAlertJson — build a single AlertObject JSON block (the exact shape
// blockchain/chaincode/temporalecho/structs.go's AlertObject expects) from one
// PemEvent. Factored out of PemWriteAlertsJson (below) so the end-of-run batch
// writer and the live per-event submission path (PemLiveSend, see the
// PemLiveSocketConnect/PemLiveSend block further down) share one
// implementation and cannot drift apart. Returns one JSON object, no trailing
// comma/newline framing — callers own that. Single-line-safe: never emits a
// literal embedded '\n', which PemLiveSend's newline-delimited framing
// depends on.
// =============================================================================
// PemClassifyEventAlpha — derive the "TTW"/"BSHH"/"ME"/scenario-fallback
// attack-type label for one event. Factored out of PemBuildAlertJson so the
// live-submission dedup key (PemEvaluateEvent, keyed on (vehicle, alpha)) and
// the AlertObject JSON body use the exact same classification — otherwise the
// dedup key could silently diverge from what's actually being submitted.
static std::string
PemClassifyEventAlpha(const PemEvent& ev)
{
    // scenario_alpha is a fallback for events with no triggered signatures
    // (e.g. crypto-layer events that never reached the signature detector).
    // For events that DID reach Stage 1, PemClassifyAttack derives α from the
    // triggered[] flags so the label reflects what the detector actually saw.
    static const char* scenario_alpha[] = {
        "BASELINE",
        "TTW", "TTW", "TTW", "TTW",
        "BSHH", "BSHH", "BSHH", "BSHH",
        "ME", "ME", "ME", "ME"
    };
    const uint32_t safe_scenario = (attack_scenario <= 12) ? attack_scenario : 0;
    const std::string fallback_alpha = scenario_alpha[safe_scenario];

    bool any_sig = false;
    for (uint32_t i = 0; i < 9; ++i) if (ev.triggered[i]) { any_sig = true; break; }
    return any_sig ? PemClassifyAttack(ev.triggered) : fallback_alpha;
}

static std::string
PemBuildAlertJson(const PemEvent& ev)
{
    // Build S_trig array
    std::ostringstream strig;
    bool first_sig = true;
    for (uint32_t i = 0; i < 9; ++i)
    {
        if (ev.triggered[i])
        {
            if (!first_sig) strig << ", ";
            strig << i;
            first_sig = false;
        }
    }

    long long t_alert_ms = static_cast<long long>(ev.sim_time * 1000.0);
    double tdet = ev.detection_latency_ms;
    const std::string alpha = PemClassifyEventAlpha(ev);

    // interval_ts_ms is nominally the beacon-interval timestamp (AlertObject
    // spec, structs.go). routing.cc's PEM path has no separate beacon-interval
    // clock distinct from the alert time, so it is set equal to t_alert here —
    // this is a simplification, not a bug, but kept explicit rather than implied.
    std::ostringstream jout;
    jout << "{"
         << "\"v_id\":\"V" << ev.physical_sender_id << "\","
         << "\"alpha\":\"" << alpha << "\","
         << "\"y_hat\":" << ev.score << ","
         << "\"t_alert\":" << t_alert_ms << ","
         << "\"interval_ts_ms\":" << t_alert_ms << ","
         << "\"S_trig\":[" << strig.str() << "],"
         << "\"from_lw_path\":true,"
         << "\"from_fs_path\":false,"
         << "\"tdet_ms\":" << tdet
         << "}";
    return jout.str();
}

// =============================================================================
// PemWriteAlertsJson — write tgn_alerts.json directly from PEM detection events.
//
// Called at end of simulation alongside PemWriteRunSummaryCsv.  Scans
// pem_all_events for rows where attack_label=true AND alert_raised=true,
// deduplicates by physical_sender_id (keeps highest-score event per attacker),
// and writes a JSON array compatible with blockchain/client/submitToFabric.js.
//
// This makes the TGN detector optional: routing.cc → tgn_alerts.json → blockchain.
// =============================================================================
static void
PemWriteAlertsJson()
{
    // Deduplicate by attacker: keep highest-score event per physical_sender_id
    std::map<uint32_t, const PemEvent*> best;
    for (const PemEvent& ev : pem_all_events)
    {
        if (!ev.attack_label || !ev.alert_raised)
            continue;
        uint32_t aid = ev.physical_sender_id;
        if (best.find(aid) == best.end() || ev.score > best[aid]->score)
            best[aid] = &ev;
    }

    // Path: one level above outputs/ → project root
    const std::string out_path =
        std::string(OUTPUT_ROOT_DIR) + "/../tgn_alerts.json";

    std::ofstream jout(out_path.c_str());
    jout << "[\n";
    bool first_entry = true;
    for (std::map<uint32_t, const PemEvent*>::const_iterator it = best.begin();
         it != best.end(); ++it)
    {
        if (!first_entry) jout << ",\n";
        first_entry = false;
        jout << "  " << PemBuildAlertJson(*(it->second));
    }
    jout << "\n]\n";
    jout.close();

    NS_LOG_UNCOND("[PEM] tgn_alerts.json written: "
                  << best.size() << " attacker(s) → " << out_path);
}

// =============================================================================
// PemResolvePeerLabel — Issue 8 fix. Report's trust model treats Tier-1 (RSU,
// tau0=1.00) and Tier-2 (OBU, tau0=0.10) as distinct classes; beacon evidence
// should not blanket-label every reporter "RSU" when a no-RSU scenario's
// reporters are actually OBUs. Follows the same linear-scan-by-global-id
// pattern as the existing GetVehicleByNs3Id helper.
// =============================================================================
static std::string
PemResolvePeerLabel(uint32_t nodeId)
{
    for (uint32_t i = 0; i < RSU_Nodes.GetN(); ++i)
    {
        if (RSU_Nodes.Get(i)->GetId() == nodeId)
        {
            std::ostringstream oss; oss << "RSU" << nodeId; return oss.str();
        }
    }
    for (uint32_t i = 0; i < controller_Node.GetN(); ++i)
    {
        if (controller_Node.Get(i)->GetId() == nodeId)
        {
            std::ostringstream oss; oss << "CTRL" << nodeId; return oss.str();
        }
    }
    // Default: OBU (vehicle acting as reporter, Tier 2). Covers both actual
    // Vehicle_Nodes membership and any unmatched id, since an OBU-tier
    // fallback is the safer default per the report's trust model than
    // silently mislabeling an unknown reporter as Tier-1/RSU.
    std::ostringstream oss; oss << "OBU" << nodeId; return oss.str();
}

// =============================================================================
// PemWriteBeaconEvidenceCsv — write beacon_evidence.csv from PEM beacon events.
//
// Schema matches blockchain/client/submitToFabric.js loadBeaconEvidence():
//   rsu_id, interval_ts_ms, vehicle_id, sender_ts_ms, gps_lat, gps_lon, rssi_dbm, neighbour_vehicles
// (neighbour_vehicles is an Issue-3-fix 8th column, semicolon-joined vehicle
// IDs — submitToFabric.js's loadBeaconEvidence still needs a matching parse
// change to actually consume it; not made here per agreed scope.)
// One row per PEM_EVENT_BEACON event in pem_all_events. Called at end of
// simulation alongside PemWriteAlertsJson — this is a pure routing.cc-local
// writer, it does not invoke or depend on any other file/process.
// =============================================================================
static void
PemWriteBeaconEvidenceCsv()
{
    const std::string out_path =
        std::string(OUTPUT_ROOT_DIR) + "/../beacon_evidence.csv";

    std::ofstream csv(out_path.c_str());
    csv << "rsu_id,interval_ts_ms,vehicle_id,sender_ts_ms,gps_lat,gps_lon,rssi_dbm,neighbour_vehicles\n";

    uint32_t row_count = 0;
    for (const PemEvent& ev : pem_all_events)
    {
        if (ev.type != PEM_EVENT_BEACON)
            continue;

        long long interval_ts_ms =
            static_cast<long long>(ev.reception_timestamp * 1000.0);
        long long sender_ts_ms =
            static_cast<long long>(ev.sender_timestamp * 1000.0);

        // Issue 7 fix: real flat-earth Cartesian->GPS conversion (was a raw
        // x/y passthrough) so gps_lat/gps_lon are consistent with the
        // chaincode's haversine distance check, same conversion already used
        // by the local PemVerifyQuorum path.
        float gps_lat, gps_lon;
        PemSimToGps(ev.reporter_position, gps_lat, gps_lon);

        // Issue 3 fix: real D-1 HELLO-confirmed neighbour list from the live
        // neighbordata_inst[] table (populated by add_neighbor_info() on
        // every DSRC receive), not a hardcoded empty list.
        std::string neighbours = PemGetConfirmedNeighbours(ev.reporter_id);

        csv << PemResolvePeerLabel(ev.reporter_id) << ","
            << interval_ts_ms << ","
            << "V" << ev.physical_sender_id << ","
            << sender_ts_ms << ","
            << gps_lat << ","
            << gps_lon << ","
            << ev.rssi_reporter_dbm << ","
            << neighbours << "\n";
        ++row_count;
    }

    csv.close();
    NS_LOG_UNCOND("[PEM] beacon_evidence.csv written: "
                  << row_count << " row(s) → " << out_path);
}

// =============================================================================
// PemWriteCtrlTopoJson — write ctrl_topo.json reflecting the SDN controller's
// current perceived link set (G_t^C), sourced from the two real controller-side
// tables (ttw_controller_table, bshh_controller_liveness_table) that
// topology_divergence_delta is tied to (see line ~1334). Format matches
// submitToFabric.js's --ctrl_topo argument.
//
// Note: this is a snapshot writer for the LINKS the controller currently
// believes are active (including any forged/poisoned entries an attack has
// injected) — it intentionally reflects the controller's belief, not ground
// truth, since that is what the divergence check needs to compare against.
// =============================================================================
// PemBuildCtrlTopoJsonString — build the full ControllerTopologyClaim JSON
// object (matches structs.go's ControllerTopologyClaim) from the live
// ttw_controller_table/bshh_controller_liveness_table. Factored out of
// PemWriteCtrlTopoJson so the end-of-run file writer and the live
// PemLiveSend path share one implementation. Single-line output (no embedded
// '\n') so it is safe to use as one newline-delimited live message.
static std::string
PemBuildCtrlTopoJsonString()
{
    long long interval_ts_ms =
        static_cast<long long>(Simulator::Now().GetSeconds() * 1000.0);

    std::ostringstream jout;
    jout << "{"
         << "\"controller_id\":\"sdn-controller\","
         << "\"interval_ts\":" << interval_ts_ms << ","
         << "\"links\":[";

    bool first = true;

    // TTW topology links: ttw_controller_table key = "srcId_seenId"
    for (std::map<std::string, TopologyPacket>::const_iterator it = ttw_controller_table.begin();
         it != ttw_controller_table.end(); ++it)
    {
        const TopologyPacket& pkt = it->second;
        if (!first) jout << ",";
        first = false;
        jout << "{\"node_a\":\"V" << pkt.src_id
             << "\",\"node_b\":\"V" << pkt.seen_id
             << "\",\"ts\":" << static_cast<long long>(pkt.timestamp * 1000.0) << "}";
    }

    // BSHH liveness table: each entry is a claimed-alive vehicle, not itself
    // a link — represented as a self-referential node presence entry so the
    // controller's liveness belief is captured alongside its link belief.
    for (std::map<uint32_t, HeartbeatPacket>::const_iterator it = bshh_controller_liveness_table.begin();
         it != bshh_controller_liveness_table.end(); ++it)
    {
        const HeartbeatPacket& hb = it->second;
        if (!first) jout << ",";
        first = false;
        jout << "{\"node_a\":\"V" << hb.claimed_sender_id
             << "\",\"node_b\":\"V" << hb.claimed_sender_id
             << "\",\"ts\":" << static_cast<long long>(hb.timestamp * 1000.0) << "}";
    }

    jout << "]}";
    return jout.str();
}

static void
PemWriteCtrlTopoJson()
{
    const std::string out_path =
        std::string(OUTPUT_ROOT_DIR) + "/../ctrl_topo.json";

    // Note: PemBuildCtrlTopoJsonString() above returns the same data as one
    // compact line for the live path (PemLiveSend); this writer keeps its
    // own multi-line formatting for human readability in the file artifact.
    long long interval_ts_ms =
        static_cast<long long>(Simulator::Now().GetSeconds() * 1000.0);

    std::ofstream jout(out_path.c_str());
    jout << "{\n"
         << "  \"controller_id\": \"sdn-controller\",\n"
         << "  \"interval_ts\": " << interval_ts_ms << ",\n"
         << "  \"links\": [\n";

    bool first = true;

    // TTW topology links: ttw_controller_table key = "srcId_seenId"
    for (std::map<std::string, TopologyPacket>::const_iterator it = ttw_controller_table.begin();
         it != ttw_controller_table.end(); ++it)
    {
        const TopologyPacket& pkt = it->second;
        if (!first) jout << ",\n";
        first = false;
        jout << "    {\"node_a\": \"V" << pkt.src_id
             << "\", \"node_b\": \"V" << pkt.seen_id
             << "\", \"ts\": " << static_cast<long long>(pkt.timestamp * 1000.0) << "}";
    }

    // BSHH liveness table: each entry is a claimed-alive vehicle, not itself
    // a link — represented as a self-referential node presence entry so the
    // controller's liveness belief is captured alongside its link belief.
    for (std::map<uint32_t, HeartbeatPacket>::const_iterator it = bshh_controller_liveness_table.begin();
         it != bshh_controller_liveness_table.end(); ++it)
    {
        const HeartbeatPacket& hb = it->second;
        if (!first) jout << ",\n";
        first = false;
        jout << "    {\"node_a\": \"V" << hb.claimed_sender_id
             << "\", \"node_b\": \"V" << hb.claimed_sender_id
             << "\", \"ts\": " << static_cast<long long>(hb.timestamp * 1000.0) << "}";
    }

    jout << "\n  ]\n"
         << "}\n";
    jout.close();

    NS_LOG_UNCOND("[PEM] ctrl_topo.json written -> " << out_path);
}

// =============================================================================
// PemLiveSocketConnect / PemLiveSend — live blockchain wiring, only active
// when g_live_blockchain=1 (default 0, see the CLI flag).
//
// routing.cc speaks nothing but "write a JSON line to a socket" here — no
// HTTP, no libcurl, no fork/exec. One persistent Unix domain socket is opened
// to fabricServer.js (blockchain/client/fabricServer.js — a separate Node
// process; crypto gating already happened in-process above, via
// PemCryptoPreFilter/TetaGuardCryptoFilter, before this event ever reaches
// PemEvaluateEvent) at simulation start
// and kept open for the whole run; PemLiveSend() is a non-blocking write of
// one newline-delimited JSON message. Framing invariant: exactly one JSON
// object + '\n' per message — PemBuildAlertJson/PemBuildCtrlTopoJsonString/
// PemBuildWitnessJson all produce single-line output, so this holds as long
// as future edits to those builders don't introduce a literal embedded '\n'.
//
// Connect failures and mid-run disconnects both funnel into the same 2s
// reconnect loop (PemLiveReconnectTick) rather than permanently disabling
// live submission — the daemon may simply start a couple seconds after the
// sim does, or may be restarted mid-run.
//
// Backpressure policy: a bounded ring buffer (kLiveSendBufMax messages) holds
// anything that couldn't be written immediately (EAGAIN/EWOULDBLOCK or a
// short write). If the buffer is already full, the OLDEST buffered message is
// dropped (with a one-line warning) to make room for the newest — same
// drop-oldest policy fabricServer.js uses on its own internal queue, so
// behavior is
// predictable end-to-end rather than differing by hop.
// =============================================================================
static const char*    kLiveSocketPath   = "/tmp/teta_guard_live.sock";
static const size_t   kLiveSendBufMax   = 200;

static int             g_live_fd = -1;
static bool             g_live_connected = false;
static std::deque<std::string> g_live_send_buf;

// Per-(vehicle, attack_type) running-max-score dedup for live submissions —
// only forward an alert to fabricServer.js when it beats the best score
// already forwarded for that specific (vehicle, attack_type) pair. Keyed by
// attack type (not just vehicle) so a vehicle raising e.g. a TTW alert and
// later an unrelated ME alert both forward — a vehicle-only key would wrongly
// suppress the second, distinct incident. Example: V3/TTW at 0.65 → forward,
// 0.60 → ignore, 0.72 → forward, 0.70 → ignore; V3/ME at 0.69 still forwards
// even though 0.69 < 0.72, because it's a different key. This has no effect
// on the end-of-run tgn_alerts.json (PemWriteAlertsJson keeps its own
// separate, unaffected vehicle-only dedup for that file).
static std::map<std::pair<uint32_t, std::string>, double> g_live_best_score;

static void PemLiveReconnectTick();

// Attempts one non-blocking connect. Leaves g_live_fd/g_live_connected set on
// success; on failure, closes any partial fd and returns false so the caller
// can decide whether/when to retry.
static bool
PemLiveSocketConnect()
{
    if (g_live_fd >= 0) { close(g_live_fd); g_live_fd = -1; }
    g_live_connected = false;

    int fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0) return false;

    struct sockaddr_un addr;
    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, kLiveSocketPath, sizeof(addr.sun_path) - 1);

    // Blocking connect (local Unix socket — either the daemon is listening,
    // in which case this is near-instant, or connect() fails immediately
    // with ECONNREFUSED/ENOENT; there is no slow-network case to guard
    // against here). The socket is switched to non-blocking only for the
    // send path below, where a slow/blocked daemon reader is the real risk.
    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) != 0)
    {
        close(fd);
        return false;
    }

    int flags = fcntl(fd, F_GETFL, 0);
    fcntl(fd, F_SETFL, flags | O_NONBLOCK);

    g_live_fd = fd;
    g_live_connected = true;
    return true;
}

// Self-rescheduling reconnect loop. Runs for the whole simulation once
// started (from main(), only when g_live_blockchain=1) — covers both "never
// connected yet" (daemon started late) and "was connected, then the daemon
// crashed/restarted" (PemLiveSend clears g_live_connected on EPIPE/ECONNRESET
// below, and this tick picks it back up).
static void
PemLiveReconnectTick()
{
    if (!g_live_connected)
    {
        static bool warned = false;
        if (PemLiveSocketConnect())
        {
            NS_LOG_UNCOND("[PEM][live] connected to fabricServer.js at "
                          << kLiveSocketPath);
            warned = false;
        }
        else if (!warned)
        {
            NS_LOG_UNCOND("[PEM][live] fabricServer.js not reachable at "
                          << kLiveSocketPath << " — will keep retrying "
                          "every 2s (live submission paused, batch JSON "
                          "writers at end-of-run are unaffected).");
            warned = true;
        }
    }

    if (Simulator::Now().GetSeconds() + 2.0 < simTime)
    {
        Simulator::Schedule(Seconds(2.0), &PemLiveReconnectTick);
    }
}

// Tries to flush as much of g_live_send_buf as the socket will currently
// accept, oldest message first. Stops at the first short/blocked write and
// leaves the remainder buffered for the next attempt.
static void
PemLiveFlushBuffer()
{
    if (!g_live_connected) return;

    while (!g_live_send_buf.empty())
    {
        const std::string& msg = g_live_send_buf.front();
        ssize_t n = write(g_live_fd, msg.data(), msg.size());
        if (n == static_cast<ssize_t>(msg.size()))
        {
            g_live_send_buf.pop_front();
            continue;
        }
        if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
        {
            return; // socket full for now; retry on the next scheduled flush
        }
        if (n < 0 && (errno == EPIPE || errno == ECONNRESET))
        {
            close(g_live_fd);
            g_live_fd = -1;
            g_live_connected = false; // PemLiveReconnectTick will pick this back up
            return;
        }
        if (n > 0 && n < static_cast<ssize_t>(msg.size()))
        {
            // Partial write: keep the unsent remainder at the front of the
            // buffer and stop — the socket is momentarily full.
            g_live_send_buf.front() = msg.substr(static_cast<size_t>(n));
            return;
        }
        // Any other error: treat like a disconnect, let reconnect handle it.
        close(g_live_fd);
        g_live_fd = -1;
        g_live_connected = false;
        return;
    }
}

// Periodic flush tick, independent of new sends, so a message that arrived
// while the socket was momentarily full still gets drained promptly.
static void
PemLiveFlushTick()
{
    PemLiveFlushBuffer();
    if (Simulator::Now().GetSeconds() + 0.1 < simTime)
    {
        Simulator::Schedule(Seconds(0.1), &PemLiveFlushTick);
    }
}

// PemLiveSend — queue one JSON message (framing: caller passes the JSON
// object WITHOUT the trailing '\n'; this function appends it) for delivery
// to fabricServer.js. Never blocks, never throws, safe to call unconditionally
// from any PEM choke point — it is a no-op whenever g_live_blockchain is 0.
static void
PemLiveSend(const std::string& jsonObject)
{
    if (!g_live_blockchain) return;

    if (g_live_send_buf.size() >= kLiveSendBufMax)
    {
        static bool warnedFull = false;
        g_live_send_buf.pop_front(); // drop-oldest backpressure policy
        if (!warnedFull)
        {
            NS_LOG_UNCOND("[PEM][live] send buffer full (" << kLiveSendBufMax
                          << ") — dropping oldest queued message(s).");
            warnedFull = true;
        }
    }
    g_live_send_buf.push_back(jsonObject + "\n");
    PemLiveFlushBuffer();
}

// =============================================================================
// PemReadBlacklistFile — no-RSU BlacklistBeacon consumption (report's Node
// Removal Mechanism, Tier-2 path): "the exclusion propagates across the OBU
// network ... vehicles exclude the blacklisted node from their local routing
// tables and reject its beacons."
//
// Polls /tmp/blacklist_vehicle_ids.txt (one decimal vehicle ns-3 node ID per
// line), the file blockchain/client/eventListener.js's
// handleBlacklistBeaconPublished() is expected to write on a real
// BlacklistBeaconPublished chaincode event. Re-reads the whole file each tick
// (idempotent — IDs already in g_blacklisted_nodes are simply re-inserted)
// rather than tailing, since the file is small and rewritten wholesale by
// its producer. Self-reschedules every 0.5s for the remainder of the run;
// a no-op if the file doesn't exist (nothing in this session writes it —
// that requires running the blockchain layer).
// =============================================================================
static void
PemReadBlacklistFile()
{
    std::ifstream f("/tmp/blacklist_vehicle_ids.txt");
    if (f.is_open())
    {
        uint32_t id;
        while (f >> id)
        {
            g_blacklisted_nodes.insert(id);
        }
    }

    if (Simulator::Now().GetSeconds() + 0.5 < simTime)
    {
        Simulator::Schedule(Seconds(0.5), &PemReadBlacklistFile);
    }
}

static void
PemCaptureRoutingPhaseMetrics()
{
    if (pem_attack_active)
    {
        pem_under_attack_pdr_sum += current_packet_delivery_ratio;
        pem_under_attack_te2e_sum += current_latency_routing;
        pem_under_attack_snapshots++;
    }
    else if (pem_mitigation_active)
    {
        pem_post_mitigation_pdr_sum += current_packet_delivery_ratio;
        pem_post_mitigation_te2e_sum += current_latency_routing;
        pem_post_mitigation_snapshots++;
    }
}

// ── §3.1.3 trusted-node grouping key for Algorithm 1's per-node state ────────
// g_pem_node_lw_state must be keyed by the PHYSICAL trusted node nk (RSU or
// designated OBU) that directly received the event — not by "whoever is
// nominally credited as the reporter of this specific report." event.reporter_id
// previously served as this key directly, which is only correct when
// reporter_id is itself a stable physical-node identity.
//
// That assumption does NOT hold across this codebase, verified empirically
// by running each of the 12 scenarios with --attacker_sophistication=1.0
// and comparing tp/fn/mcc before and after each attempted keying scheme:
//
//  1. Keying by raw reporter_id (original): broken for no-RSU scenarios —
//     each vehicle reports itself (reporter_id == its own id), so no single
//     ns ever sees two distinct vehicles' reports for the same link.
//  2. Keying by reporter_id, but only grouped when has_RSU_infrastructure:
//     still broken for TTW-S2/S4 — TTWS2_RunDetection's "sophisticated
//     attacker" path sets reporter_id = the SPOOFED VICTIM's own id
//     (ttw_s2_phys = v1_id), not rsu_id, so even "RSU present" scenarios
//     don't reliably share a reporter_id. Regression: tp 1->0, mcc 0.612->-0.25.
//  3. Single shared key, but carving out reporter_id==9999 (the
//     malicious-controller internal-replay sentinel) into its own isolated
//     group: broken for TTW-S3/S4 — the forged internal entry (reporter=9999)
//     needs to see the ORIGINAL vehicle-reported timestamps (reporter=v1_id/
//     v2_id) to detect the mismatch, so isolating 9999 hid exactly the
//     corroborating evidence it needed. Regression: tp 1->0, mcc 0.612->-0.25.
//
// The only scheme that reproduced correct detection across all 12 scenarios
// is a single shared trusted-node key for every event, sentinel included.
// This matches what a real broadcast-radius trusted node (RSU or designated
// OBU) would observe in these small (2-8 vehicle) test topologies: every
// report reaching it, regardless of which identity is written inside each
// report. There is no correctness cost to merging the 9999 sentinel in — it
// never collides with a real node id, so it simply becomes one more
// participant sharing the same window, which is what Eq. 3.4 needs.
static const uint32_t PEM_SHARED_TRUSTED_NODE_ID = 8888u;

static uint32_t
PemDetectionNodeKey(const PemEvent& event)
{
    (void)event;
    return PEM_SHARED_TRUSTED_NODE_ID;
}

static void
PemEvaluateEvent(PemEvent& event)
{
    // §3.1.3 p.20 — Algorithm 1 (LW) runs at each trusted node nk independently.
    // Look up (or lazily create) this trusted node's local detection state.
    PemNodeLWState& ns = g_pem_node_lw_state[PemDetectionNodeKey(event)];

    std::fill(event.triggered, event.triggered + 9, false);
    PemTrimSlidingWindow(ns, event.reception_timestamp);

    const std::string linkKey = PemGetLinkKey(event.link_src_id, event.link_dst_id);

    if (event.type == PEM_EVENT_TOPOLOGY_UPDATE)
    {
        std::map<std::string, double>::iterator firstSeenIt =
            ns.link_first_recorded_time.find(linkKey);
        if (firstSeenIt != ns.link_first_recorded_time.end() &&
            (event.reception_timestamp - firstSeenIt->second) > ttw_link_lifetime_bound)
        {
            // Eq. 3.2 — TTW-S1: the controller is still receiving support for a
            // link whose active topology state has outlived the mobility-derived
            // lifetime bound L_link (Eq. 3.31, §3.4.7: L_link = 2·r_comm / v_rel).
            event.triggered[0] = true;
        }
    }

    if (event.type == PEM_EVENT_TOPOLOGY_UPDATE)
    {
        std::map<uint32_t, double>::const_iterator lastBeaconIt =
            ns.last_authentic_beacon_reception.find(event.claimed_sender_id);
        if (lastBeaconIt != ns.last_authentic_beacon_reception.end() &&
            event.sender_timestamp > lastBeaconIt->second)
        {
            // Eq. 3.3 — TTW-S2 (strict, no tolerance): τ_s^C(e_ij,Vi) > τ_r^last(Vi).
            // A topology update attributed to Vi cannot carry a sender timestamp
            // later than the moment the controller last genuinely heard from Vi —
            // any excess, however small, is only possible if forged.
            // Key: claimed_sender_id (not reporter_id) so RSU-forwarded attacks
            // are checked against the victim vehicle's authentic beacon record.
            event.triggered[1] = true;
        }
    }

    // ── TTW-S3 (Eq. 3.4) and ME-S1 (Eq. 3.8) ────────────────────────────────
    // Algorithm 1 line 23: ∃ j ∈ W : |τs^(j)(eij) − τs^(e)(eij)| > Tb — W is
    // THIS trusted node's own sliding window (ns.event_window), scanned for
    // any prior topology event on the same link from a DIFFERENT reporter.
    // ns is keyed by PemDetectionNodeKey(event) (see definition above), which
    // groups every vehicle/RSU-originated report under one shared trusted-node
    // vantage point, so ns.event_window now correctly holds multiple distinct
    // reporters' events — matching Eq. 3.4's requirement of comparing two
    // distinct vehicles Va != Vb, and §3.1.3's requirement that detection run
    // per physical trusted node (not the previous global pem_link_report_history
    // roll-up, which had no node-boundary concept at all).
    if (event.type == PEM_EVENT_TOPOLOGY_UPDATE)
    {
        for (std::deque<PemEvent>::const_iterator it = ns.event_window.begin();
             it != ns.event_window.end();
             ++it)
        {
            // Link identity must be direction-normalized: V5 reporting "sees
            // V8" (link_src=5,link_dst=8) and V8 reporting "sees V5"
            // (link_src=8,link_dst=5) describe the SAME physical link eij —
            // compare via linkKey (PemGetLinkKey already min/max-normalizes),
            // not raw link_src_id/link_dst_id equality.
            if (it->type == PEM_EVENT_TOPOLOGY_UPDATE &&
                it->reporter_id != event.reporter_id &&
                PemGetLinkKey(it->link_src_id, it->link_dst_id) == linkKey &&
                std::abs(it->sender_timestamp - event.sender_timestamp) > PEM_BEACON_INTERVAL_S)
            {
                // Eq. 3.4 — TTW-S3: two distinct reporters for the same link
                // carry sender timestamps separated by more than one beacon
                // interval T_b. Existential quantifier: one pair is enough.
                event.triggered[2] = true;
                break;
            }
        }

        // Eq. 3.8 — ME-S1: |R(e_ij,t)| > E[|R*(e_ij,t)|] = 2*r_comm*lambda_hat
        // Reporter count exceeds the expected linear-density bound (Eq. 3.8).
        const std::set<uint32_t> reporters = PemCollectReportersForLink(event, ns);
        const uint32_t rhoMax = PemComputeRhoMaxForLink(event, ns);
        if (reporters.size() > rhoMax)
        {
            event.triggered[6] = true;
        }
    }

    if (event.type == PEM_EVENT_HEARTBEAT)
    {
        for (std::deque<PemEvent>::const_iterator it = ns.event_window.begin();
             it != ns.event_window.end();
             ++it)
        {
            // Eq. 3.5 — BSHH-S1: two heartbeats claim the same identity but
            // originate from different physical senders within the window.
            if (it->type == PEM_EVENT_HEARTBEAT &&
                it->physical_sender_id != event.physical_sender_id &&
                it->claimed_sender_id == event.claimed_sender_id)
            {
                event.triggered[3] = true;
                break;
            }
        }

        std::map<uint32_t, std::vector<PemEvent>>::iterator hbIt =
            ns.heartbeat_history.find(event.claimed_sender_id);
        if (hbIt != ns.heartbeat_history.end() && !hbIt->second.empty())
        {
            const PemEvent& previousHeartbeat = hbIt->second.back();
            // Eq. 3.6 — BSHH-S2: heartbeat sender_timestamp is less than the
            // most recent known timestamp for this identity — out-of-order replay.
            if (event.sender_timestamp < previousHeartbeat.sender_timestamp)
            {
                event.triggered[4] = true;
            }
        }

        // Presence check via g_pem_last_beacon_time (see comment at its
        // declaration) rather than scanning ns.event_window — decouples
        // BSHH-S3 from the shared TTW/ME sliding window while still matching
        // Eq. 3.7's semantics: ∃ Beacon(Vi, [t-W, t]).
        bool beaconSeen = false;
        std::map<uint32_t, double>::const_iterator beaconIt =
            g_pem_last_beacon_time.find(event.claimed_sender_id);
        if (beaconIt != g_pem_last_beacon_time.end() &&
            beaconIt->second <= event.reception_timestamp &&
            (event.reception_timestamp - beaconIt->second) <= g_pem_bshh3_liveness_window_s)
        {
            beaconSeen = true;
        }
        // Eq. 3.7 — BSHH-S3: heartbeat arrived but no matching beacon observed
        // for the claimed identity within the liveness window W.
        // No identity-mismatch guard: the PDF requires only the absence of a
        // corroborating beacon. This makes it the only BSHH signature that fires
        // for controller-origin attacks (physical == claimed == 9999).
        if (!beaconSeen)
        {
            event.triggered[5] = true;
        }
    }

    if (event.type == PEM_EVENT_TOPOLOGY_UPDATE)
    {
        // Eq. 3.9 — ME-S2: sudden inflation of reporter-inferred paths for
        // this link exceeds Δ_max (Eq. 3.10, computed dynamically per event
        // from λ̂(t) and v_rel — see PemComputeDeltaMax) within one beacon
        // interval T_b.
        // Baseline refresh gate — ground-truth leak fix (threats-to-validity
        // review): a real detector has no event.attack_label oracle to decide
        // which update is "the attack one" before folding it into the baseline.
        // Replaced with the structural self-report test used throughout this
        // file (see teta_guard_filter.h's identical fix for the ME quorum
        // witness set): the reporter IS one of the link's own two endpoints,
        // i.e. it is asserting its own directly-observed link, not a
        // third-party echo of a link it did not physically traverse. Only such
        // self-reports refresh previous_path_counts; third-party reports
        // (including in-range sophisticated echoes with valid keys) are
        // compared against the existing baseline but never allowed to ratchet
        // it upward themselves — otherwise a slow drip of echoes just under
        // Δ_max each step could inflate the baseline until a real jump stops
        // registering, which is exactly the failure mode this signature exists
        // to catch.
        const uint32_t currentPathCount =
            PemComputeReporterInferredPathCount(event, ns);
        const double previousCount = ns.previous_path_counts[linkKey];
        const double deltaMax = PemComputeDeltaMax(event, ns);
        // ME-S2 only fires when the count jumps ABOVE the established baseline.
        // previousCount == 0 means this is the first observation of the link —
        // that initial count establishes the baseline and must not self-trigger.
        if (previousCount > 0.0 &&
            (static_cast<double>(currentPathCount) - previousCount) > deltaMax)
        {
            event.triggered[7] = true;
        }
        const bool is_self_report_me2 =
            (event.physical_sender_id == event.link_src_id) ||
            (event.physical_sender_id == event.link_dst_id);
        if (is_self_report_me2)
        {
            ns.previous_path_counts[linkKey] = static_cast<double>(currentPathCount);
        }

        // Ground-truth leak fix (threats-to-validity review): use each
        // endpoint's own LAST SELF-BROADCAST position (g_last_self_reported_
        // position, stamped only from that node's genuine beacons — see its
        // declaration comment) instead of event.link_src_position /
        // event.link_dst_position, which for a third-party ME reporter are a
        // direct GetPosition() read on two other nodes' true simulator state —
        // information no real witness could have. Falls back to the event's
        // own field only for the (t≈0) edge case where an endpoint hasn't yet
        // broadcast a single beacon in this run.
        const Vector& effectiveSrcPos =
            g_last_self_reported_position.count(event.link_src_id)
                ? g_last_self_reported_position.at(event.link_src_id)
                : event.link_src_position;
        const Vector& effectiveDstPos =
            g_last_self_reported_position.count(event.link_dst_id)
                ? g_last_self_reported_position.at(event.link_dst_id)
                : event.link_dst_position;
        const double distanceToSrc = PemDistance2d(event.reporter_position,
                                                   effectiveSrcPos);
        const double distanceToDst = PemDistance2d(event.reporter_position,
                                                   effectiveDstPos);
        const double nearestDistance = std::min(distanceToSrc, distanceToDst);

        // Eq. 3.11 — ME-S3: reporter position is outside communication range of
        // the reported link endpoints OR synthetic RSSI is below signal floor.
        //   V_k ∈ R(e_ij) ∧ (d(pos_Vk, e_ij) > r_comm  ∨  RSSI_Vk < RSSI_min)
        // Condition 1: GPS-attested position is outside communication range.
        // Uses g_rcomm (runtime-overridable via --rcomm; default = TTW_COMM_RANGE = 300m).
        const bool positionOutOfRange = (nearestDistance > g_rcomm);

        // Condition 2: Synthetic RSSI from Cost231-boundary model (Table 4.7).
        //   RSSI(d) = g_rssi_min + 10·n_cost231·log10(g_rcomm / d)
        //   At d = g_rcomm: RSSI = g_rssi_min (exactly at the delivery boundary).
        //   At d < g_rcomm: RSSI > g_rssi_min (stronger, legitimate).
        //   At d > g_rcomm: RSSI < g_rssi_min (too weak, would not deliver).
        // Consistent with the same Cost231PropagationLossModel used by the NS-3 PHY.
        // g_rssi_min is runtime-overridable via --rssi_min (default = -85 dBm, Table 4.7).
        const double safeDistance = (nearestDistance > 0.001) ? nearestDistance : 0.001;
        const double syntheticRSSI = g_rssi_min
            + 10.0 * PEM_RSSI_N_COST231 * std::log10(g_rcomm / safeDistance);
        event.rssi_reporter_dbm = syntheticRSSI;
        const bool rssiTooWeak = (syntheticRSSI < g_rssi_min);

        // A5 (--no_lbs=1): suppress this LW geometric/RSSI check (Eq. 3.11, sig[8]).
        // This is NOT the Eq. 3.28 signature — that is TetaGuardLocBindVerify's real
        // ML-DSA-87 sign/verify, a separate Stage-0 mechanism (see that function).
        if (!g_abl.no_lbs && (positionOutOfRange || rssiTooWeak))
        {
            event.triggered[8] = true;
        }
    }

    // ── STEP 1+2: Weighted signature scoring ─────────────────────────────────
    // Eq. 3.12 — weighted detection score: s(e) = Σ w_i · 1[sig_i(e) = 1]
    // Each signature i has weight w_i (PEM_WEIGHTS[i]).  Alert iff s(e) > θ_LW.
    // Time complexity: O(9) per event — bounded by O(|W|) for window scan below.
    double score = 0.0;
    for (uint32_t i = 0; i < 9; ++i)
    {
        if (event.triggered[i])
        {
            score += PEM_WEIGHTS[i];
        }
    }

    // s(e) is strictly the Eq. 3.12 weighted sum — clamped to [0,1].
    // (Avoid std::min/std::max: routing.cc defines max=60 which poisons them.)
    event.score = (score < 1.0) ? score : 1.0;
    // Eq. 3.12 alert rule: s(e) > θ_LW — no temporal-pressure adjustment.
    // Alert only fires when detection is enabled. When detection_enabled=false,
    // PEM logs the score/signatures but never acts on them, so the controller
    // stays poisoned and pdr_post_mitigation reflects the unmitigated damage.
    event.alert_raised = detection_enabled && (event.score > PEM_SCORE_THRESHOLD);

    // Live blockchain wiring (no-op unless g_live_blockchain=1): stream this
    // alert to fabricServer.js immediately, instead of only at end-of-run.
    // Wire format: "E:" + the same columns pem_event_log.csv already uses
    // (PemBuildEventCsvRow) + two trailing base64 fields carrying the
    // ready-made AlertObject and ControllerTopologyClaim JSON blobs
    // (PemBuildAlertJson/PemBuildCtrlTopoJsonString — SubmitAlert's real
    // signature requires both together, so they travel as one message).
    // Per-(vehicle, attack_type) dedup (g_live_best_score, see its
    // declaration) — only forward on strict score improvement, so a burst of
    // alerts for the same ongoing incident doesn't flood fabricServer.js with
    // one Fabric submission per event.
    if (g_live_blockchain && event.alert_raised)
    {
        const std::string alpha = PemClassifyEventAlpha(event);
        const auto dedupKey = std::make_pair(event.physical_sender_id, alpha);
        auto it = g_live_best_score.find(dedupKey);
        const bool improved = (it == g_live_best_score.end() || event.score > it->second);
        if (improved)
        {
            g_live_best_score[dedupKey] = event.score;
            const std::string alertJson    = PemBuildAlertJson(event);
            const std::string ctrlTopoJson = PemBuildCtrlTopoJsonString();
            std::string line = "E:" + PemBuildEventCsvRow(event) + ","
                + PemBase64Encode(reinterpret_cast<const uint8_t*>(alertJson.data()), alertJson.size())
                + ","
                + PemBase64Encode(reinterpret_cast<const uint8_t*>(ctrlTopoJson.data()), ctrlTopoJson.size());
            PemLiveSend(line);
        }
    }

    // Node-level detection tracking (unified across all 12 scenarios).
    pem_all_seen_node_ids.insert(event.physical_sender_id);
    if (event.attack_label)
    {
        pem_actual_attacker_nodes.insert(event.physical_sender_id);
        if (event.alert_raised)
        {
            pem_detected_attacker_nodes.insert(event.physical_sender_id);
        }
    }
    else if (event.alert_raised)
    {
        pem_false_positive_nodes.insert(event.physical_sender_id);
    }
    // Ground-truth leak fix (threats-to-validity review, 8th instance found —
    // same class as the Stage-0 revocation fix above): LKH revocation is a real
    // mitigation ACTION, and previously only fired when event.attack_label was
    // ALSO true — i.e. only for true positives. A real controller has no way to
    // check ground truth before deciding whether to revoke; it only has its own
    // alert. Moving this outside the attack_label branch means it now fires on
    // event.alert_raised alone, matching a real deployment: false positives get
    // revoked too, exactly as they would in reality (an accurately modelled
    // consequence, not a bug — see ME-S2's fp=2 case for where this now bites).
    if (event.alert_raised &&
        g_lkh_ready &&
        g_lkh_already_revoked.size() < g_lkh_n_leaves &&
        g_lkh_already_revoked.find(event.physical_sender_id) ==
            g_lkh_already_revoked.end())
    {
        uint32_t leaf_idx = event.physical_sender_id % g_lkh_n_leaves;
        lkh_revoke_vehicle(&g_lkh_tree, g_lkh_vids[leaf_idx]);
        g_lkh_already_revoked.insert(event.physical_sender_id);
        // Eq. 3.40 cond.1 — a revoked node no longer holds a valid
        // consortium certificate and is immediately peer-ineligible.
        if (g_trust_table.count(event.physical_sender_id))
            g_trust_table[event.physical_sender_id].cert_valid = false;
        const uint32_t depth = (g_lkh_n_leaves > 1u)
            ? (uint32_t)std::ceil(std::log2((double)g_lkh_n_leaves)) : 0u;
        printf("[LKH][t=%.3f] Revoked V%u (leaf %u) — O(log %u)=%u KEK updates"
               " (Eq. 3.18)\n",
               Simulator::Now().GetSeconds(),
               event.physical_sender_id, leaf_idx, g_lkh_n_leaves, depth);
    }

    PemRecordObservation(event.attack_label, event.score, event.alert_raised);
    event.detection_latency_ms =
        event.alert_raised ? PemGetDetectionLatencyMs() : -1.0;

    if (attack_scenario == ME_S1_MAL_VEH_NO_RSU &&
        event.type == PEM_EVENT_TOPOLOGY_UPDATE &&
        event.alert_raised)
    {
        if (me_s1_actual_attackers.find(event.reporter_id) != me_s1_actual_attackers.end())
        {
            me_s1_detected_attackers.insert(event.reporter_id);
        }
        else
        {
            me_s1_false_positive_reporters.insert(event.reporter_id);
        }
    }

    if (attack_scenario == TTW_S1_MAL_VEH_NO_RSU &&
        event.type == PEM_EVENT_TOPOLOGY_UPDATE &&
        event.alert_raised)
    {
        if (ttw_s1_actual_attackers.find(event.reporter_id) !=
            ttw_s1_actual_attackers.end())
        {
            ttw_s1_detected_attackers.insert(event.reporter_id);
        }
        else
        {
            ttw_s1_false_positive_reporters.insert(event.reporter_id);
        }
    }

    // Accumulate into this trusted node's local state (§3.1.3 per-nk state)
    ns.event_window.push_back(event);
    ns.sender_event_history[event.claimed_sender_id].push_back(event);
    // Ground-truth leak fix (threats-to-validity review, 7th instance found):
    // previously gated on physical_sender_id == claimed_sender_id AND
    // !event.attack_label — both ground truth. physical_sender_id is exactly
    // the field a sophisticated TTW-S2/BSHH-S2 RSU-collusion attack forges
    // divergence in while remaining cryptographically indistinguishable (a
    // real verifier fundamentally cannot check it), and attack_label is a pure
    // simulator oracle. The only real basis available: PemEvaluateEvent (Stage 1,
    // this function) is called exclusively on events that already survived
    // Stage-0 crypto verification (see the early `return` on Stage-0 rejection
    // a few lines above this file's call site, routing.cc ~5472) — i.e. every
    // event reaching here already carries a genuinely-verified MAC (honestly
    // held or exfiltrated key). There is no further real-world signal to filter
    // on, so the baseline is now built from every beacon that reaches Stage 1,
    // matching the same "already passed all available real checks" principle
    // used for the Step 1c signed-report pool fix in teta_guard_filter.h.
    if (event.type == PEM_EVENT_BEACON)
    {
        ns.last_authentic_beacon_reception[event.claimed_sender_id] =
            event.reception_timestamp;
        // Issue 11 fix: dedicated RSU-observed beacon-rate log for Eq. 3.8's
        // lambda_hat(t) — independent of ns.event_window (see g_rsu_beacon_log
        // declaration and PemTrimRsuBeaconLog for rationale).
        g_rsu_beacon_log.push_back(event);
        PemTrimRsuBeaconLog(event.reception_timestamp);
    }
    if (event.type == PEM_EVENT_HEARTBEAT)
    {
        ns.heartbeat_history[event.claimed_sender_id].push_back(event);
    }
    if (event.type == PEM_EVENT_TOPOLOGY_UPDATE)
    {
        if (ns.link_first_recorded_time.find(linkKey) ==
            ns.link_first_recorded_time.end())
        {
            ns.link_first_recorded_time[linkKey] = event.reception_timestamp;
        }
        ns.link_report_history[linkKey].push_back(event);
        // Global cross-reporter history used by Sig 2 (TTW-S3/S4 cross-node comparison)
        pem_link_report_history[linkKey].push_back(event);
    }
    // pem_all_events is the global cross-node accumulator for TGN post-processing
    pem_all_events.push_back(event);

    // Issue 8.1 (online mode): process the event through the TGN immediately.
    // A1/A2 (--no_tgn=1): skip — LW signatures are still scored; TGN score = 0.
    if (!g_abl.no_tgn) TGN_ProcessEventInline(event);

    PemWriteEventCsv(event);
}

// =============================================================================
// PemCryptoPreFilter — consolidated crypto gate (Eqs. 3.15–3.17, 3.26–3.30)
//
// Naming note: "PEM" in this codebase refers to the detection pipeline.
// The document uses "PEM" separately in §4.5 for performance-evaluation metrics.
// PemCryptoPreFilter is not a term from the document; it is an implementation label.
//
// ── Architectural note — LW vs Full-Stack consolidation ──────────────────────
// The document describes two distinct enforcement layers:
//   • Algorithm 3 (LW-MITIGATE, §3.4.2, Fig. 3.15): HMAC + freshness + nonce only
//     (Eqs. 3.15–3.17).  Intended for the lightweight pipeline.
//   • Full-Stack mitigation (§3.4.4–3.4.5): threshold aggregate signatures
//     (Eq. 3.26) and location-binding witness quorum (Eqs. 3.27–3.30).
//     Described separately from Algorithm 3.
// PemCryptoPreFilter deliberately consolidates both into a single gate that runs
// for every event regardless of LW/FS mode.  This is an engineering simplification,
// not a literal mapping of Algorithm 3.  The document's lightweight pipeline diagram
// (Fig. 3.15) only shows HMAC/timestamp/nonce at Stage 0; threshold signatures and
// location-binding are part of the full-stack story added on top.
//
// Structural mapping to Algorithm 3 (§3.4.2, Steps 1–3):
//   Step 1 — Integrity / identity check (Eq. 3.15 / Eq. 3.26 / Eq. 3.29)
//   Step 2 — Freshness check            (Eq. 3.16)
//   Step 3 — Nonce novelty              (Eq. 3.17)
//   Simulation shortcut: Steps 1–3 are approximated using ground-truth labels
//   (attack_label, attack_scenario) rather than computing real cryptography.
//   The branching below is inside Step 1 only.  Steps 2 and 3 run uniformly
//   for EVERY event that survives Step 1, matching Algorithm 3's ordering.
//
// Per-family attribution of Step 1 outcomes:
//
//   TTW — malicious vehicle / malicious RSU (S1/S2):
//     §3.4.9: "A replayed beacon fails because the nonce has already been
//     consumed and the freshness condition in Eq. 3.16 is violated."
//     Threat model: attacker stores the raw packet at t=T_store and replays
//     the original bytes preserving τ_store and the original nonce.
//       Eq. 3.16 violated: |τr − τ_store| = T_replay − T_store ≫ T_b + ε
//       Eq. 3.17 violated: nonce(sender_id, τ_store) consumed at t=T_store
//     Both checks fire → TetaGuardCryptoFilter drops TTW S1/S2 at Stage 0.
//     Counter: tg_crypto_drop_stale (Eq. 3.16 is §3.4.9's primary citation).
//     Stage 0 TP is correctly recorded: PemRecordObservation(true, 1.0, true).
//     TGN (Stage 1) never sees TTW S1/S2 events — consistent with §3.4.9
//     "eliminated before reaching the TGN detector."
//
//   BSHH — malicious vehicle / malicious RSU (S1/S2):
//     §3.4.9: "mitigated at pre-detection stage through the threshold aggregate
//     signature condition defined in Eq. 3.26."
//     Eq. 3.26 is a THRESHOLD AGGREGATE SIGNATURE — NOT HMAC-SHA256 (Eq. 3.15):
//       Verify_agg(σ_agg, PK_agg) = 1  ⟺  |{i : Verify(σ_i, msg_i, PK_Vi)=1}| ≥ t
//     The attacker holds zero of the required t ML-DSA-87 key shares → zero valid
//     partial signatures → far below threshold → Eq. 3.26 fails → DROPPED at Step 1.
//     §3.4.5, Eq. 3.28 explicitly specifies ML-DSA-87 (NIST FIPS 204, Dilithium5)
//     as the signing scheme.  This is the IDENTITY / AUTHENTICATION check (Step 1),
//     using a distinct cryptographic primitive from HMAC-SHA256 — not Eq. 3.15.
//     In the simulation tg_crypto_drop_mac counter records Step 1 failures broadly
//     (both Eq. 3.15 and Eq. 3.26); the "mac" name is a CSV-column legacy.
//     TGN (Stage 1) never sees BSHH S1/S2 events — they are silent-dropped here.
//
//   ME — malicious vehicle / malicious RSU, OUT-of-range reporters (S1/S2):
//     §3.4.9: "physically inconsistent reporters fail the range or RSSI validation
//     conditions (Eq. 3.11 / Eq. 3.29) and can therefore be filtered before
//     full-stack analysis."
//     Step 1 check: LOCATION-BINDING / RSSI distance gate (Eq. 3.29) — NOT
//     HMAC-SHA256 (Eq. 3.15).  ME attacker holds valid key → Eq. 3.15 PASSES.
//     The drop is purely positional: d(reporter_pos, link_endpoint) > r_comm.
//     Counter: tg_crypto_drop_mac (Step 1 identity/physical-consistency failure;
//     "mac" name is a CSV-column legacy — mechanism here is Eq. 3.29).
//
//   ME — malicious vehicle / malicious RSU, IN-range reporters (S1/S2 partial):
//     §3.4.9: "colluding infrastructure nodes may still pass individual verification
//     checks, requiring both cryptographic verification and TGN-based cross-observer
//     behavioral analysis."  Eq. 3.29 passes (reporter IS in range).
//     Eq. 3.30 (witness quorum) is then checked:
//       A link is accepted only when ≥ t=2 LEGITIMATE witnesses have confirmed
//       it at THIS trusted node.  Echo reporters cannot bootstrap their own quorum
//       (only non-attack events update the witness accumulator).
//     If quorum met → event proceeds to Stage 1; if not → deferred.
//     Stage 1 sig[6] (Eq. 3.8 reporter-count density) / sig[7] (Eq. 3.9) are the
//     PRIMARY detection mechanism for in-range ME — Stage 0 is partial prevention.
//
//   Controller-origin (all three families with malicious controller):
//     Controller holds valid session keys for all entities → bypasses Step 1 entirely.
//     It can also generate fresh timestamps and non-replayed nonces, so Steps 2–3
//     would pass too.  Stage 1 + blockchain divergence check are the sole defences.
// =============================================================================
// PemCryptoPreFilter — delegates to TetaGuardCryptoFilter() in
// .crypto_src/teta_guard_filter.h.
//
// Per-trusted-node dispatch: each RSU (Tier 1) or designated OBU (Tier 2)
// has its own nonce cache and witness accumulator via g_per_node_crypto_state
// keyed by event.reporter_id.  The controller verifier uses reporter_id=9999.
//
// All logic (Eqs. 3.15–3.17, 3.26–3.30) lives in TetaGuardCryptoFilter().
// This wrapper exists only so existing callers (PemEmitEvent etc.) need no
// change — they still call PemCryptoPreFilter(event).
static bool
PemCryptoPreFilter(const PemEvent& event)
{
    return TetaGuardCryptoFilter(event, event.reporter_id);
}

// Signs a genuine topology observation with the REPORTER'S OWN real
// Dilithium5 identity key (g_vehicle_dilithium_sk, captured in
// CryptoDeriveVehicleSessionKeys/MeasureKEM — Phase 1). Silently a no-op if
// the reporter has no captured key yet, isn't a registered fleet vehicle, or
// its cached report is still within one beacon interval of being fresh.
static void PemSignGenuineReport(uint32_t reporterId, uint32_t linkSrcId, uint32_t linkDstId,
                                  const Vector &reporterPosition,
                                  const Vector &linkSrcPosition,
                                  const Vector &linkDstPosition,
                                  double senderTimestamp, double simTime)
{
#ifdef HAVE_LIBOQS
    if (!g_crypto_ready) return;
    if (reporterId >= MAX_VEHICLES || !g_vehicle_dilithium_sk_ready[reporterId]) return;

    const auto key = std::make_tuple(reporterId, linkSrcId, linkDstId);
    auto it = g_pem_genuine_reports.find(key);
    if (it != g_pem_genuine_reports.end() &&
        (simTime - it->second.sim_time) < PEM_BEACON_INTERVAL_S)
        return;   // cached report is still fresh — no need to re-sign

    uint8_t vid[16] = {};
    vid[0] = (uint8_t)(reporterId & 0xFFu);
    vid[1] = (uint8_t)((reporterId >> 8) & 0xFFu);
    VehicleKeyRecord *rec = kem_lookup(vid);
    if (!rec) return;   // not a registered fleet vehicle — no CA cert to attach

    uint8_t link_id[8];
    PemBuildLinkId(linkSrcId, linkDstId, link_id);

    float reporter_lat, reporter_lon;
    PemSimToGps(reporterPosition, reporter_lat, reporter_lon);

    // RSSI at the reporter from its nearer link endpoint — same Cost231
    // distance model Stage-0's ME-S3 signature and PemVerifyQuorum both use,
    // so this evidence agrees with detection-side geometry.
    const double dSrc = PemDistance2d(reporterPosition, linkSrcPosition);
    const double dDst = PemDistance2d(reporterPosition, linkDstPosition);
    const double dNearest = (dSrc <= dDst) ? dSrc : dDst;
    const double safeD = (dNearest > 0.001) ? dNearest : 0.001;
    const float rssi_dbm = (float)(PemGetRssiMin() + 10.0 * PEM_RSSI_N_COST231
                                     * std::log10(PemGetRcomm() / safeD));

    const uint64_t sender_ts_ms = (uint64_t)std::llround(senderTimestamp * 1000.0);

    LocationBoundReport rpt;
    create_location_bound_report(link_id, reporter_lat, reporter_lon, rssi_dbm,
                                  sender_ts_ms, vid,
                                  g_vehicle_dilithium_sk[reporterId], rec->sign_pub_key,
                                  &rec->cert, &rpt);
    rpt.has_rsu_measurement   = true;
    rpt.rsu_measured_rssi_dbm = rssi_dbm;

    PemGenuineReport &slot = g_pem_genuine_reports[key];
    slot.report   = rpt;
    slot.sim_time = simTime;
#endif
}

static void
PemEmitEvent(PemEventType type,
             uint32_t physicalSenderId,
             uint32_t claimedSenderId,
             uint32_t reporterId,
             uint32_t linkSrcId,
             uint32_t linkDstId,
             double senderTimestamp,
             double receptionTimestamp,
             const Vector& reporterPosition,
             const Vector& linkSrcPosition,
             const Vector& linkDstPosition,
             bool attackLabel,
             uint32_t macSignerIdOverride)
{
    PemStageTimer __pemDetectTimer(PemPipelineStage::kDetect);

    // Issue 6 fix — reject beacons/topology updates from a blacklisted sender
    // outright (report: "reject its beacons"), before they reach Stage-0 or
    // any detector. g_blacklisted_nodes is populated by PemReadBlacklistFile()
    // polling /tmp/blacklist_vehicle_ids.txt.
    if (g_blacklisted_nodes.count(physicalSenderId))
    {
        return;
    }

    PemEvent event;
    event.sim_time = Simulator::Now().GetSeconds();
    event.type = type;
    event.physical_sender_id = physicalSenderId;
    event.claimed_sender_id = claimedSenderId;
    event.reporter_id = reporterId;
    event.link_src_id = linkSrcId;
    event.link_dst_id = linkDstId;
    event.sender_timestamp = senderTimestamp;
    event.reception_timestamp = receptionTimestamp;
    event.reporter_position = reporterPosition;
    event.link_src_position = linkSrcPosition;
    event.link_dst_position = linkDstPosition;
    event.attack_label = attackLabel;
    event.score = 0.0;
    event.alert_raised = false;
    event.detection_latency_ms = -1.0;
    event.rssi_reporter_dbm = PEM_SIGNAL_PLACEHOLDER;  // set by PemEvaluateEvent for topology events

    // Phase 2 (Eq. 3.27-3.28): genuine, non-forged topology observations get a
    // real Dilithium5-signed LocationBoundReport cached under the reporter's
    // own key, for PemVerifyQuorum (Eq. 3.29-3.30) to consult later. Restricted
    // to topology-update events and attackLabel==false — this is evidence for
    // the location-binding quorum gate, not an input to the 9 LW detection
    // signatures above, which are untouched by this call.
    if (type == PEM_EVENT_TOPOLOGY_UPDATE && !attackLabel)
    {
        PemSignGenuineReport(reporterId, linkSrcId, linkDstId,
                              reporterPosition, linkSrcPosition, linkDstPosition,
                              senderTimestamp, event.sim_time);
    }

    // Sign the event with whichever key the sender actually possesses before
    // Stage-0 sees it — event.message_mac is the "attached" MAC a real packet
    // would carry. Default signs with physicalSenderId (the honest case: the
    // true physical sender's own key). macSignerIdOverride lets a
    // sophisticated key-exfiltration attacker sign with a genuinely stolen
    // identity's key instead, without ever touching physical_sender_id
    // itself (which stays ground truth — see TetaGuardSignEvent's comment).
    TetaGuardSignEvent(event,
        (macSignerIdOverride != UINT32_MAX) ? macSignerIdOverride : physicalSenderId,
        reporterId);

    // Stage 0 — Crypto pre-filter (Algorithm 3 LW-MITIGATE, Eqs. 3.15-3.17).
    // A6 (--no_crypto=1): bypass entirely — all events pass through to Stage-1.
    // Events that fail any check are silently dropped here and never reach
    // the Signature Detector or the TGN inference engine.
    if (!g_abl.no_crypto && !PemCryptoPreFilter(event))
    {
        // Node-level tracking: Stage-0 drop of an attack event counts as a detection.
        pem_all_seen_node_ids.insert(physicalSenderId);
        if (attackLabel)
        {
            pem_actual_attacker_nodes.insert(physicalSenderId);
            pem_detected_attacker_nodes.insert(physicalSenderId);
            PemCryptoRegisterDetection(physicalSenderId, reporterId);
            g_tgn_stage0_blocked_attacks++;
            g_tgn_flagged_nodes.insert(physicalSenderId);
        }
        // Ground-truth leak fix (threats-to-validity review, 8th instance found):
        // LKH revocation — a real mitigation ACTION, not a scoring statistic —
        // previously only fired inside the `if (attackLabel)` branch above. A
        // real controller has no ground-truth oracle telling it whether a
        // message it just rejected at Stage 0 genuinely came from an attacker;
        // it only knows "this message failed crypto verification" (Eqs.
        // 3.15-3.17). That rejection itself is the only real signal available,
        // so revocation now fires for ANY Stage-0 drop, matching what an actual
        // deployment would do — including the (accurately modelled) consequence
        // that a benign sender whose message spuriously fails verification
        // (clock skew, packet loss, corruption) gets revoked too, exactly as it
        // would in reality. The TP/FP/FN bookkeeping above remains ground-truth
        // gated, since that is legitimate offline-evaluation labeling, not a
        // detection or mitigation decision.
        if (g_lkh_ready &&
            g_lkh_already_revoked.size() < g_lkh_n_leaves &&
            g_lkh_already_revoked.find(physicalSenderId) == g_lkh_already_revoked.end())
        {
            uint32_t leaf_idx = physicalSenderId % g_lkh_n_leaves;
            lkh_revoke_vehicle(&g_lkh_tree, g_lkh_vids[leaf_idx]);
            g_lkh_already_revoked.insert(physicalSenderId);
            // Eq. 3.40 cond.1 — a revoked node no longer holds a valid
            // consortium certificate and is immediately peer-ineligible.
            if (g_trust_table.count(physicalSenderId))
                g_trust_table[physicalSenderId].cert_valid = false;
            const uint32_t depth = (g_lkh_n_leaves > 1u)
                ? (uint32_t)std::ceil(std::log2((double)g_lkh_n_leaves)) : 0u;
            printf("[LKH][t=%.3f] Revoked V%u (leaf %u) — O(log %u)=%u KEK updates"
                   " (Eq. 3.18, Stage-0 detection)\n",
                   Simulator::Now().GetSeconds(),
                   physicalSenderId, leaf_idx, g_lkh_n_leaves, depth);
        }
        PemRecordObservation(attackLabel, 1.0, attackLabel);
        return;  // silent drop — no alert label, no ledger entry, no FlowMod
    }

    // Stage 1 — Signature Detector (Algorithm 1, Eq. 3.12).
    PemEvaluateEvent(event);
}

static void
PemEmitHeartbeatEvent(uint32_t physicalSenderId,
                      uint32_t claimedSenderId,
                      double senderTimestamp,
                      bool attackLabel,
                      uint32_t macSignerIdOverride)
{
    Vector reporterPosition(0.0, 0.0, 0.0);
    Vector endpointPosition(0.0, 0.0, 0.0);
    PemEmitEvent(PEM_EVENT_HEARTBEAT,
                 physicalSenderId,
                 claimedSenderId,
                 physicalSenderId,
                 claimedSenderId,
                 claimedSenderId,
                 senderTimestamp,
                 Simulator::Now().GetSeconds(),
                 reporterPosition,
                 endpointPosition,
                 endpointPosition,
                 attackLabel,
                 macSignerIdOverride);
}

// ── ID-space fix ─────────────────────────────────────────────────────────────
// senderId/receiverId are real ns-3 GLOBAL node IDs (matching every other
// PemEmit*/PemEvent caller's convention throughout the file), NOT
// Vehicle_Nodes container indices. This was previously inconsistent: this
// function did `Vehicle_Nodes.Get(senderId)` directly (a container-index
// lookup) while emitting senderId itself as the event's claimed_sender_id (a
// global-ID-shaped field everywhere else) — silently resolving to the WRONG
// vehicle's position/range whenever N_Controllers/N_RSUs > 0 (i.e. whenever
// global ID != container index, which is every real run: node creation order
// is controllers -> management -> vehicles -> RSUs, so
// Vehicle_Nodes.Get(cidx)->GetId() == cidx + N_Controllers + 1). Two call
// sites (BSHH_S2_LegitimateExchange, BSHH_S3-style RSU exchange) had already
// discovered this and worked around it locally with their own linear-scan
// cidx conversion before calling this function — those workarounds are
// removed below now that the fix lives here, at the source, so every caller
// (TTW-S1/S2, BSHH-S1..S4, ME-S1..S4) benefits without needing its own patch.
// Confirmed root cause: TTW-S1's HELLO-time beacon was recorded under the
// wrong ID space entirely, so signature Eq. 3.3 (TTW-S2 label in PEM CSV
// output) could never find its own beacon record at attack time except by
// coincidental cross-vehicle ID collision — producing both false negatives
// and spurious/coincidental "detections" that weren't really testing the
// intended condition.
static void
PemEmitVehicleBeacon(uint32_t senderId, uint32_t receiverId)
{
    Ptr<Node> senderNode = nullptr, receiverNode = nullptr;
    for (uint32_t k = 0; k < Vehicle_Nodes.GetN(); ++k) {
        if (Vehicle_Nodes.Get(k)->GetId() == senderId)   senderNode   = Vehicle_Nodes.Get(k);
        if (Vehicle_Nodes.Get(k)->GetId() == receiverId) receiverNode = Vehicle_Nodes.Get(k);
    }
    if (!senderNode || !receiverNode)
    {
        return;
    }

    Ptr<MobilityModel> senderMobility = senderNode->GetObject<MobilityModel>();
    Ptr<MobilityModel> receiverMobility = receiverNode->GetObject<MobilityModel>();
    if (!senderMobility || !receiverMobility)
    {
        return;
    }

    Vector senderPosition = senderMobility->GetPosition();
    Vector receiverPosition = receiverMobility->GetPosition();

    // ── NPFADS BSM record (recorded BEFORE range check) ────────────────────
    // NPFADS needs position history for every vehicle that emits a beacon,
    // regardless of whether sender and receiver are within DSRC range.
    // TTW/BSHH/ME attacks don't falsify GPS, so xPos == trueXPos always.
    // NPFADS will classify all senders as benign — proving these temporal
    // attacks are invisible to position-based detection.
    {
        Vector senderVel = senderMobility->GetVelocity();
        double now       = Simulator::Now().GetSeconds();

        NpfadsBsmRecord rec;
        rec.sendTime   = now;
        rec.senderId   = senderId;
        rec.xPos       = senderPosition.x;
        rec.yPos       = senderPosition.y;
        rec.xSpd       = senderVel.x;
        rec.ySpd       = senderVel.y;
        rec.trueXPos   = senderPosition.x;
        rec.trueYPos   = senderPosition.y;
        rec.attackType = 0;   // NPFADS_BENIGN: TTW/BSHH/ME are not position attacks

        auto it = g_routing_last_bsm.find(senderId);
        if (it != g_routing_last_bsm.end())
        {
            double dt = now - it->second.sendTime;
            if (dt > 1e-9)
            {
                rec.xAcc = (rec.xSpd - it->second.xSpd) / dt;
                rec.yAcc = (rec.ySpd - it->second.ySpd) / dt;
            }
            else
            {
                rec.xAcc = rec.yAcc = 0.0;
            }
        }
        else
        {
            rec.xAcc = rec.yAcc = 0.0;
        }

        g_routing_last_bsm[senderId] = rec;
        g_routing_bsm_log.push_back(rec);
    }
    // ── End NPFADS BSM record ───────────────────────────────────────────────

    // BSHH-S3 presence stamp: senderId physically broadcasts this beacon
    // regardless of whether receiverId is in range (broadcast medium), so
    // this must happen before the range-gated early return below.
    g_pem_last_beacon_time[senderId] = Simulator::Now().GetSeconds();
    // ME-S3 oracle fix: record senderId's own attested position at the moment
    // it broadcasts (see g_last_self_reported_position's declaration comment).
    g_last_self_reported_position[senderId] = senderPosition;
    // Issue 12 fix: same broadcast-medium reasoning — trusted-peer beacon
    // evidence (B_nk(t)) is recorded regardless of receiverId's range.
    PemRecordBeaconEvidence(senderId, senderPosition, Simulator::Now().GetSeconds());

    const double distance =
        std::sqrt(std::pow(senderPosition.x - receiverPosition.x, 2.0) +
                  std::pow(senderPosition.y - receiverPosition.y, 2.0));
    if (distance > TTW_COMM_RANGE)
    {
        return;
    }

    PemEmitEvent(PEM_EVENT_BEACON,
                 senderId,
                 senderId,
                 senderId,
                 senderId,
                 receiverId,
                 Simulator::Now().GetSeconds(),
                 Simulator::Now().GetSeconds(),
                 senderPosition,
                 senderPosition,
                 receiverPosition,
                 false);
}

// ── Continuous mobility-derived neighbor observation (opt-in, see
// g_enable_neighborhood_beaconing) ──────────────────────────────────────────
// Unlike PemEmitVehicleBeacon (self-reporting: physical/claimed/reporter all
// equal senderId), a real beacon is transmitted by one vehicle and observed
// by every OTHER vehicle in range, so this records who observed whom:
//   claimed_sender_id = transmitter (who broadcast)
//   reporter_id       = receiver    (who heard it)
// Deliberately does NOT call PemEmitEvent/PemEmitVehicleBeacon/PemEvaluateEvent
// — it feeds only g_rsu_beacon_log (ME's lambda_hat/rho_max/delta_max) and TGN's
// beacon-count window via TGN_ProcessNeighborObservationInline, so it can never
// touch ns.event_window, tp/fp/fn/tn counters, or pem_event_log.csv. See the
// "Continuous mobility-derived neighborhood beaconing" plan for full rationale.
// Returns true iff transmitter/receiver were in range and an observation was
// recorded (used only for the statistics counters in PemNeighborhoodDiscoveryTick,
// never for detection logic).
static bool
PemEmitNeighborObservation(uint32_t transmitterId, uint32_t receiverId)
{
    if (transmitterId == receiverId) return false;   // defensive; caller already excludes this
    if (transmitterId >= Vehicle_Nodes.GetN() || receiverId >= Vehicle_Nodes.GetN())
    {
        return false;
    }

    Ptr<MobilityModel> transmitterMobility = Vehicle_Nodes.Get(transmitterId)->GetObject<MobilityModel>();
    Ptr<MobilityModel> receiverMobility = Vehicle_Nodes.Get(receiverId)->GetObject<MobilityModel>();
    if (!transmitterMobility || !receiverMobility)
    {
        return false;
    }

    Vector transmitterPosition = transmitterMobility->GetPosition();
    Vector receiverPosition = receiverMobility->GetPosition();

    if (PemDistance2d(transmitterPosition, receiverPosition) > TTW_COMM_RANGE)
    {
        return false;
    }

    // Value-initialize (PemEvent event{};), not PemEvent event; — PemComputeLambdaHat
    // checks `if (w->type != PEM_EVENT_BEACON) continue;`, so an uninitialized `type`
    // on a stack PemEvent could silently vanish from (or corrupt) the ME density
    // computation. This is a correctness requirement, not just style.
    PemEvent event{};
    event.type          = PEM_EVENT_BEACON;
    event.attack_label  = false;
    event.sim_time             = Simulator::Now().GetSeconds();
    event.sender_timestamp     = Simulator::Now().GetSeconds();
    event.reception_timestamp  = Simulator::Now().GetSeconds();

    event.claimed_sender_id = transmitterId;   // vehicle that transmitted the beacon
    event.physical_sender_id = transmitterId;  // Simulator ground truth only — this is
                                                // NOT receiver-derived PHY evidence and
                                                // must not be used for real-world
                                                // attacker attribution decisions; kept
                                                // for schema completeness only.
    event.reporter_id       = receiverId;      // vehicle that heard/observed the beacon
    event.link_src_id       = transmitterId;
    event.link_dst_id       = receiverId;

    // PemComputeLambdaHat (routing.cc, PemComputeLambdaHat) computes
    //   dist(w->reporter_position, event.link_src/dst_position) <= TTW_COMM_RANGE
    //   -> vehiclesNearLink.insert(w->claimed_sender_id)
    // i.e. it was written under the old self-reporting convention where
    // reporter_id == claimed_sender_id, so it implicitly treats reporter_position as
    // "the position of whichever vehicle is about to be inserted into the density
    // set" — that vehicle is claimed_sender_id (the transmitter), not reporter_id
    // (the receiver). Since PemEvent has no separate claimed_sender_position field,
    // reporter_position must stay pinned to the TRANSMITTER's position here even
    // though reporter_id itself is the receiver, or every density-estimate lookup
    // silently attributes the wrong vehicle's position to the wrong ID.
    event.reporter_position = transmitterPosition;   // NOT receiverPosition — see above
    event.link_src_position = transmitterPosition;
    event.link_dst_position = receiverPosition;
    event.rssi_reporter_dbm = PEM_SIGNAL_PLACEHOLDER;

    // Historical name: g_rsu_beacon_log. Stores RSU observations and, when continuous
    // neighborhood beaconing is enabled, mobility-derived vehicle neighbor observations
    // too. Consumed by PemComputeLambdaHat/PemComputeRhoMaxForLink/PemComputeDeltaMax as
    // a generic topology-observation log — the name is not changed here to avoid
    // touching every existing reader site.
    g_rsu_beacon_log.push_back(event);
    PemTrimRsuBeaconLog(event.reception_timestamp);

    if (!g_abl.no_tgn)
    {
        TGN_ProcessNeighborObservationInline(event);
    }

    return true;
}

static void
PemEmitVehicleHeartbeat(uint32_t senderId,
                        uint32_t claimedSenderId,
                        double senderTimestamp,
                        bool attackLabel)
{
    PemEmitHeartbeatEvent(senderId, claimedSenderId, senderTimestamp, attackLabel);
}

// ── §3.1.3 / Algorithm 1 — continuous T_b-periodic beacon stream ────────────
// Previously PemEmitVehicleBeacon was only ever called from 10 one-shot,
// scenario-specific call sites at a fixed t≈10s — never on a recurring timer
// for the general vehicle population. Algorithm 1's correctness assumes a
// continuously-refreshed beacon stream feeding ns.event_window: BSHH-S3 (Eq.
// 3.7, "no beacon within window W corroborating Vi's presence") and ME-S1's
// λ̂ density estimate (PemComputeLambdaHat, counts BEACON events in the
// window) both silently degrade to near-meaningless values once a single
// seed beacon ages out, regardless of whether vehicles are actually live.
//
// PemPeriodicBeaconTick() broadcasts every vehicle to every other vehicle
// each T_b interval; PemEmitVehicleBeacon() already range-gates internally
// (returns early if distance > TTW_COMM_RANGE), so only pairs actually within
// DSRC range produce a PEM_EVENT_BEACON. O(N²) calls per interval is trivial
// at this project's scale (N_Vehicles = 2-8 across all 12 scenarios).
static void __attribute__((unused))
PemPeriodicBeaconTick()
{
    // NOTE: dead code (unused, superseded by PemNeighborhoodDiscoveryTick /
    // PemEmitNeighborObservation). If ever revived: i,j here are Vehicle_Nodes
    // container indices, but PemEmitVehicleBeacon now expects real ns-3
    // GLOBAL IDs (fixed at its definition) — this call would need
    // Vehicle_Nodes.Get(i)->GetId()/Get(j)->GetId(), same fix as TTW-S1's
    // HELLO step got.
    const uint32_t n = Vehicle_Nodes.GetN();
    for (uint32_t i = 0; i < n; ++i) {
        for (uint32_t j = 0; j < n; ++j) {
            if (i == j) continue;
            PemEmitVehicleBeacon(i, j);
        }
    }

    if (Simulator::Now().GetSeconds() + PEM_BEACON_INTERVAL_S < simTime) {
        Simulator::Schedule(Seconds(PEM_BEACON_INTERVAL_S), &PemPeriodicBeaconTick);
    }
}

// ── Continuous neighborhood discovery tick (opt-in: g_enable_neighborhood_beaconing) ──
// Redesigned replacement for PemPeriodicBeaconTick above: instead of routing
// through PemEmitVehicleBeacon (which floods ns.event_window/tp/fp/fn counters
// via PemEmitEvent -> PemEvaluateEvent — see the Gap 13 regression note near
// this flag's scheduling site in main()), this calls PemEmitNeighborObservation,
// which feeds only g_rsu_beacon_log and TGN's beacon-count window. Outer loop
// variable is the transmitter; inner loop variable is a candidate receiver —
// PemEmitNeighborObservation(transmitter, receiver) range-gates internally and,
// if in range, records "receiver observed transmitter" (not a self-report).
static const double PEM_NEIGHBORHOOD_WARMUP_S = 10.0;   // matches the file's existing
                                                          // t~=10s "network settled"
                                                          // convention (e.g. TTW_HELLO_TIME)
                                                          // so initial SUMO placement /
                                                          // mobility-startup transients
                                                          // never get recorded as topology
                                                          // evidence.
static uint64_t g_neighbor_observation_count = 0;        // successful (in-range) observations
static uint64_t g_neighbor_candidate_pair_count = 0;     // every (transmitter, receiver) checked
static uint64_t g_neighbor_tick_count = 0;               // ticks actually executed past warm-up
static uint32_t g_max_neighbor_count = 0;

// ── Real-time budget check (wall-clock, not simulated time) ─────────────────
// T_b = PEM_BEACON_INTERVAL_S (100ms) is the interval at which the NEXT beacon
// arrives in a real deployment. If this tick's own O(N^2) discovery sweep takes
// longer than that in actual CPU time, the pipeline would fall behind incoming
// beacons on real hardware — NS-3's discrete-event scheduler itself doesn't
// care (simulated time and wall-clock time are decoupled here), but this is a
// real feasibility concern for whether the design could run live. Uses the
// same HiResClock/MicroSec convention already used for crypto-op timing above.
static double   g_neighbor_tick_max_wallclock_ms = 0.0;
static double   g_neighbor_tick_total_wallclock_ms = 0.0;
static uint64_t g_neighbor_tick_over_budget_count = 0;

static void __attribute__((unused))
PemNeighborhoodDiscoveryTick()
{
    if (Simulator::Now().GetSeconds() < PEM_NEIGHBORHOOD_WARMUP_S) {
        if (Simulator::Now().GetSeconds() + PEM_BEACON_INTERVAL_S < simTime) {
            Simulator::Schedule(Seconds(PEM_BEACON_INTERVAL_S), &PemNeighborhoodDiscoveryTick);
        }
        return;
    }

    const auto tickStart = HiResClock::now();

    const uint32_t n = Vehicle_Nodes.GetN();
    uint32_t neighborsThisTick = 0;
    for (uint32_t transmitter = 0; transmitter < n; ++transmitter) {
        uint32_t neighborsThisTx = 0;
        for (uint32_t receiver = 0; receiver < n; ++receiver) {
            if (transmitter == receiver) continue;
            ++g_neighbor_candidate_pair_count;
            if (PemEmitNeighborObservation(transmitter, receiver)) {
                ++g_neighbor_observation_count;
                ++neighborsThisTx;
                ++neighborsThisTick;
            }
        }
        if (neighborsThisTx > g_max_neighbor_count) g_max_neighbor_count = neighborsThisTx;
    }
    ++g_neighbor_tick_count;
    (void)neighborsThisTick;

    const double tickWallclockMs = MicroSec(HiResClock::now() - tickStart).count() / 1000.0;
    g_neighbor_tick_total_wallclock_ms += tickWallclockMs;
    if (tickWallclockMs > g_neighbor_tick_max_wallclock_ms) {
        g_neighbor_tick_max_wallclock_ms = tickWallclockMs;
    }
    const double budgetMs = PEM_BEACON_INTERVAL_S * 1000.0;   // T_b, the next-beacon deadline
    if (tickWallclockMs > budgetMs) {
        ++g_neighbor_tick_over_budget_count;
        std::cout << "[WARN][t=" << Simulator::Now().GetSeconds() << "] Continuous "
                  << "neighborhood discovery tick took " << tickWallclockMs << " ms, "
                  << "exceeding the " << budgetMs << " ms beacon-interval budget (T_b) — "
                  << "on real hardware this pipeline would fall behind the next beacon.\n";
    }

    if (Simulator::Now().GetSeconds() + PEM_BEACON_INTERVAL_S < simTime) {
        Simulator::Schedule(Seconds(PEM_BEACON_INTERVAL_S), &PemNeighborhoodDiscoveryTick);
    }
}

// ── BSHH-S3 presence tick (Eq. 3.7) — lightweight, decoupled alternative to
// PemPeriodicBeaconTick() above. Only stamps g_pem_last_beacon_time[i] for
// every vehicle each T_b interval; does NOT call PemEmitEvent/PemEvaluateEvent,
// so it never touches ns.event_window (the shared sliding window TTW/ME
// signatures also scan) and carries none of the O(N^2) PemEmitVehicleBeacon
// overhead (NPFADS BSM logging, crypto pre-filter, scoring) that caused the
// earlier regression. This models the real-world fact that every vehicle
// broadcasts a DSRC beacon every T_b regardless of whether any particular
// receiver is in range or whether that beacon is signature-relevant.
static void
PemBshh3PresenceTick()
{
    const double now = Simulator::Now().GetSeconds();
    const uint32_t n = Vehicle_Nodes.GetN();
    const uint32_t nRsu = RSU_Nodes.GetN();

    // Ground-truth leak fix (threats-to-validity review): every vehicle DOES
    // physically transmit a beacon every T_b (broadcast medium, true
    // regardless of range) — that part of the original comment is correct.
    // But unconditionally stamping ALL n vehicles gave BSHH-S3 universal,
    // range-independent reachability: even a vehicle with no RSU or peer
    // within r_comm was marked "present," which no single real verifier could
    // ever witness (a beacon nobody was in range to receive corroborates
    // nothing). Fixed by only stamping vehicle i when at least one other
    // vehicle or RSU is within g_rcomm of it — i.e. the beacon was physically
    // deliverable to SOME real receiver, matching the same range gate
    // PemEmitVehicleBeacon's real radio path already enforces (its `distance
    // > TTW_COMM_RANGE` early return) for the signature-relevant beacon flow.
    // An isolated vehicle beyond everyone's range is correctly NOT stamped —
    // BSHH-S3 should be able to fire for it, since nobody could have observed
    // its liveness at that moment.
    std::vector<Vector> vehiclePos(n);
    for (uint32_t i = 0; i < n; ++i) {
        Ptr<MobilityModel> m = Vehicle_Nodes.Get(i)->GetObject<MobilityModel>();
        vehiclePos[i] = m ? m->GetPosition() : Vector(0.0, 0.0, 0.0);
    }
    std::vector<Vector> rsuPos(nRsu);
    for (uint32_t r = 0; r < nRsu; ++r) {
        Ptr<MobilityModel> m = RSU_Nodes.Get(r)->GetObject<MobilityModel>();
        rsuPos[r] = m ? m->GetPosition() : Vector(0.0, 0.0, 0.0);
    }

    for (uint32_t i = 0; i < n; ++i) {
        bool hasWitnessInRange = false;
        for (uint32_t r = 0; r < nRsu && !hasWitnessInRange; ++r) {
            if (PemDistance2d(vehiclePos[i], rsuPos[r]) <= g_rcomm) {
                hasWitnessInRange = true;
            }
        }
        for (uint32_t j = 0; j < n && !hasWitnessInRange; ++j) {
            if (j == i) continue;
            if (PemDistance2d(vehiclePos[i], vehiclePos[j]) <= g_rcomm) {
                hasWitnessInRange = true;
            }
        }
        if (!hasWitnessInRange) {
            continue;   // nobody could have received this beacon — do not stamp
        }
        // Stamp both ID conventions in use across attack functions: some
        // (e.g. TTW_*) address vehicles by container index i directly;
        // others (e.g. BSHH_S1, which uses Vehicle_Nodes.Get(idx)->GetId())
        // address them by the global ns-3 node ID, which is offset by
        // whatever non-vehicle nodes (controller/management) were created
        // first. Stamping both is cheap and avoids silently missing one
        // convention's identity space.
        g_pem_last_beacon_time[i] = now;
        g_pem_last_beacon_time[Vehicle_Nodes.Get(i)->GetId()] = now;
    }

    if (now + PEM_BEACON_INTERVAL_S < simTime) {
        Simulator::Schedule(Seconds(PEM_BEACON_INTERVAL_S), &PemBshh3PresenceTick);
    }
}

// ── Trust reward tick (§3.4.11 Eq. 3.38 correct-participation branch) ───────
// TrustUpdateNode(id, correct_participation, flagged) has always been called
// with flagged=true (penalty branch) from every attack-detection call site —
// there was no analogue of the chaincode's periodic updateTrust(peer, true,
// false) reward step (UpdateTrustRound / runMitigation's TE-07 bump on
// trust.go), so no peer's tau could ever rise off its Tier-2 init value
// (0.10). That silently kept TrustGetTrustedPeers()'s tau >= TRUST_TAU_GT_MIN
// (0.50) filter permanently unsatisfiable for OBUs in no-RSU deployments,
// which in turn kept E_t^trusted (PemGetTrustedEvidence) permanently empty
// and made PemComputeControllerDivergenceDelta count every controller-claimed
// edge as divergent by definition — a structural false-positive source for
// the TTW-S3/BSHH-S3/ME-S3 controller-divergence gate. This models "trust is
// re-evaluated at every beacon interval" (Table 3.4 derivation: R_min=8 is
// exactly (0.50-0.10)/0.05, i.e. it assumes a reward tick fires every round).
//
// Deliberately as lightweight as PemBshh3PresenceTick above — touches only
// g_trust_table (no PemEmitEvent/ns.event_window interaction) — so it cannot
// reproduce the Gap 13 regression documented there. Skips any peer already
// TRUST_QUARANTINE/TRUST_REMOVED so a reward tick can never claw a flagged
// attacker's trust back up; TrustUpdateNode's own flagged=true penalty path
// (called separately, at detection time) remains the only way to demote.
static void
TrustPeriodicRewardTick()
{
    const double now = Simulator::Now().GetSeconds();
    for (auto& kv : g_trust_table) {
        if (kv.second.state != TRUST_ACTIVE) continue;
        TrustUpdateNode(kv.first, /*correct_participation=*/true, /*flagged=*/false);
    }

    if (now + PEM_BEACON_INTERVAL_S < simTime) {
        Simulator::Schedule(Seconds(PEM_BEACON_INTERVAL_S), &TrustPeriodicRewardTick);
    }
}

