// Maps attack_scenario (1–12) to the present_*_attack_* flags.
// Called once after cmd.Parse(), before declare_attackers().
void declare_attack_states()
{
    // Reset all flags first.
    present_ttw_attack_nodes         = false;
    present_bshh_attack_nodes        = false;
    present_me_attack_nodes          = false;
    present_ttw_attack_controllers   = false;
    present_bshh_attack_controllers  = false;
    present_me_attack_controllers    = false;

    // TTW family (scenarios 1–4)
    if (attack_scenario >= TTW_S1_MAL_VEH_NO_RSU &&
        attack_scenario <= TTW_S4_MAL_CTRL_WITH_RSU)
    {
        present_ttw_attack_nodes = true;
        if (controller_malicious_assumption ||
            attack_scenario == TTW_S3_MAL_CTRL_NO_RSU ||
            attack_scenario == TTW_S4_MAL_CTRL_WITH_RSU)
        {
            present_ttw_attack_controllers = true;
        }
        // RSU is in the data path for S2 and S4.
        if (attack_scenario == TTW_S2_MAL_RSU ||
            attack_scenario == TTW_S4_MAL_CTRL_WITH_RSU)
            has_RSU_infrastructure = true;
    }
    // BSHH family (scenarios 5–8)
    else if (attack_scenario >= BSHH_S1_MAL_VEH_NO_RSU &&
             attack_scenario <= BSHH_S4_MAL_CTRL_WITH_RSU)
    {
        present_bshh_attack_nodes = true;
        if (controller_malicious_assumption ||
            attack_scenario == BSHH_S3_MAL_CTRL_NO_RSU ||
            attack_scenario == BSHH_S4_MAL_CTRL_WITH_RSU)
        {
            present_bshh_attack_controllers = true;
        }
        if (attack_scenario == BSHH_S2_MAL_RSU ||
            attack_scenario == BSHH_S4_MAL_CTRL_WITH_RSU)
            has_RSU_infrastructure = true;
    }
    // ME family (scenarios 9–12)
    else if (attack_scenario >= ME_S1_MAL_VEH_NO_RSU &&
             attack_scenario <= ME_S4_MAL_CTRL_WITH_RSU)
    {
        present_me_attack_nodes = true;
        if (controller_malicious_assumption ||
            attack_scenario == ME_S3_MAL_CTRL_NO_RSU ||
            attack_scenario == ME_S4_MAL_CTRL_WITH_RSU)
        {
            present_me_attack_controllers = true;
        }
        if (attack_scenario == ME_S2_MAL_RSU ||
            attack_scenario == ME_S4_MAL_CTRL_WITH_RSU)
            has_RSU_infrastructure = true;
    }
    // ATTACK_NONE (0): all flags remain false — baseline run.
}

static Ptr<UniformRandomVariable>
AttackGetRng()
{
    static Ptr<UniformRandomVariable> rng = CreateObject<UniformRandomVariable>();
    return rng;
}

template <typename T>
static void
AttackShuffleVector(std::vector<T>& values)
{
    if (values.size() < 2)
    {
        return;
    }

    Ptr<UniformRandomVariable> rng = AttackGetRng();
    for (uint32_t i = static_cast<uint32_t>(values.size()) - 1; i > 0; --i)
    {
        const uint32_t j = static_cast<uint32_t>(rng->GetInteger(0, i));
        std::swap(values[i], values[j]);
    }
}

static bool
AttackRoll(double probability)
{
    if (probability <= 0.0)
    {
        return false;
    }
    if (probability >= 1.0)
    {
        return true;
    }
    return AttackGetRng()->GetValue(0.0, 1.0) < probability;
}

static double
AttackSampleSignedJitter(double maxAbsSeconds)
{
    if (maxAbsSeconds <= 0.0)
    {
        return 0.0;
    }
    return AttackGetRng()->GetValue(-maxAbsSeconds, maxAbsSeconds);
}

static double
AttackMax(double lhs, double rhs)
{
    return (lhs > rhs) ? lhs : rhs;
}

static void
AttackSelectActiveVehicles(std::vector<uint32_t>& maliciousVehicles,
                           double activationProbability,
                           uint32_t minimumActiveCount = 1u)
{
    if (maliciousVehicles.empty())
    {
        return;
    }

    std::vector<uint32_t> activeVehicles;
    activeVehicles.reserve(maliciousVehicles.size());
    for (uint32_t vehicleIdx : maliciousVehicles)
    {
        if (AttackRoll(activationProbability))
        {
            activeVehicles.push_back(vehicleIdx);
        }
    }

    const uint32_t requiredActiveCount =
        std::min<uint32_t>(minimumActiveCount, maliciousVehicles.size());

    if (activeVehicles.size() < requiredActiveCount)
    {
        std::vector<uint32_t> inactiveVehicles;
        inactiveVehicles.reserve(maliciousVehicles.size());
        for (uint32_t vehicleIdx : maliciousVehicles)
        {
            if (std::find(activeVehicles.begin(), activeVehicles.end(), vehicleIdx) ==
                activeVehicles.end())
            {
                inactiveVehicles.push_back(vehicleIdx);
            }
        }

        AttackShuffleVector(inactiveVehicles);
        for (uint32_t vehicleIdx : inactiveVehicles)
        {
            if (activeVehicles.size() >= requiredActiveCount)
            {
                break;
            }
            activeVehicles.push_back(vehicleIdx);
        }
    }

    maliciousVehicles.swap(activeVehicles);
}

// Assigns malicious membership to every vehicle node and to up to 3 controllers
// based on attack_percentage.  Must be called after declare_attack_states() and
// after N_Vehicles is finalised.
//
// Controller assignment thresholds mirror LDA.cc:
//   pct <  10 → 0 malicious controllers
//   pct <  35 → 1 malicious controller  (index 0)
//   pct <  67 → 2 malicious controllers (indices 0–1)
//   pct < 101 → 3 malicious controllers (indices 0–2)
//   index 3 is never set malicious (reserved spare)
void declare_attackers()
{
    // ── Node assignment ──────────────────────────────────────────────────────
    ttw_malicious_nodes.assign(N_Vehicles, false);
    bshh_malicious_nodes.assign(N_Vehicles, false);
    me_malicious_nodes.assign(N_Vehicles, false);

    // Compute exact attacker count from attack_percentage (same approach as controller assignment).
    // First n_mal_veh vehicle indices are malicious; the rest are victims.
    // uint32_t n_mal_veh = (uint32_t)std::round(N_Vehicles * attack_percentage / 100.0);
    // if (n_mal_veh > N_Vehicles) n_mal_veh = N_Vehicles;

    // for (uint32_t i = 0; i < N_Vehicles; i++)
    // {
    //     bool attacking = (i < n_mal_veh);

    //     if (present_ttw_attack_nodes)   ttw_malicious_nodes[i]  = attacking;
    //     if (present_bshh_attack_nodes)  bshh_malicious_nodes[i] = attacking;
    //     if (present_me_attack_nodes)    me_malicious_nodes[i]   = attacking;
    // }

	    // Compute exact attacker count from attack_percentage.
    uint32_t n_mal_veh = (uint32_t)std::round(N_Vehicles * attack_percentage / 100.0);
    if (n_mal_veh > N_Vehicles) n_mal_veh = N_Vehicles;

    std::vector<uint32_t> indices(N_Vehicles);
    for (uint32_t i = 0; i < N_Vehicles; i++) indices[i] = i;
    // --Random=0: deterministic first-N vehicle selection.
    // --Random=1: randomly shuffle vehicles first, then take the first N.
    // The shuffled mode uses the shared attack RNG, so it is reproducible with
    // ns-3 RNG run control while changing across different RngRun values.
    if (Random != 0)
    {
        AttackShuffleVector(indices);
    }

    for (uint32_t i = 0; i < N_Vehicles; i++)
    {
        bool attacking = (i < n_mal_veh);
        uint32_t k = indices[i];

        if (present_ttw_attack_nodes)   ttw_malicious_nodes[k]  = attacking;
        if (present_bshh_attack_nodes)  bshh_malicious_nodes[k] = attacking;
        if (present_me_attack_nodes)    me_malicious_nodes[k]   = attacking;
    }



    // ── Controller assignment — TTW ──────────────────────────────────────────
    for (int k = 0; k < 4; k++) ttw_malicious_controllers[k] = false;
    if (present_ttw_attack_controllers)
    {
        if (attack_percentage >= 10)  ttw_malicious_controllers[0] = true;
        if (attack_percentage >= 35)  ttw_malicious_controllers[1] = true;
        if (attack_percentage >= 67)  ttw_malicious_controllers[2] = true;
        // index 3 intentionally left false
    }

    // ── Controller assignment — BSHH ─────────────────────────────────────────
    for (int k = 0; k < 4; k++) bshh_malicious_controllers[k] = false;
    if (present_bshh_attack_controllers)
    {
        if (attack_percentage >= 10)  bshh_malicious_controllers[0] = true;
        if (attack_percentage >= 35)  bshh_malicious_controllers[1] = true;
        if (attack_percentage >= 67)  bshh_malicious_controllers[2] = true;
    }

    // ── Controller assignment — ME ───────────────────────────────────────────
    for (int k = 0; k < 4; k++) me_malicious_controllers[k] = false;
    if (present_me_attack_controllers)
    {
        if (attack_percentage >= 10)  me_malicious_controllers[0] = true;
        if (attack_percentage >= 35)  me_malicious_controllers[1] = true;
        if (attack_percentage >= 67)  me_malicious_controllers[2] = true;
    }

    // ── Console summary ──────────────────────────────────────────────────────
    auto count_true = [](const std::vector<bool>& v) {
        uint32_t n = 0;
        for (bool b : v) n += b ? 1 : 0;
        return n;
    };
    auto count_ctrl = [](const bool arr[4]) {
        int n = 0;
        for (int k = 0; k < 4; k++) n += arr[k] ? 1 : 0;
        return n;
    };

    std::cout << "[declare_attackers] scenario=" << attack_scenario
              << "  pct=" << attack_percentage
              << "  Random=" << Random
              << "  N_Vehicles=" << N_Vehicles << "\n"
              << "  TTW  nodes=" << count_true(ttw_malicious_nodes)
              << "  controllers=" << count_ctrl(ttw_malicious_controllers) << "\n"
              << "  BSHH nodes=" << count_true(bshh_malicious_nodes)
              << "  controllers=" << count_ctrl(bshh_malicious_controllers) << "\n"
              << "  ME   nodes=" << count_true(me_malicious_nodes)
              << "  controllers=" << count_ctrl(me_malicious_controllers) << "\n";
}

// ── Log file init ─────────────────────────────────────────────────────────────
// Helper: look up a Vehicle_Nodes entry by its NS-3 node ID
static Ptr<Node> GetVehicleByNs3Id(uint32_t ns3_id) {
    for (uint32_t i = 0; i < Vehicle_Nodes.GetN(); i++) {
        if (Vehicle_Nodes.Get(i)->GetId() == ns3_id)
            return Vehicle_Nodes.Get(i);
    }
    return nullptr;
}

// ── TTW-S1 (Option B): real-SUMO natural link-break discovery ───────────────
// g_sumo_wp_map/g_sumo_initial_pos are populated once, in main(), while the
// SUMO .tcl trace is parsed (before any attack scheduling runs). These
// helpers let the S1 attacker/victim pairing search the REAL trajectory
// instead of assuming a synthetic converge/diverge model.

// Interpolated real SUMO position of vehicle `cidx` (Vehicle_Nodes container
// index) at time `t`, mirroring exactly what the simulator's
// ConstantVelocityMobilityModel will do (position snap at each waypoint,
// linear fill toward the next one).
static Vector TtwSumoPositionAt(uint32_t cidx, double t)
{
    Vector base = g_sumo_initial_pos.count(cidx) ? g_sumo_initial_pos[cidx] : Vector(0.0, 0.0, 0.0);
    auto it = g_sumo_wp_map.find(cidx);
    if (it == g_sumo_wp_map.end() || it->second.empty() || t <= it->second.front().t)
        return base;
    const auto& wps = it->second;
    for (size_t i = 0; i + 1 < wps.size(); i++) {
        if (t >= wps[i].t && t <= wps[i + 1].t) {
            double dt = wps[i + 1].t - wps[i].t;
            double frac = dt > 1e-9 ? (t - wps[i].t) / dt : 0.0;
            return Vector(wps[i].x + frac * (wps[i + 1].x - wps[i].x),
                          wps[i].y + frac * (wps[i + 1].y - wps[i].y), 0.0);
        }
    }
    return Vector(wps.back().x, wps.back().y, 0.0);
}

// Result of scanning a candidate attacker/victim pair's real trajectories
// for a genuine communication-range break.
struct TtwBreakEval {
    bool   found          = false;
    double breakTime      = 0.0;  // first time distance exceeds commRange
    double brokenDuration = 0.0;  // total time spent beyond commRange in the window
    double maxDist        = 0.0;  // largest separation reached beyond commRange
};

// Requires the pair to be within commRange at helloTime (so HELLO/topology
// discovery is physically plausible), then scans [searchStart, searchEnd]
// for how genuinely the link gets severed afterward.
static TtwBreakEval TtwEvaluateNaturalBreak(uint32_t attackerCidx, uint32_t victimCidx,
                                             double helloTime, double searchStart, double searchEnd,
                                             double commRange, double stepSec)
{
    TtwBreakEval r;
    if (PemDistance2d(TtwSumoPositionAt(attackerCidx, helloTime),
                       TtwSumoPositionAt(victimCidx, helloTime)) > commRange)
        return r;  // not in range at HELLO time -> not a viable candidate

    for (double t = searchStart; t <= searchEnd; t += stepSec) {
        double d = PemDistance2d(TtwSumoPositionAt(attackerCidx, t),
                                  TtwSumoPositionAt(victimCidx, t));
        if (d > commRange) {
            if (!r.found) { r.found = true; r.breakTime = t; }
            r.brokenDuration += stepSec;
            if (d > r.maxDist) r.maxDist = d;
        }
    }
    return r;
}

// One resolved attacker/victim assignment out of TtwFindNaturalBreakPairs.
struct TtwAssignedPair {
    uint32_t attackerCidx;
    uint32_t victimCidx;
    double   breakTime;
};

// Shared pair-selection search (Option B): for each attacker in attackerPool,
// scan victimPool (shrinking as victims get claimed) for the best-scoring
// candidate whose REAL SUMO trajectory is in range at helloTime and later
// genuinely exceeds commRange — exactly the loop TTW-S1 already runs inline
// (see the attack_scenario==1 block). Extracted so TTW-S2/S3/S4 and
// BSHH-S1..S4 can reuse it without duplicating the selection logic, while
// TTW-S1's own inline block is left untouched (zero regression risk to the
// one scenario already proven to work).
static std::vector<TtwAssignedPair>
TtwFindNaturalBreakPairs(const std::vector<uint32_t>& attackerPool,
                         std::vector<uint32_t> victimPool,   // copy — drained as victims are claimed
                         double helloTime, double searchStart, double searchEnd,
                         double commRange, double stepSec)
{
    std::vector<TtwAssignedPair> assigned;
    for (uint32_t attackerCidx : attackerPool)
    {
        int bestIdx = -1;
        TtwBreakEval best;
        for (size_t vi = 0; vi < victimPool.size(); vi++)
        {
            if (victimPool[vi] == attackerCidx) continue;  // never pair a node with itself
            TtwBreakEval ev = TtwEvaluateNaturalBreak(
                attackerCidx, victimPool[vi], helloTime,
                searchStart, searchEnd, commRange, stepSec);
            if (!ev.found) continue;
            const bool better =
                (bestIdx < 0) ||
                (ev.brokenDuration > best.brokenDuration) ||
                (ev.brokenDuration == best.brokenDuration && ev.maxDist > best.maxDist) ||
                (ev.brokenDuration == best.brokenDuration && ev.maxDist == best.maxDist
                 && ev.breakTime < best.breakTime);
            if (better) { bestIdx = (int)vi; best = ev; }
        }
        if (bestIdx < 0) continue;  // no natural break found for this attacker — caller logs/skips
        uint32_t victimCidx = victimPool[(size_t)bestIdx];
        victimPool.erase(victimPool.begin() + bestIdx);
        assigned.push_back({attackerCidx, victimCidx, best.breakTime});
    }
    return assigned;
}

