// ── STEP 1: V2V HELLO beacon ──────────────────────────────────────────────────
void TTW_SendHelloBeacon(Ptr<Node> sender, Ptr<Node> receiver)
{
    double now = Simulator::Now().GetSeconds();

    Ptr<MobilityModel> mob_s = sender->GetObject<MobilityModel>();
    Ptr<MobilityModel> mob_r = receiver->GetObject<MobilityModel>();
    if (!mob_s || !mob_r) { NS_LOG_WARN("[TTW-S4] mobility model missing"); return; }

    Vector ps = mob_s->GetPosition();
    Vector pr = mob_r->GetPosition();
    double dist = std::sqrt(std::pow(ps.x-pr.x,2.0) + std::pow(ps.y-pr.y,2.0));
    bool   ok   = (dist <= TTW_COMM_RANGE);

    NS_LOG_INFO("[TTW-S4] t=" << now << "s  STEP-1 HELLO"
                << "  V" << sender->GetId() << "->V" << receiver->GetId()
                << "  dist=" << dist << "m"
                << (ok ? "  DELIVERED" : "  OUT-OF-RANGE"));
    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S1][t=" << now << "]  V" << sender->GetId()
              << " --HELLO beacon--> V" << receiver->GetId()
              << "  dist=" << dist << "m  "
              << (ok ? "DELIVERED" : "OUT-OF-RANGE") << std::endl;

    ttw_log << "[t=" << now << "]  STEP ①  HELLO  (real DSRC 802.11p packet)\n"
            << "  V" << sender->GetId()   << " pos=(" << ps.x << "," << ps.y << ")\n"
            << "  V" << receiver->GetId() << " pos=(" << pr.x << "," << pr.y << ")\n"
            << "  dist=" << dist << "m  "
            << (ok ? "DELIVERED — neighbor discovered\n\n"
                   : "DROPPED   — out of range\n\n");
    AttackSendDSRCBeacon(sender, receiver);
    AttackSendDSRCBeacon(receiver, sender);

    // Crypto latency: sign on send side, verify on receive side
    double t_now = Simulator::Now().GetSeconds();
    CryptoMeasureBeaconSign  (t_now, sender->GetId(),   "TTW", false);
    CryptoMeasureBeaconVerify(t_now, receiver->GetId(), "TTW", false);
}

// ── STEP 2: Legitimate topology update ───────────────────────────────────────
void TTW_SendTopologyUpdate(Ptr<Node> vehicle, uint32_t seen_id, double obs_time)
{
    double now = Simulator::Now().GetSeconds();

    TopologyPacket pkt;
    pkt.src_id    = vehicle->GetId();
    pkt.seen_id   = seen_id;
    pkt.timestamp = obs_time;
    pkt.is_forged = false;

    std::string key = std::to_string(pkt.src_id) + "_" + std::to_string(pkt.seen_id);

    bool already_newer = (ttw_controller_table.count(key) &&
                          ttw_controller_table[key].timestamp >= pkt.timestamp);
    if (!already_newer)
    {
        ttw_controller_table[key] = pkt;
        NS_LOG_INFO("[TTW-S4] t=" << now << "s  STEP-2 TOPO-UPDATE"
                    << "  V" << pkt.src_id << "->Controller"
                    << "  <V" << pkt.src_id << " sees V" << pkt.seen_id
                    << ", t=" << pkt.timestamp << ">  ACCEPTED");
        std::cout << std::fixed << std::setprecision(3)
                  << "[TTW-S1][t=" << now << "]  V" << pkt.src_id
                  << " --topology update--> Controller"
                  << "  <V" << pkt.src_id << " sees V" << pkt.seen_id
                  << ", t=" << pkt.timestamp << ">  ACCEPTED" << std::endl;

        ttw_log << "[t=" << now << "]  STEP ②  TOPOLOGY UPDATE (legitimate)\n"
                << "  V" << pkt.src_id << " -> Controller\n"
                << "  Packet : <V" << pkt.src_id << " sees V" << pkt.seen_id
                << ", t=" << pkt.timestamp << ">\n"
                << "  Result : ACCEPTED — link V" << pkt.src_id
                << "<->V" << pkt.seen_id << " marked ACTIVE\n\n";
    }
    Ptr<MobilityModel> reporterMobility = vehicle->GetObject<MobilityModel>();
    Vector reporterPosition =
        reporterMobility ? reporterMobility->GetPosition() : Vector(0.0, 0.0, 0.0);
    Vector neighborPosition(0.0, 0.0, 0.0);
    {
        Ptr<Node> neighborNode = GetVehicleByNs3Id(seen_id);
        if (neighborNode) {
            Ptr<MobilityModel> m = neighborNode->GetObject<MobilityModel>();
            if (m) neighborPosition = m->GetPosition();
        }
    }

    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE,
                 pkt.src_id,
                 pkt.src_id,
                 pkt.src_id,
                 pkt.src_id,
                 pkt.seen_id,
                 pkt.timestamp,
                 now,
                 reporterPosition,
                 reporterPosition,
                 neighborPosition,
                 false);
}

// ── STEP 3: Attacker stores own packet ───────────────────────────────────────
void TTW_StorePacket(uint32_t src_id, uint32_t dst_id, double obs_time, double real_break_time)
{
    double now = Simulator::Now().GetSeconds();

    //ttw_stored_packet = {src_id, dst_id, obs_time, false};
    //ttw_packet_stored = true;

	ttw_stored_packets[src_id] = {src_id, dst_id, obs_time, false};

    const double expectedReplayTime = real_break_time + TTW_S1_REPLAY_MARGIN_S;

    NS_LOG_INFO("[TTW-S4] t=" << now << "s  STEP-3 PACKET STORED"
                << "  old_packet=<V" << src_id << " sees V" << dst_id
                << ", t=" << obs_time << ">");
    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S1][t=" << now << "]  V" << src_id
              << " stored old packet <V" << src_id << " sees V" << dst_id
              << ", t=" << obs_time << ">  (will replay at t~=" << expectedReplayTime << ")" << std::endl;

    ttw_log << "[t=" << now << "]  STEP ③  ATTACKER STORES PACKET\n"
            << "  old_packet : <V" << src_id << " sees V" << dst_id
            << ", t=" << obs_time << ">\n"
            << "  Status     : Stored — awaiting replay at t~="
            << expectedReplayTime << "\n\n"
            << "  NOTE: Link V" << src_id << "<->V" << dst_id
            << " physically breaks (real SUMO trajectory) at t="
            << std::fixed << std::setprecision(3) << real_break_time << "s"
            << " (dist > " << TTW_COMM_RANGE << "m)\n"
            << "  Controller receives no link-down notification.\n\n"
            << std::setprecision(3);
}

// ── STEPS 4+5+6: Replay attack ───────────────────────────────────────────────
// ── TTW L3 chain definitions ──────────────────────────────────────────────────
void TTW_L3_Start(uint32_t src, uint32_t dst, double dist)
{
#ifdef HAVE_LIBOQS
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacSign(msg, 64);
    g_ttw_l3_pi = L3_Start("HMAC_Sign_TTW", "Attack_Inject", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_AI_DilSign, src, dst, dist);
#endif
}
void TTW_L3_AI_DilSign(uint32_t src, uint32_t dst, double d)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_ttw_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilSign(msg, 64);
    g_ttw_l3_pi = L3_Start("Dilithium_Sign_TTW", "Attack_Inject", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_AI_HMACVfy, src, dst, d);
#endif
}
void TTW_L3_AI_HMACVfy(uint32_t src, uint32_t dst, double d)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_ttw_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacVerify(msg, 64);
    g_ttw_l3_pi = L3_Start("HMAC_Verify_TTW", "Attack_Inject", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_AI_DilVfy, src, dst, d);
#endif
}
void TTW_L3_AI_DilVfy(uint32_t src, uint32_t dst, double d)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_ttw_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_ttw_l3_pi = L3_Start("Dilithium_Verify_TTW", "Attack_Inject", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_AI_End, src, dst, d);
#endif
}
void TTW_L3_AI_End(uint32_t src, uint32_t dst, double d)
{
    L3_End(&g_ttw_l3_pi);
    // all 4 inject ops complete — now schedule detection at TTW_DETECTION_DELAY_MS
    Simulator::Schedule(MilliSeconds(static_cast<int64_t>(TTW_DETECTION_DELAY_MS)),
        &TTW_RunReplayDetection, src, dst, d);
}
// Detection chain (entry called from TTW_RunReplayDetection when latency==3)
void TTW_L3_Det_DilVfy(uint32_t src, uint32_t dst, double d)
{
#ifdef HAVE_LIBOQS
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_ttw_l3_pi = L3_Start("Dilithium_Verify_TTW_Det", "Detection", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_Det_Hav, src, dst, d);
#endif
}
void TTW_L3_Det_Hav(uint32_t src, uint32_t dst, double d)
{
    L3_End(&g_ttw_l3_pi);
    double us = TimedHaversine();
    g_ttw_l3_pi = L3_Start("Haversine", "Detection", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_Det_Fresh, src, dst, d);
}
void TTW_L3_Det_Fresh(uint32_t src, uint32_t dst, double d)
{
    L3_End(&g_ttw_l3_pi);
    double us = TimedFreshness();
    g_ttw_l3_pi = L3_Start("Freshness_Check", "Detection", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_LKH, src, dst, d);
}
void TTW_L3_LKH(uint32_t src, uint32_t, double)
{
    L3_End(&g_ttw_l3_pi);
    uint32_t n_rep = (N_Vehicles >= 64) ? 64u : 16u;
    char op[48]; snprintf(op, sizeof(op), "LKH_Revoke_n%u", n_rep);
    double us = TimedLkhRevoke(n_rep);
    g_ttw_l3_pi = L3_Start(op, "Mitigation", src, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &TTW_L3_Done, src, 0u, 0.0);
}
void TTW_L3_Done(uint32_t, uint32_t, double)
{
    L3_End(&g_ttw_l3_pi);
}
// ─────────────────────────────────────────────────────────────────────────────

void TTW_ReplayAttack(Ptr<Node> attacker, Ptr<Node> victim,
                      uint32_t  src_id,   uint32_t  dst_id,
                      double    forged_time, double real_break_time)
{
    double now = Simulator::Now().GetSeconds();

    if (ttw_stored_packets.find(src_id) == ttw_stored_packets.end())
    {
        NS_LOG_WARN("[TTW-S4] No stored packet — was TTW_StorePacket called?");
        ttw_log << "[t=" << now << "]  REPLAY FAILED — no stored packet!\n\n";
        return;
    }

    // Verify link is physically broken
    Ptr<MobilityModel> ma = attacker->GetObject<MobilityModel>();
    Ptr<MobilityModel> mv = victim->GetObject<MobilityModel>();
    Vector pa = ma->GetPosition(), pv = mv->GetPosition();
    double dist = std::sqrt(std::pow(pa.x-pv.x,2.0)+std::pow(pa.y-pv.y,2.0));

    // STEP 4: Forge timestamp — change stored t=10 to appear current (t=20)
    const double stored_ts = ttw_stored_packets[src_id].timestamp;
    ttw_s1_forged_timestamp = forged_time;
    TopologyPacket forged = {src_id, dst_id, forged_time, true};

    ttw_log << "[t=" << now << "]  STEP ④  TIMESTAMP FORGE + REPLAY ATTACK\n"
            << "  Stored packet : <V" << src_id << " sees V" << dst_id
            << ", t=" << stored_ts << ">  (original observation at t=" << stored_ts << ")\n"
            << "  Forged packet : <V" << src_id << " sees V" << dst_id
            << ", t=" << forged_time << ">  timestamp changed " << stored_ts << " -> " << forged_time << "\n"
            << "  Forge action  : attacker changes timestamp to appear current, sends to controller at t=" << now
            << " — link has been broken since t=" << real_break_time << "s (real SUMO trajectory)\n"
            << "  Physical link distance : " << dist << " m  "
            << (dist > TTW_COMM_RANGE ? "BROKEN\n\n" : "WARNING still in range!\n\n");


    // STEP 5: Send to controller — record in §3.4.1 T matrix and increment δ
    std::string key = std::to_string(src_id) + "_" + std::to_string(dst_id);
    attack_T_matrix[key] = forged_time;   // T[i][j] = forged timestamp (Eq. 3.1)
    ttw_controller_table[key] = forged;
    topology_divergence_delta++;          // δ = |E_t^C △ E_t^R| grows by 1

        NS_LOG_INFO("[TTW-S1] t=" << now << "s  STEP-5 FORGED REPLAY SENT"
                << "  <V" << src_id << " sees V" << dst_id
                << ", t=" << forged_time << ">  (stored=" << stored_ts << ")  CONTROLLER DECEIVED");
    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S1][t=" << now << "]  V" << src_id
              << " --FORGED replay--> Controller"
              << "  <V" << src_id << " sees V" << dst_id
              << ", t=" << forged_time << ">  (stored=" << stored_ts << ")  CONTROLLER DECEIVED"
              << "  (link physically BROKEN  dist=" << dist << "m)" << std::endl;

        ttw_log << "[t=" << now << "]  STEP ⑤  FORGED PACKET → CONTROLLER\n"
            << "  Controller ACCEPTED forged packet (no timestamp-integrity protection)\n\n";

    // Bug 1 fix (see project memory): guard on injection_time itself, not
    // pem_attack_active — PemRecordObservation resets pem_attack_active on
    // the first alert, so a second attacker firing after that would otherwise
    // overwrite injection_time with a later value and make tdet negative.
    if (pem_attack_injection_time < 0.0) pem_attack_injection_time = now;
    pem_attack_active = true;
    pem_mitigation_active = false;

    // Crypto latency: attacker forges a new signature + sends; controller verifies
#ifdef HAVE_LIBOQS
    if (enable_crypto_latency == 3 && g_crypto_ready) {
        // latency=3: start chained events; detection scheduled by TTW_L3_AI_End
        TTW_L3_Start(src_id, dst_id, dist);
    } else if (enable_crypto_latency && g_crypto_ready) {
        uint8_t msg[64]; RAND_bytes(msg, 64);
        g_crypto_pending_delay_us = 0.0;   // reset accumulator for this function
        CryptoRecord(now, "HMAC_Sign_TTW",        TimedHmacSign  (msg,64), src_id, "Attack_Inject", true);
        CryptoRecord(now, "Dilithium_Sign_TTW",   TimedDilSign   (msg,64), src_id, "Attack_Inject", true);
        CryptoRecord(now, "HMAC_Verify_TTW",      TimedHmacVerify(msg,64), src_id, "Attack_Inject", true);
        CryptoRecord(now, "Dilithium_Verify_TTW", TimedDilVerify (msg,64), src_id, "Attack_Inject", true);
    }
#endif

    // STEP 6: Log faulty routing consequence
    const bool linkPhysicallyBroken = (dist > TTW_COMM_RANGE);
        ttw_log << "[t=" << now << "]  STEP ⑥  FAULTY ROUTING DECISION\n"
            << "  Controller believes V" << src_id << "<->V" << dst_id
            << " was ACTIVE at t=" << forged_time
            << " (forged entry — link broken since t=" << real_break_time << "s)\n"
            << "  Physical reality : link "
            << (linkPhysicallyBroken ? "BROKEN" : "ACTIVE")
            << " (dist=" << dist << "m)\n"
            << (linkPhysicallyBroken
                    ? "  Consequence : packets routed via ghost link will be DROPPED\n"
                    : "  Consequence : controller holds forged entry — link will appear valid past its true expiry\n")
            << "  Topology timeline CORRUPTED — controller has forged temporal reference\n\n";


    NS_LOG_INFO("[TTW-S4] ATTACK COMPLETE — ghost link V"
                << src_id << "<->V" << dst_id << " injected");
    std::cout << "[TTW-S1][t=" << now << "]  *** ATTACK COMPLETE ***  ghost link V"
              << src_id << "<->V" << dst_id << " injected into controller table" << std::endl;

    // Per-pair topology snapshot (shows cumulative state at this moment)
    ttw_log << "  Topology Table (after this pair's replay):\n"
            << "  Src   Dst   Timestamp   Forged?\n"
            << "  ──────────────────────────────────\n";
    for (auto& e : ttw_controller_table)
    {
        TopologyPacket& p = e.second;
        ttw_log << "  V" << p.src_id  << "  ->  V" << p.seen_id
                << "    t=" << p.timestamp
                << "    " << (p.is_forged ? "YES <- FORGED" : "No") << "\n";
    }
    ttw_log << "\n";

    // Print the scenario-completion banner only after the last pair completes
    ++ttw_s1_completed_pairs;
    if (ttw_s1_completed_pairs >= ttw_s1_total_pairs)
    {
        ttw_log << "========================================================\n"
                << "  TTW ATTACK SCENARIO " << attack_scenario << " COMPLETE\n"
                << "========================================================\n";
    }
    ttw_log.flush();

    // latency=3: detection already scheduled by TTW_L3_AI_End (end of inject chain)
    // latency=0/1/2: schedule detection here
    if (enable_crypto_latency != 3) {
        double extra_us = g_crypto_inject_delay ? g_crypto_pending_delay_us : 0.0;
        Time det_delay = MilliSeconds(static_cast<int64_t>(TTW_DETECTION_DELAY_MS))
                         + MicroSeconds(static_cast<int64_t>(extra_us));
        Simulator::Schedule(det_delay, &TTW_RunReplayDetection, src_id, dst_id, dist);
    }
}

void TTW_RunReplayDetection(uint32_t src_id, uint32_t dst_id, double linkDistance)
{
    Vector reporterPosition(0.0, 0.0, 0.0);
    Vector sourcePosition(0.0, 0.0, 0.0);
    Vector destinationPosition(0.0, 0.0, 0.0);
    {
        Ptr<Node> srcNode = GetVehicleByNs3Id(src_id);
        if (srcNode) {
            Ptr<MobilityModel> m = srcNode->GetObject<MobilityModel>();
            if (m) { reporterPosition = m->GetPosition(); sourcePosition = m->GetPosition(); }
        }
    }
    {
        Ptr<Node> dstNode = GetVehicleByNs3Id(dst_id);
        if (dstNode) {
            Ptr<MobilityModel> m = dstNode->GetObject<MobilityModel>();
            if (m) destinationPosition = m->GetPosition();
        }
    }

    // TTW-S1 timestamp forgery — this IS the attack, not an optional upgrade.
    // TTW (Temporal-Echo/Time-Warp) is defined as: replay a stored observation
    // with its sender_timestamp forged to look current (routing.cc's own CLAUDE.md
    // spec, §7/§9: "V0 forges timestamp: <V0 sees V1, t=20>"). An attacker who
    // instead resends the stale original timestamp unchanged isn't performing a
    // time-warp at all — it's a naive stale replay, trivially caught by the
    // Eq. 3.16 age check, and was never the threat this attack models.
    //   age = |now − now| = 0 ≤ T_b + ε → Step 2 (Eq. 3.16) passes.
    //   nonce_key uses ts_slot(now), never previously seen → Step 3 (Eq. 3.17) passes.
    //   physical_sender_id == claimed_sender_id (self-report, no identity spoof
    //   needed) → Step 1 (Eq. 3.15 MAC) passes trivially.
    // Since the attacker validly holds its own signing key, no Stage-0 crypto
    // check can distinguish a forged-fresh timestamp from a real one — this
    // always reaches Stage-1 (LW signature) + Stage-2 (TGN) by construction.
    const double ttw_s1_stored_ts = ttw_stored_packets.count(src_id)
                                  ? ttw_stored_packets[src_id].timestamp : 0.0;
    const double ttw_s1_sender_ts = Simulator::Now().GetSeconds();
    ttw_log << "[t=" << Simulator::Now().GetSeconds() << "]  TTW-S1 attacker V" << src_id
            << "  forged fresh ts=" << ttw_s1_sender_ts
            << " (stored original ts=" << ttw_s1_stored_ts
            << ") → Stage-0 BYPASSED by construction → reaches LW+TGN\n";
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE,
                 src_id, src_id, src_id, src_id, dst_id,
                 ttw_s1_sender_ts,
                 Simulator::Now().GetSeconds(),
                 reporterPosition, sourcePosition, destinationPosition,
                 true);

    // Crypto latency: detection gate (verify + haversine + freshness)
    if (enable_crypto_latency == 3 && g_crypto_ready) {
        // latency=3: start chained detection events (TTW_L3_Det_DilVfy → ... → TTW_L3_Done)
        if (pem_last_alert)
            TTW_L3_Det_DilVfy(src_id, dst_id, linkDistance);
    } else {
        double t_now = Simulator::Now().GetSeconds();
        g_crypto_pending_delay_us = 0.0;
        CryptoMeasureDetection(t_now, src_id, "TTW", false);
        if (pem_last_alert)
            CryptoMeasureLKH(t_now, src_id, N_Vehicles);
    }

    if (pem_last_alert)
    {
        const std::string key = std::to_string(src_id) + "_" + std::to_string(dst_id);
        ttw_controller_table.erase(key);
        attack_T_matrix.erase(key);                          // remove from T matrix
        if (topology_divergence_delta > 0) topology_divergence_delta--;  // δ restored

        ttw_log << "[t=" << Simulator::Now().GetSeconds()
                << "]  DETECTION + MITIGATION\n"
                << "  Alert raised for ghost link V" << src_id << "<->V" << dst_id << "\n"
                << "  Link distance: " << linkDistance << " m\n"
                << "  Detector score: " << pem_last_detection_score << "\n"
                << "  Detection latency: " << PemGetDetectionLatencyMs() << " ms\n"
                << "  delta (divergence) after mitigation: " << topology_divergence_delta << "\n"
                << "  Action: forged topology entry removed from controller table\n"
                << PemApplyMitigation(src_id, Simulator::Now().GetSeconds(), "TTW-S1")
                << "\n";
        ttw_log.flush();
    }
}

// Arms the S1 pipeline intercept: called at t=19.9999 so the very next
// send_LTE_data_agent call from the attacker node sends the forged packet.
static void TTW_ActivateReplay_S1()
{
    if (ttw_s1_attacker_victim_map.empty()) {
        std::cout << "[TTW-S1][t=" << Simulator::Now().GetSeconds()
                  << "]  WARNING: no attackers registered in map" << std::endl;
        return;
    }
    ttw_s1_attack_active    = true;
    ttw_s1_pending_attackers.clear();
    for (auto& kv : ttw_s1_attacker_victim_map)
        ttw_s1_pending_attackers.insert(kv.first);

    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S1][t=" << Simulator::Now().GetSeconds()
              << "]  Pipeline armed: " << ttw_s1_pending_attackers.size() << " attacker(s)\n";
    for (auto& kv : ttw_s1_attacker_victim_map)
        std::cout << "    attacker NS3-ID=" << kv.first
                  << " -> victim NS3-ID=" << kv.second << "\n";
}


// ── Explicit key-exfiltration narrative (malicious-RSU "sophisticated" mode) ──
// Used by TTW-S2 and BSHH-S2 only — both model the SAME real-crypto mechanism:
// a colluding vehicle voluntarily hands its full session key (K_{Vi,nk}, used
// for HMAC/Eq. 3.15) AND its long-term Dilithium signing key (SK_Vi, used for
// any individually-signed report) to the malicious RSU. That handoff — not an
// unexplained probability draw — is what makes the RSU's subsequent forged
// message cryptographically indistinguishable from the victim's own genuine
// self-report: Step 1's MAC recompute uses the SAME real key on both sides
// (claimed and physical), so it passes by construction, not by a simulation
// shortcut. This is a stronger assumption than session-key theft alone (the
// architecture deliberately keeps K_{Vi,nk} and SK_Vi on separate credential
// layers, e.g. SK_Vi is meant to be HSM/secure-element-bound) — both being
// compromised together is the "sophisticated" threat model for these two
// scenarios specifically, distinct from a basic RSU relaying under its own
// identity with no stolen credentials (which correctly fails Step 1's real
// HMAC mismatch and is dropped at Stage-0 — no fix needed there).
// The colluding vehicle itself is assumed complicit and is NOT separately
// flagged/detected; only the RSU is treated as the attacker for mitigation
// (PemApplyMitigation is always called with rsu_id, never victim_id).
// ME-S2's "sophisticated" mode is a DIFFERENT mechanism (GPS/location-binding
// spoofing, Eqs. 3.27-3.29 — the RSU fabricates ITS OWN reported position,
// not a stolen vehicle identity) and does not use this helper.
//
// Decide basic vs sophisticated for the three malicious-RSU scenarios (TTW-S2,
// BSHH-S2, ME-S2). Real runs keep the TRUE random roll (g_attacker_sophistication_prob,
// default 0.5) — with the full 200-vehicle network's attacker count, that gives
// good statistical coverage of both branches. The small test_network (10 pairs,
// often only 1-2 malicious RSUs per scenario) doesn't have enough trials for
// that: with so few coin-flips, a single test run can easily land all-basic or
// all-sophisticated by chance, and — since NS-3 uses a fixed default RNG seed
// unless --RngRun is varied — would deterministically repeat that same
// incomplete coverage on every subsequent run of the same command. In
// test-network mode this alternates deterministically by discriminator (the
// RSU's ns-3 node id) instead, so a single test run reliably exercises BOTH
// branches regardless of how many malicious RSUs get selected.
static bool DecideRsuSophistication(uint32_t discriminator)
{
    // Only override in the ambiguous default case. An explicit extreme
    // (--attacker_sophistication=0 or =1) is an unambiguous request for
    // "always basic" / "always sophisticated" — honor it exactly, in test
    // mode or not, rather than silently overriding it with alternation.
    if (test_network == 1 &&
        g_attacker_sophistication_prob > 0.0 && g_attacker_sophistication_prob < 1.0)
        return (discriminator % 2) == 0;
    return (g_attacker_rng && g_attacker_rng->GetValue() < g_attacker_sophistication_prob);
}

static std::string TtwRsuKeyExfiltrationNarrative(const std::string& attackTag,
                                                   uint32_t victim_id, uint32_t rsu_id,
                                                   double t)
{
    std::stringstream ss;
    ss << std::fixed << std::setprecision(3);
    ss << "[t=" << t << "]  [KEY-EXFIL] " << attackTag << " sophistication: "
       << "V" << victim_id << " (complicit) -> RSU V" << rsu_id
       << " : session_key K_{V" << victim_id << ",nk} + private signing key SK_V"
       << victim_id << " handed over (collusion)\n"
       << "  RSU now holds V" << victim_id << "'s real credentials -> can produce "
       << "messages cryptographically indistinguishable from V" << victim_id
       << "'s own genuine self-report\n";
    return ss.str();
}

// =============================================================================
// TTW-S2: MALICIOUS RSU — attack_scenario == 2
// =============================================================================

static void TTWS2_RunDetection(uint32_t rsu_id, uint32_t v1_id, uint32_t v2_id)
{
    double now2 = Simulator::Now().GetSeconds();
    Vector v1Pos(0.0,0.0,0.0), v2Pos(0.0,0.0,0.0);
    { Ptr<Node> n = GetVehicleByNs3Id(v1_id); if (n) { Ptr<MobilityModel> m = n->GetObject<MobilityModel>(); if (m) v1Pos = m->GetPosition(); } }
    { Ptr<Node> n = GetVehicleByNs3Id(v2_id); if (n) { Ptr<MobilityModel> m = n->GetObject<MobilityModel>(); if (m) v2Pos = m->GetPosition(); } }
    // Timestamp forgery — always happens; this IS the TTW attack (see TTW-S1
    // fix above). A stale-timestamp resend is a naive replay, not a time-warp,
    // and was never the threat this scenario models.
    //
    // Identity spoofing remains a genuine, separate escalation dimension for a
    // malicious RSU (unlike TTW-S1, which has no identity dimension at all).
    // physical_sender_id stays rsu_id ALWAYS — the RSU is who physically
    // transmits this event either way; that is ground truth, not something
    // its own attack code gets to declare. What changes is which key the RSU
    // uses to SIGN it (see PemEmitEvent's macSignerIdOverride / TetaGuardSignEvent):
    // Sophisticated RSU: signs with V1's genuinely exfiltrated session key
    //   (macSignerIdOverride=v1_id) → Step 1 (MAC) recomputed from claimed=V1's
    //   pairwise key matches the carried tag → passes → reaches LW+TGN.
    // Basic RSU: signs with its own key (default override, physicalSenderId=rsu_id)
    //   while claiming to be V1 — the recomputed expected tag (from V1's key)
    //   won't match a tag genuinely produced with the RSU's own key → Step 1
    //   correctly fails → dropped at Stage-0.
    const bool ttw_s2_sophisticated = DecideRsuSophistication(rsu_id);
    const uint32_t ttw_s2_phys = rsu_id; // ground truth — never overwritten
    const uint32_t ttw_s2_mac_signer = ttw_s2_sophisticated ? v1_id : rsu_id;
    double _ts2 = now2;
    // Explicit narrated cause for the sophisticated bypass (see
    // TtwRsuKeyExfiltrationNarrative's comment above) — replaces the old bare
    // coin-flip-decides-pass/fail behavior with a logged collusion event.
    if (ttw_s2_sophisticated) {
        ttws2_log << TtwRsuKeyExfiltrationNarrative("TTW-S2", v1_id, rsu_id, now2);
    }
    ttws2_log << "[t=" << now2 << "]  TTW-S2 RSU attacker  forged fresh ts=" << now2
              << "  identity: "
              << (ttw_s2_sophisticated
                  ? "SOPHISTICATED [key-exfiltration] — RSU signs with V1's genuinely stolen key, claims V1 identity -> Step 1 MAC genuinely matches -> LW+TGN\n"
                  : "BASIC [no keys held] — RSU signs with its own key, claims V1 identity (RSU!=V1) -> Step 1 MAC genuinely fails -> DROPPED at Stage-0\n");
    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S2][t=" << now2 << "]  Sophistication: "
              << (ttw_s2_sophisticated
                  ? "SOPHISTICATED (key-exfiltration) -> LW+TGN"
                  : "BASIC (no keys held) -> Stage-0 drop") << "\n";
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE,
                 ttw_s2_phys, v1_id, ttw_s2_phys,
                 v1_id, v2_id,
                 _ts2,
                 now2, v1Pos, v1Pos, v2Pos, true,
                 ttw_s2_mac_signer);
    if (pem_last_alert) {
        const std::string k = std::to_string(v1_id) + "_" + std::to_string(v2_id);
        ttw_controller_table.erase(k);
        CryptoMeasureLKH(now2, rsu_id, N_Vehicles);
        ttws2_log << "[t=" << now2 << "]  DETECTION + MITIGATION\n"
                  << "  Ghost link V" << v1_id << "<->V" << v2_id << " removed\n"
                  << "  Score: " << pem_last_detection_score << "\n"
                  << "  Latency: " << PemGetDetectionLatencyMs() << " ms\n"
                  << PemApplyMitigation(rsu_id, now2, "TTW-S2")
                  << "\n";
        ttws2_log.flush();
    }
}

// Arms the S2 pipeline intercept for the RSU.
// TTWS2_ActivateReplay — arms the S2 pipeline at TTW_REPLAY_TIME.
// Vehicle pairs come from ttw_s2_all_pairs (registered in main() at setup time),
// not from arguments — the function only needs the RSU node ID.
// The old signature had two unused v1/v2 parameters (commented out with /**/);
// they are removed here to avoid misleading callers.
static void TTWS2_ActivateReplay(uint32_t rsu_ns3_id)
{
    ttw_s2_attack_active  = true;
    ttw_s2_rsu_ns3_id     = rsu_ns3_id;
    ttw_s2_pending_pairs  = ttw_s2_all_pairs; // load all pairs registered in main()
    std::cout << std::fixed << std::setprecision(3)
              << "[TTW-S2][t=" << Simulator::Now().GetSeconds()
              << "]  Pipeline armed: RSU NS3-ID=" << rsu_ns3_id
              << " will inject " << ttw_s2_pending_pairs.size() << " forged pair(s)\n";
    for (auto& p : ttw_s2_pending_pairs)
        std::cout << "    V" << p.first << " sees V" << p.second << "\n";
}


