static void TTWApplyGhostLinkToController(uint32_t src_id, uint32_t dst_id, double forged_time);

static void TTWS3_RunDetection(uint32_t v1_id, uint32_t v2_id)
{
    double now2 = Simulator::Now().GetSeconds();
    Vector v1Pos(0.0,0.0,0.0), v2Pos(0.0,0.0,0.0);
    { Ptr<Node> n = GetVehicleByNs3Id(v1_id); if (n) { Ptr<MobilityModel> m = n->GetObject<MobilityModel>(); if (m) v1Pos = m->GetPosition(); } }
    { Ptr<Node> n = GetVehicleByNs3Id(v2_id); if (n) { Ptr<MobilityModel> m = n->GetObject<MobilityModel>(); if (m) v2Pos = m->GetPosition(); } }
    // Stage-0 already bypasses controller-origin events unconditionally
    // (TetaGuardCryptoFilter's is_malicious_controller check), so forging
    // sender_ts to the current time buys nothing there — it only erases the
    // TTW-S3 cross-reporter signal (Eq. 3.4): the stale STORED timestamp is
    // what the controller is replaying, and comparing it against the
    // legitimate reporter's fresh timestamp (already in ns.event_window) is
    // exactly what fires sig[2]. Mirrors BSHH-S3, which passes stored_time
    // (not a forged-fresh value) into its detection event for the same reason.
    double _ts3 = ttws3_packet_stored ? ttws3_stored_packet.timestamp : 0.0;
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE,
                 9999u, v1_id, 9999u,
                 v1_id, v2_id,
                 _ts3,
                 now2, v1Pos, v1Pos, v2Pos, true);
    if (pem_last_alert) {
        const std::string k = std::to_string(v1_id) + "_" + std::to_string(v2_id);
        ttw_controller_table.erase(k);
        attack_T_matrix.erase(k);
        if (topology_divergence_delta > 0) topology_divergence_delta--;
        CryptoMeasureLKH(now2, v1_id, N_Vehicles);
        // Controller-origin: reassign zone to backup controller (Eqs. 3.42-3.43),
        // gated by Algorithm 4's δ-divergence check (lines 2-7, Eqs. 3.44-3.46).
        uint32_t ctrl_ns3 = (controller_Node.GetN() > 0)
                            ? controller_Node.Get(0)->GetId() : 9999u;
        std::string trust_log, ctrl_div_log;
        if (PemControllerDivergenceGate(now2, "TTW-S3", ctrl_div_log, v1_id, v2_id, now2)) {
            TrustUpdateNode(ctrl_ns3, false, true);
            trust_log = TrustReassignController(ctrl_ns3, now2);
        }
        trust_log = ctrl_div_log + trust_log;
        TrustRunDemotionPipeline(now2);
        ttws3_log << "[t=" << now2 << "]  DETECTION + MITIGATION\n"
                  << "  Internal replay detected and removed\n"
                  << "  Score: " << pem_last_detection_score << "\n"
                  << "  Latency: " << PemGetDetectionLatencyMs() << " ms\n"
                  << PemApplyMitigation(v1_id, now2, "TTW-S3")
                  << trust_log << "\n";
        ttws3_log.flush();
    }
}

