void BSHH_S1_ReplayOldHeartbeatToVictim(uint32_t attacker_id, uint32_t victim_id, double stored_time)
{
    double now = Simulator::Now().GetSeconds();
    const std::string attackerLabel = GetVehicleLogLabel(attacker_id);
    const std::string victimLabel = GetVehicleLogLabel(victim_id);
    
    if (bshh_stored_heartbeats.find(attacker_id) == bshh_stored_heartbeats.end()) {
        std::cout << "[BSHH-S1] Error: Attacker V" << attacker_id << " has no stored heartbeat!" << std::endl;
        return;
    }

    // Bug fix (per thesis Fig. 3.7 narrative): STEP ④ must replay the VICTIM's
    // own captured heartbeat back to the victim (Sender=victim_id) — the packet
    // is physically transmitted by the attacker but claims the victim's own
    // identity, exactly as BSHH_S1_StoreOldHeartbeat's own log text already
    // says ("captured_packet: Heartbeat(Sender=Victim...)"; "stores Victim's
    // old heartbeat for replay to victim"). The previous code sent
    // Sender=attacker_id instead, which made STEP ⑤'s forward an identity
    // mismatch (physical=victim != claimed=attacker) that Step 1 (HMAC) drops
    // trivially — never exercising the freshness/nonce checks (Steps 2/3) this
    // path is meant to test on a correctly-attributed-but-stale replay.
    std::stringstream ss;
    ss << "[t=" << now << "]  STEP ④  ATTACKER REPLAYS VICTIM'S CAPTURED HEARTBEAT TO VICTIM\n"
       << "  Attacker        : " << attackerLabel << "\n"
       << "  Victim          : " << victimLabel << "\n"
       << "  " << attackerLabel << " -> " << victimLabel
       << " : Heartbeat(Sender=" << victimLabel
       << ", beacon_sending_time=" << stored_time << ")\n"
       << "  Victim receives its own captured heartbeat replayed back (stale timestamp beacon_sending_time=" << stored_time << ")\n\n";
    bshh_s1_pair_logs[attacker_id] += ss.str();

    std::cout << std::fixed << std::setprecision(3)
              << "[BSHH-S1][t=" << now << "]  V" << attacker_id
              << " --REPLAY old heartbeat--> V" << victim_id
              << "  Heartbeat(Sender=V" << victim_id << ", t=" << stored_time
              << ")  [MALICIOUS â€” replayed victim's captured heartbeat]" << std::endl;

    Ptr<Node> attackerNode = GetVehicleByNs3Id(attacker_id);
    if (attackerNode) {
        AttackSendHeartbeat(attackerNode, victim_id, stored_time, true);
    }

    // Crypto latency: attacker re-signs replayed heartbeat, controller verifies
#ifdef HAVE_LIBOQS
    if (enable_crypto_latency == 3 && g_crypto_ready) {
        // latency=3: start chained attack-inject events (measurement only)
        // attack-logic side effects (liveness table, PEM emit) run on main() schedule
        BSHH_L3_Start(attacker_id, victim_id, stored_time);
    } else if (enable_crypto_latency && g_crypto_ready) {
        uint8_t msg[64]; RAND_bytes(msg, 64);
        g_crypto_pending_delay_us = 0.0;
        CryptoRecord(now, "HMAC_Sign_BSHH",        TimedHmacSign  (msg,64), attacker_id, "Attack_Inject", true);
        CryptoRecord(now, "Dilithium_Sign_BSHH",   TimedDilSign   (msg,64), attacker_id, "Attack_Inject", true);
        CryptoRecord(now, "HMAC_Verify_BSHH",      TimedHmacVerify(msg,64), victim_id,   "Attack_Inject", true);
        CryptoRecord(now, "Dilithium_Verify_BSHH", TimedDilVerify (msg,64), victim_id,   "Attack_Inject", true);
        CryptoRecord(now, "Freshness_Check",        TimedFreshness(),        victim_id,   "Attack_Inject", true);
        // latency=2: forward-to-controller step fires after crypto delay
        if (g_crypto_inject_delay) {
            double delay_us = g_crypto_pending_delay_us;
            Simulator::Schedule(MicroSeconds(static_cast<int64_t>(delay_us)),
                &BSHH_S1_VictimForwardsOldHeartbeatToController, attacker_id, victim_id, stored_time);
            return;   // forwarding is scheduled — don't fall through
        }
    }
#endif
}

void BSHH_S1_VictimForwardsOldHeartbeatToController(uint32_t attacker_id, uint32_t victim_id, double stored_time)
{
    double now = Simulator::Now().GetSeconds();
    const std::string attackerLabel = GetVehicleLogLabel(attacker_id);
    const std::string victimLabel = GetVehicleLogLabel(victim_id);
    
    // Bug fix (matches STEP ④'s correction): the packet the victim received
    // and is forwarding claims Sender=victim_id (its own identity), not
    // Sender=attacker_id — so both the claimed_sender field and the liveness
    // table key must be victim_id. This produces physical=victim ==
    // claimed=victim (a correctly-attributed but stale message), which is
    // what lets Stage-0's freshness/nonce checks (Eqs. 3.16-3.17) — not an
    // identity mismatch — be the thing that catches or misses this path.
    HeartbeatPacket forwarded = {victim_id, victim_id, stored_time, true};
    bshh_controller_liveness_table[victim_id] = forwarded;
    // Bug 1 fix (see project memory): this function runs once per
    // attacker/victim pair. With multiple attacker pairs scheduled at
    // different times, an unconditional overwrite here could set
    // injection_time later than an earlier pair's already-recorded
    // first_alert_time, producing a negative detection latency.
    if (pem_attack_injection_time < 0.0) pem_attack_injection_time = now;
    pem_attack_active = true;
    pem_mitigation_active = false;

    std::stringstream ss;
    ss << "[t=" << now << "]  STEP ⑤  VICTIM FORWARDS ITS OWN REPLAYED-STALE HEARTBEAT TO CONTROLLER\n"
       << "  Originally captured from : " << victimLabel << " (attacker=" << attackerLabel << " replayed it back)\n"
       << "  Forwarder/physical       : " << victimLabel << "\n"
       << "  " << victimLabel << " -> Controller : Heartbeat(Sender="
       << victimLabel << ", beacon_sending_time=" << stored_time << ")\n"
       << "  Controller refreshes " << victimLabel
       << " liveness using stale timestamp beacon_sending_time=" << stored_time << "\n\n";
    bshh_s1_pair_logs[attacker_id] += ss.str();

    std::cout << std::fixed << std::setprecision(3)
              << "[BSHH-S1][t=" << now << "]  V" << victim_id
              << " --forwards stale heartbeat--> Controller"
              << "  Heartbeat(Sender=V" << victim_id << ", t=" << stored_time
              << ")  Controller liveness POISONED" << std::endl;
    PemEmitHeartbeatEvent(victim_id, victim_id, stored_time, true);
}

void BSHH_S1_AttackerHijacksOldHeartbeatToController(uint32_t attacker_id, uint32_t victim_id, double stored_time)
{
    double now = Simulator::Now().GetSeconds();
    const std::string attackerLabel = GetVehicleLogLabel(attacker_id);
    const std::string victimLabel = GetVehicleLogLabel(victim_id);
    
    HeartbeatPacket forged = {victim_id, attacker_id, stored_time, true};
    bshh_controller_liveness_table[victim_id] = forged;
    
    std::stringstream ss;
    ss << "[t=" << now << "]  STEP ⑥  ATTACKER HIJACKS SAME OLD HEARTBEAT TO CONTROLLER\n"
       << "  Attacker/physical_sender : " << attackerLabel << "\n"
       << "  Victim/claimed_sender    : " << victimLabel << "\n"
       << "  Packet source            : stored STEP ③ heartbeat captured from " << victimLabel << "\n"
       << "  " << attackerLabel << " -> Controller : Heartbeat(claimed="
       << victimLabel << ", beacon_sending_time=" << stored_time << ")\n"
       << "  physical_sender=" << attackerLabel
       << "  claimed_sender=" << victimLabel << "\n"
       << "  Stale timestamp " << stored_time << " < current t=" << now << " -> replay evidence\n"
       << "  Different physical sender -> impersonation evidence\n\n";
    bshh_s1_pair_logs[attacker_id] += ss.str();
    
    // Sophistication roll — BSHH-S1.
    // physical_sender_id stays attacker_id ALWAYS — the attacker vehicle is
    // who physically transmits this heartbeat either way; that is ground
    // truth. Timestamp forgery (bshh_s1_ts) is genuine payload content the
    // attacker legitimately controls either way. What sophistication changes
    // is which key signs the event (see PemEmitHeartbeatEvent's
    // macSignerIdOverride):
    // Sophisticated attacker: signs with victim's genuinely exfiltrated
    //   session key + fresh timestamp → Step 1 MAC genuinely matches (via
    //   claimed=victim's pairwise key) → Steps 1,2,3 pass → LW+TGN.
    // Basic attacker: signs with its own key while claiming victim's identity
    //   → Step 1 (Eq. 3.15 MAC) genuinely fails → drops at Stage-0.
    const bool bshh_s1_sophisticated = (g_attacker_rng && g_attacker_rng->GetValue() < g_attacker_sophistication_prob);
    const uint32_t bshh_s1_phys = attacker_id; // ground truth — never overwritten
    const uint32_t bshh_s1_mac_signer = bshh_s1_sophisticated ? victim_id : attacker_id;
    const double bshh_s1_ts     = bshh_s1_sophisticated ? now : stored_time;
    bshh_s1_pair_logs[attacker_id] += (bshh_s1_sophisticated
        ? "  Sophistication: SOPHISTICATED — signs with victim's genuinely stolen key + fresh ts → Stage-0 genuinely passes → LW+TGN\n"
        : "  Sophistication: BASIC — signs with own key, claims victim identity → DROPPED at Stage-0 (Eq. 3.15 MAC)\n");
    std::cout << std::fixed << std::setprecision(3)
              << "[BSHH-S1][t=" << now << "]  V" << attacker_id
              << " --HIJACK old heartbeat--> Controller"
              << "  Heartbeat(physical=V" << bshh_s1_phys << ", claimed=V" << victim_id
              << ", t=" << bshh_s1_ts << ")  IMPERSONATION"
              << (bshh_s1_sophisticated ? " [SOPHISTICATED→LW+TGN]" : " [BASIC→Stage-0 drop]")
              << "  *** ATTACK COMPLETE ***" << std::endl;
    PemEmitHeartbeatEvent(bshh_s1_phys, victim_id, bshh_s1_ts, true, bshh_s1_mac_signer);

    // Crypto latency: detection verify + freshness + LKH mitigation
    if (enable_crypto_latency == 3 && g_crypto_ready) {
        BSHH_L3_Det_DilVfy(attacker_id, victim_id, stored_time);
    } else {
        CryptoMeasureDetection(now, attacker_id, "BSHH", false);
        CryptoMeasureLKH(now, victim_id, N_Vehicles);
    }

    if (pem_last_alert) {
        bshh_controller_liveness_table.erase(victim_id);
        std::string mit = PemApplyMitigation(attacker_id, now, "BSHH-S1");
        std::stringstream ms;
        ms << std::fixed << std::setprecision(3)
           << "[t=" << now << "]  DETECTION + MITIGATION\n"
           << "  Stale heartbeat impersonation: V" << attacker_id
           << " impersonated V" << victim_id << "\n"
           << "  Score: " << pem_last_detection_score << "\n"
           << "  Latency: " << PemGetDetectionLatencyMs() << " ms\n"
           << mit << "\n";
        bshh_s1_pair_logs[attacker_id] += ms.str();
    }
}

