// =============================================================================
// ME-S1: MALICIOUS VEHICLES, NO RSU — attack_scenario == 9
// =============================================================================

void ME_S1_InitLog(uint32_t total_vehicles, uint32_t n_echo_attackers,
                   uint32_t n_benign, uint32_t n_groups,
                   const std::vector<uint32_t>& echo_cidx,
                   const std::vector<uint32_t>& real_cidx)
{
    me_log.open(BuildLogPath("me_s1_attack_log.txt"), std::ios::out | std::ios::trunc);
    me_log << std::fixed << std::setprecision(3);
    me_log << "========================================================\n"
           << "  ME Attack S1 — Malicious Vehicles, No RSU             \n"
           << "========================================================\n\n"
           << "  Simulation Parameters:\n"
           << "    Total vehicles        : " << total_vehicles << "\n"
           << "    Attack percentage     : " << attack_percentage << "%\n"
           << "    Echo attacker vehicles: " << n_echo_attackers << "\n"
           << "    Benign (real link) veh: " << n_benign << "\n"
           << "    Active attack groups  : " << n_groups << "\n\n"
           << "  Vehicle Roles (NS-3 node IDs):\n";
    for (uint32_t k = 0; k < total_vehicles; k++) {
        uint32_t ns3id = Vehicle_Nodes.Get(k)->GetId();
        bool is_echo = me_malicious_nodes[k];
        bool in_group = false;
        for (uint32_t g = 0; g < n_groups; g++) {
            if (2*g   < echo_cidx.size() && echo_cidx[2*g]   == k) { in_group = true; break; }
            if (2*g+1 < echo_cidx.size() && echo_cidx[2*g+1] == k) { in_group = true; break; }
            if (2*g   < real_cidx.size() && real_cidx[2*g]   == k) { in_group = true; break; }
            if (2*g+1 < real_cidx.size() && real_cidx[2*g+1] == k) { in_group = true; break; }
        }
        me_log << "    V" << ns3id
               << (is_echo  ? "  [ECHO ATTACKER]" : "  [benign — real link]")
               << (in_group ? " <-- in active group" : "")
               << "\n";
    }
    me_log << "\n"
           << "  Attack Steps (per group):\n"
           << "  t=10  ①  Real pair HELLO exchange (V2V link); echo pair also exchange own HELLO\n"
           << "  t=10  ②  All four vehicles send legitimate topology to controller\n"
           << "            (no cross-links between real pair and echo pair)\n"
           << "  t=10  ③  Echo vehicles overhear real-pair HELLO (echo preparation)\n"
           << "  t=10+ ④  Echo vehicles send forged echo reports to controller\n"
           << "  t=10+ ⑤  Controller infers phantom paths via echo vehicles\n"
           << "  t=10+ ⑥  Controller installs faulty routes on phantom paths\n\n"
           << "========================================================\n\n";
    NS_LOG_INFO("[ME-S1] Log opened: me_s1_attack_log.txt");
}


void ME_S1_LegitimateDiscovery(uint32_t v1_id, uint32_t v2_id,
                                uint32_t v3_id, uint32_t v4_id, double t)
{
    double now = Simulator::Now().GetSeconds();
    uint32_t v1_ns3 = (v1_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v1_id)->GetId() : v1_id;
    uint32_t v2_ns3 = (v2_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v2_id)->GetId() : v2_id;
    uint32_t v3_ns3 = (v3_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v3_id)->GetId() : v3_id;
    uint32_t v4_ns3 = (v4_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v4_id)->GetId() : v4_id;

    // Positions come from wherever SUMO/the mobility model actually placed
    // these vehicles at attack time — no code-controlled positioning (matches
    // ME_Single3's organic model). Both "real" pairs are therefore only
    // genuinely real if actually within DSRC range; measure, don't assume.
    Vector pos1(0,0,0), pos2(0,0,0), pos3(0,0,0), pos4(0,0,0);
    if (v1_id < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(v1_id)->GetObject<MobilityModel>(); if (m) pos1 = m->GetPosition(); }
    if (v2_id < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(v2_id)->GetObject<MobilityModel>(); if (m) pos2 = m->GetPosition(); }
    if (v3_id < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(v3_id)->GetObject<MobilityModel>(); if (m) pos3 = m->GetPosition(); }
    if (v4_id < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(v4_id)->GetObject<MobilityModel>(); if (m) pos4 = m->GetPosition(); }
    // Inlined distance (MEDist2D is declared later in the file, after this
    // function — same reason ME_S1_EchoAttack below inlines it too).
    const double d12 = std::sqrt((pos1.x-pos2.x)*(pos1.x-pos2.x) + (pos1.y-pos2.y)*(pos1.y-pos2.y));
    const double d34 = std::sqrt((pos3.x-pos4.x)*(pos3.x-pos4.x) + (pos3.y-pos4.y)*(pos3.y-pos4.y));
    const bool link12 = d12 <= TTW_COMM_RANGE;
    const bool link34 = d34 <= TTW_COMM_RANGE;

    // Update controller table only with links that are actually real.
    if (link12) {
        ttw_controller_table[std::to_string(v1_id)+"_"+std::to_string(v2_id)] = {v1_id, v2_id, t, false};
        ttw_controller_table[std::to_string(v2_id)+"_"+std::to_string(v1_id)] = {v2_id, v1_id, t, false};
    }
    if (link34) {
        ttw_controller_table[std::to_string(v3_id)+"_"+std::to_string(v4_id)] = {v3_id, v4_id, t, false};
        ttw_controller_table[std::to_string(v4_id)+"_"+std::to_string(v3_id)] = {v4_id, v3_id, t, false};
    }

    // STEP ①: Normal V2V Topology Discovery — real pair + echo pair own link
    me_log << "[t=" << now << "]  STEP ①  NORMAL V2V TOPOLOGY DISCOVERY\n"
           << "  Measured distances: d(V" << v1_ns3 << ",V" << v2_ns3 << ")=" << d12
           << "m  d(V" << v3_ns3 << ",V" << v4_ns3 << ")=" << d34 << "m  (range=" << TTW_COMM_RANGE << "m)\n"
           << (link12 ? ("  V" + std::to_string(v1_ns3) + " -> V" + std::to_string(v2_ns3) +
                         " : HELLO(Sender=V" + std::to_string(v1_ns3) + ", t=" + std::to_string(t) + ")  (real link pair)\n"
                         "  V" + std::to_string(v2_ns3) + " -> V" + std::to_string(v1_ns3) +
                         " : HELLO(Sender=V" + std::to_string(v2_ns3) + ", t=" + std::to_string(t) + ")  (real link pair)\n")
                       : ("  V" + std::to_string(v1_ns3) + "<->V" + std::to_string(v2_ns3) +
                          " OUT OF RANGE — no real HELLO exchange this run\n"))
           << (link34 ? ("  V" + std::to_string(v3_ns3) + " -> V" + std::to_string(v4_ns3) +
                         " : HELLO(Sender=V" + std::to_string(v3_ns3) + ", t=" + std::to_string(t) + ")  (echo pair — own legitimate link)\n"
                         "  V" + std::to_string(v4_ns3) + " -> V" + std::to_string(v3_ns3) +
                         " : HELLO(Sender=V" + std::to_string(v4_ns3) + ", t=" + std::to_string(t) + ")  (echo pair — own legitimate link)\n")
                       : ("  V" + std::to_string(v3_ns3) + "<->V" + std::to_string(v4_ns3) +
                          " OUT OF RANGE — echo pair has no genuine link of its own this run\n"))
           << "  [V" << v3_ns3 << " and V" << v4_ns3
           << " are in overhearing range of V" << v1_ns3 << "↔V" << v2_ns3
           << " but have NO direct link to V" << v1_ns3 << " or V" << v2_ns3 << "]\n\n";

    // STEP ②: All four vehicles report legitimate topology to controller
    me_log << "[t=" << now << "]  STEP ②  LEGITIMATE LINK ESTABLISHMENT\n"
           << (link12 ? ("  V" + std::to_string(v1_ns3) + " -> Controller : <V" + std::to_string(v1_ns3) +
                         " sees V" + std::to_string(v2_ns3) + ", t=" + std::to_string(t) + ">  (real reporter)\n"
                         "  V" + std::to_string(v2_ns3) + " -> Controller : <V" + std::to_string(v2_ns3) +
                         " sees V" + std::to_string(v1_ns3) + ", t=" + std::to_string(t) + ">  (real reporter)\n") : "")
           << (link34 ? ("  V" + std::to_string(v3_ns3) + " -> Controller : <V" + std::to_string(v3_ns3) +
                         " sees V" + std::to_string(v4_ns3) + ", t=" + std::to_string(t) + ">  (echo pair's own real link)\n"
                         "  V" + std::to_string(v4_ns3) + " -> Controller : <V" + std::to_string(v4_ns3) +
                         " sees V" + std::to_string(v3_ns3) + ", t=" + std::to_string(t) + ">  (echo pair's own real link)\n") : "")
           << "  No direct links: V" << v1_ns3 << "-V" << v3_ns3
           << ", V" << v1_ns3 << "-V" << v4_ns3
           << ", V" << v2_ns3 << "-V" << v3_ns3
           << ", V" << v2_ns3 << "-V" << v4_ns3 << " do NOT exist\n\n";

    // STEP ③: Interception by echo attackers
    me_log << "[t=" << now << "]  STEP ③  HELLO MESSAGE INTERCEPTION (Echo Preparation)\n"
           << "  V" << v3_ns3 << " overhears HELLO: <V" << v1_ns3
           << " sees V" << v2_ns3 << ", t=" << t << ">  [stored for echo]\n"
           << "  V" << v4_ns3 << " overhears HELLO: <V" << v1_ns3
           << " sees V" << v2_ns3 << ", t=" << t << ">  [stored for echo]\n"
           << "  Echo vehicles will replay this observation to the controller\n\n";

    std::cout << std::fixed << std::setprecision(3)
              << "[ME-S1][t=" << now << "]  STEP①  V" << v1_ns3
              << " <-> V" << v2_ns3 << (link12 ? " HELLO exchange (real link)" : " OUT OF RANGE (no real link)") << std::endl;
    std::cout << "[ME-S1][t=" << now << "]  STEP②  V" << v1_ns3 << ", V" << v2_ns3
              << (link12 ? " report real link to controller" : " have no real link to report") << std::endl;
    std::cout << "[ME-S1][t=" << now << "]  STEP③  V" << v3_ns3 << ", V" << v4_ns3
              << " overhear HELLO — stored for echo" << std::endl;

    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v1_id, v1_id, v1_id, v1_id, v2_id, t, now, pos1, pos1, pos2, false);
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v2_id, v2_id, v2_id, v2_id, v1_id, t, now, pos2, pos2, pos1, false);
    if (link34) {
        PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v3_id, v3_id, v3_id, v3_id, v4_id, t, now, pos3, pos3, pos4, false);
        PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v4_id, v4_id, v4_id, v4_id, v3_id, t, now, pos4, pos4, pos3, false);
    }
    PemEmitVehicleBeacon(v1_id, v2_id);
    if (link34) PemEmitVehicleBeacon(v3_id, v4_id);
    if (v1_id < Vehicle_Nodes.GetN() && v2_id < Vehicle_Nodes.GetN()) {
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v1_id), Vehicle_Nodes.Get(v2_id));
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v2_id), Vehicle_Nodes.Get(v1_id));
    }
    if (v3_id < Vehicle_Nodes.GetN() && v4_id < Vehicle_Nodes.GetN()) {
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v3_id), Vehicle_Nodes.Get(v4_id));
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v4_id), Vehicle_Nodes.Get(v3_id));
    }

    // Crypto latency: legitimate sign+verify for real links V1/V2
    CryptoMeasureBeaconSign  (now, v1_id, "ME", false);
    CryptoMeasureBeaconVerify(now, v2_id, "ME", false);
}

// ── ME L3 chain definitions ───────────────────────────────────────────────────
// V3 chain → V4 chain → Detection chain (all sequential for full timing picture)
void ME_L3_Start(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    // g_me_l3_ctx already set by ME_S1_EchoAttack before calling ME_L3_Start
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacSign(msg, 64);
    g_me_l3_pi = L3_Start("HMAC_Sign_ME", "Attack_Inject", v3, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V3_DilSgn, v3, v4, 0.0);
#endif
}
void ME_L3_V3_DilSgn(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilSign(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Sign_ME", "Attack_Inject", v3, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V3_HMACVfy, v3, v4, 0.0);
#endif
}
void ME_L3_V3_HMACVfy(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacVerify(msg, 64);
    g_me_l3_pi = L3_Start("HMAC_Verify_ME", "Attack_Inject", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V3_DilVfy, v3, v4, 0.0);
#endif
}
void ME_L3_V3_DilVfy(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Verify_ME", "Attack_Inject", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V3_Hav, v3, v4, 0.0);
#endif
}
void ME_L3_V3_Hav(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    double us = TimedHaversine();
    g_me_l3_pi = L3_Start("Haversine", "Attack_Inject", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V3_End, v3, v4, 0.0);
}
void ME_L3_V3_End(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    // chain to V4
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacSign(msg, 64);
    g_me_l3_pi = L3_Start("HMAC_Sign_ME", "Attack_Inject", v4, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V4_DilSgn, v3, v4, 0.0);
}
void ME_L3_V4_DilSgn(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilSign(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Sign_ME", "Attack_Inject", v4, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V4_HMACVfy, v3, v4, 0.0);
#endif
}
void ME_L3_V4_HMACVfy(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedHmacVerify(msg, 64);
    g_me_l3_pi = L3_Start("HMAC_Verify_ME", "Attack_Inject", g_me_l3_ctx.ldst, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V4_DilVfy, v3, v4, 0.0);
#endif
}
void ME_L3_V4_DilVfy(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Verify_ME", "Attack_Inject", g_me_l3_ctx.ldst, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V4_Hav, v3, v4, 0.0);
#endif
}
void ME_L3_V4_Hav(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    double us = TimedHaversine();
    g_me_l3_pi = L3_Start("Haversine", "Attack_Inject", g_me_l3_ctx.ldst, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_V4_End, v3, v4, 0.0);
}
void ME_L3_V4_End(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    // chain to detection (immediate — ME has no detection delay)
    ME_L3_Det_DilVfy(v3, v4, 0.0);
}
// Detection chain
void ME_L3_Det_DilVfy(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Verify_ME_Det", "Detection", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_Det_DilVfy2, v3, v4, 0.0);
#endif
}
void ME_L3_Det_DilVfy2(uint32_t v3, uint32_t v4, double)
{
#ifdef HAVE_LIBOQS
    L3_End(&g_me_l3_pi);
    uint8_t msg[64]; RAND_bytes(msg, 64);
    double us = TimedDilVerify(msg, 64);
    g_me_l3_pi = L3_Start("Dilithium_Verify_ME_Det2", "Detection", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_Det_LocBind, v3, v4, 0.0);
#endif
}
void ME_L3_Det_LocBind(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    double us = TimedLocationBind();
    g_me_l3_pi = L3_Start("LocBind_Verify", "Detection", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_Det_Hav, v3, v4, 0.0);
}
void ME_L3_Det_Hav(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    double us = TimedHaversine();
    g_me_l3_pi = L3_Start("Haversine", "Detection", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_Det_Fresh, v3, v4, 0.0);
}
void ME_L3_Det_Fresh(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    double us = TimedFreshness();
    g_me_l3_pi = L3_Start("Freshness_Check", "Detection", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_LKH, v3, v4, 0.0);
}
void ME_L3_LKH(uint32_t v3, uint32_t v4, double)
{
    L3_End(&g_me_l3_pi);
    uint32_t n_rep = (N_Vehicles >= 64) ? 64u : 16u;
    char op[48]; snprintf(op, sizeof(op), "LKH_Revoke_n%u", n_rep);
    double us = TimedLkhRevoke(n_rep);
    g_me_l3_pi = L3_Start(op, "Mitigation", g_me_l3_ctx.lsrc, true);
    Simulator::Schedule(MicroSeconds((int64_t)us), &ME_L3_Done, v3, v4, 0.0);
}
void ME_L3_Done(uint32_t, uint32_t, double)
{
    L3_End(&g_me_l3_pi);
}
// ─────────────────────────────────────────────────────────────────────────────


void ME_S1_EchoAttack(uint32_t echo_v3, uint32_t echo_v4,
                      uint32_t link_src, uint32_t link_dst, double t,
                      uint32_t reporter_mask)
{
    double now = Simulator::Now().GetSeconds();
    if (pem_attack_injection_time < 0.0) pem_attack_injection_time = now;
    pem_attack_active = true;
    pem_mitigation_active = false;
    const bool emit_v3 = (reporter_mask & 0x1u) != 0u;
    const bool emit_v4 = (reporter_mask & 0x2u) != 0u;
    uint32_t ev3_ns3  = (echo_v3  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(echo_v3)->GetId()  : echo_v3;
    uint32_t ev4_ns3  = (echo_v4  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(echo_v4)->GetId()  : echo_v4;
    uint32_t src_ns3  = (link_src < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(link_src)->GetId() : link_src;
    uint32_t dst_ns3  = (link_dst < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(link_dst)->GetId() : link_dst;
    if (emit_v3)
    {
        MEEchoReport r3 = {link_src, link_dst, echo_v3, t, true};
        me_echo_reports.push_back(r3);
        std::string k3 = std::to_string(echo_v3)+"_echo_"+std::to_string(link_src)+"_"+std::to_string(link_dst);
        ttw_controller_table[k3] = {echo_v3, link_dst, t, true};
        attack_E_matrix.insert(k3);       // E[i][j]=1: link echoed by false reporter V3
        topology_divergence_delta++;      // δ += 1 (Eq. 3.1)
    }
    if (emit_v4)
    {
        MEEchoReport r4 = {link_src, link_dst, echo_v4, t, true};
        me_echo_reports.push_back(r4);
        std::string k4 = std::to_string(echo_v4)+"_echo_"+std::to_string(link_src)+"_"+std::to_string(link_dst);
        ttw_controller_table[k4] = {echo_v4, link_dst, t, true};
        attack_E_matrix.insert(k4);       // E[i][j]=1: link echoed by false reporter V4
        topology_divergence_delta++;      // δ += 1 (Eq. 3.1)
    }

    // Resolve current positions before logging so Path 4 check uses actual distance.
    Vector v3Pos(0.0,0.0,0.0), v4Pos(0.0,0.0,0.0), vSrcPos(0.0,0.0,0.0), vDstPos(0.0,0.0,0.0);
    if (echo_v3  < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(echo_v3)->GetObject<MobilityModel>();  if (m) v3Pos   = m->GetPosition(); }
    if (echo_v4  < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(echo_v4)->GetObject<MobilityModel>();  if (m) v4Pos   = m->GetPosition(); }
    if (link_src < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(link_src)->GetObject<MobilityModel>(); if (m) vSrcPos = m->GetPosition(); }
    if (link_dst < Vehicle_Nodes.GetN()) { Ptr<MobilityModel> m = Vehicle_Nodes.Get(link_dst)->GetObject<MobilityModel>(); if (m) vDstPos = m->GetPosition(); }

    // Honest check: is the echoed link itself actually real (link_src<->link_dst
    // in DSRC range)? The echo reports below are fabricated by the attacker
    // regardless — that IS the attack — but the log/Path-1 label must reflect
    // measured reality, not assume it, now that positions are organic (SUMO)
    // rather than code-forced.
    const double srcDstDist = std::sqrt((vSrcPos.x-vDstPos.x)*(vSrcPos.x-vDstPos.x) +
                                         (vSrcPos.y-vDstPos.y)*(vSrcPos.y-vDstPos.y));
    const bool srcDstLinked = srcDstDist <= TTW_COMM_RANGE;

    // Path 4 (V1→V3→V4→V2) exists only when V3 and V4 have a real wireless link
    // between them (distance ≤ DSRC range).  Paper: "V3 and V4 are within overhearing
    // range; no direct links V1–V3, V1–V4, V2–V3, V2–V4 — but V3↔V4 may exist."
    // One attacker:  only Path 2.
    // Two attackers, V3↔V4 out of range: Paths 2+3 (no Path 4).
    // Two attackers, V3↔V4 in range:     Paths 2+3+4.
    bool v3v4_linked = false;
    double v3v4_dist = 0.0;
    if (emit_v3 && emit_v4) {
        double dx = v3Pos.x - v4Pos.x;
        double dy = v3Pos.y - v4Pos.y;
        v3v4_dist = std::sqrt(dx*dx + dy*dy);
        v3v4_linked = (v3v4_dist <= TTW_COMM_RANGE);
        if (v3v4_linked) {
            // Register V3↔V4 as a real observed link so controller can infer Path 4.
            std::string k34 = std::to_string(echo_v3)+"_real_"+std::to_string(echo_v4);
            ttw_controller_table[k34] = {echo_v3, echo_v4, t, false};
        }
    }

    // STEP ④: Echo reports sent to controller
    me_log << "[t=" << now << "]  STEP ④  ECHOED TOPOLOGY OBSERVATION REPORTS\n"
           << (emit_v3
                   ? ("  V" + std::to_string(ev3_ns3) + " -> Controller : <V" +
                      std::to_string(src_ns3) + " sees V" + std::to_string(dst_ns3) +
                      ", t=" + std::to_string(t) + ">  (ECHO -- false reporter)\n")
                   : "")
           << (emit_v4
                   ? ("  V" + std::to_string(ev4_ns3) + " -> Controller : <V" +
                      std::to_string(src_ns3) + " sees V" + std::to_string(dst_ns3) +
                      ", t=" + std::to_string(t) + ">  (ECHO -- false reporter)\n")
                   : "")
           << "  Active false reporters: "
           << (emit_v3 ? ("V" + std::to_string(ev3_ns3)) : "")
           << ((emit_v3 && emit_v4) ? ", " : "")
           << (emit_v4 ? ("V" + std::to_string(ev4_ns3)) : "")
           << "\n";
    if (emit_v3 && emit_v4) {
        me_log << "  V3↔V4 link: dist=" << std::fixed << std::setprecision(1) << v3v4_dist
               << "m  " << (v3v4_linked ? "IN RANGE — Path 4 inferred" : "OUT OF RANGE — no Path 4")
               << "\n";
    }
    me_log << "  V" << src_ns3 << "↔V" << dst_ns3 << " echoed link: dist=" << std::fixed << std::setprecision(1)
           << srcDstDist << "m  " << (srcDstLinked ? "IN RANGE — genuinely real" : "OUT OF RANGE — Path 1 claim itself is false")
           << "\n";
    me_log << "  Note: echo vehicles duplicate an existing link — they do NOT fabricate new physical links\n\n";

    // STEP ⑤: Multipath inference at controller
    me_log << "[t=" << now << "]  STEP ⑤  MULTIPATH INFERENCE AT CONTROLLER (Attack Effect)\n"
           << "  Controller aggregates observations for link V" << src_ns3 << "↔V" << dst_ns3 << ":\n"
           << "    (1) V" << src_ns3 << " reports V" << src_ns3 << "↔V" << dst_ns3 << "  [real]\n"
           << "    (2) V" << dst_ns3 << " reports V" << dst_ns3 << "↔V" << src_ns3 << "  [real]\n"
           << (emit_v3
                   ? ("    (3) V" + std::to_string(ev3_ns3) + " reports V" +
                      std::to_string(src_ns3) + "↔V" + std::to_string(dst_ns3) + "  [ECHO]\n")
                   : "")
           << (emit_v4
                   ? ("    (4) V" + std::to_string(ev4_ns3) + " reports V" +
                      std::to_string(src_ns3) + "↔V" + std::to_string(dst_ns3) + "  [ECHO]\n")
                   : "")
           << "  Controller incorrectly infers:\n"
           << "    Path 1: V" << src_ns3 << " -> V" << dst_ns3
           << (srcDstLinked ? "  (REAL)\n" : "  (FALSE — out of range, echoed anyway)\n")
           << (emit_v3
                   ? ("    Path 2: V" + std::to_string(src_ns3) + " -> V" +
                      std::to_string(ev3_ns3) + " -> V" + std::to_string(dst_ns3) +
                      "  (PHANTOM)\n")
                   : "")
           << (emit_v4
                   ? ("    Path 3: V" + std::to_string(src_ns3) + " -> V" +
                      std::to_string(ev4_ns3) + " -> V" + std::to_string(dst_ns3) +
                      "  (PHANTOM)\n")
                   : "")
           << (v3v4_linked
                   ? ("    Path 4: V" + std::to_string(src_ns3) + " -> V" +
                      std::to_string(ev3_ns3) + " -> V" + std::to_string(ev4_ns3) +
                      " -> V" + std::to_string(dst_ns3) + "  (PHANTOM — V3↔V4 in range)\n\n")
                   : "\n");

    // STEP ⑥: Faulty routing decisions
    me_log << "[t=" << now << "]  STEP ⑥  FAULTY ROUTING DECISIONS\n"
           << "  Controller installs routing rules relying on phantom paths\n"
           << "  Packets to V" << dst_ns3 << " may be forwarded via V"
           << (emit_v3 ? std::to_string(ev3_ns3) : std::to_string(ev4_ns3))
           << ((emit_v3 && emit_v4) ? (" or V" + std::to_string(ev4_ns3)) : "")
           << (v3v4_linked ? " (including 3-hop V3→V4 chain)" : "")
           << " (non-existent paths)\n"
           << "  Expected impact: packet loss, increased delay, routing instability\n"
           << "  <- ATTACK SUCCESS\n\n";
    me_log.flush();

    NS_LOG_INFO("[ME-S1] t=" << now << "s  echoed link V" << src_ns3
                << "<->V" << dst_ns3 << " with "
                << (emit_v3 ? "V" + std::to_string(ev3_ns3) : "")
                << ((emit_v3 && emit_v4) ? " and " : "")
                << (emit_v4 ? "V" + std::to_string(ev4_ns3) : "")
                << (v3v4_linked ? " (V3↔V4 linked, Path4 inferred)" : ""));
    std::cout << std::fixed << std::setprecision(3);
    if (emit_v3)
    {
        std::cout << "[ME-S1][t=" << now << "]  STEP④  V" << ev3_ns3
                  << " --ECHO--> Controller  <V" << src_ns3 << " sees V" << dst_ns3
                  << ">  FALSE REPORTER" << std::endl;
    }
    if (emit_v4)
    {
        std::cout << "[ME-S1][t=" << now << "]  STEP④  V" << ev4_ns3
                  << " --ECHO--> Controller  <V" << src_ns3 << " sees V" << dst_ns3
                  << ">  FALSE REPORTER" << std::endl;
    }
    std::cout << "[ME-S1][t=" << now << "]  STEP⑤  Controller infers "
              << (1 + (emit_v3?1:0) + (emit_v4?1:0) + (v3v4_linked?1:0))
              << " path(s) for V" << src_ns3 << "->V" << dst_ns3
              << (v3v4_linked ? "  (Path4: V3↔V4 in range)" : "")
              << "  *** ATTACK COMPLETE ***" << std::endl;
    // Sophistication roll — ME-S1 (per echo reporter independently).
    // Both reporters use own identity (physical=claimed) so Step 1 always passes.
    // Step 1b location-binding (TetaGuardLocBindVerify, Eqs. 3.27-3.29) checks
    // distance from the FORGED reporter_position to whichever single link
    // endpoint (src or dst) is nearest that forged position — see
    // TetaGuardLocBindVerify's closer_to_src selection in teta_guard_filter.h.
    // Bug fix: forging to the MIDPOINT of src/dst (as before) only works when
    // src and dst are within 2*R_COMM of each other — if the real link's own
    // endpoints are farther apart than that (possible with independent vehicle
    // mobility), the midpoint is > R_COMM from BOTH endpoints and every
    // "sophisticated" echo still gets dropped at Stage-0, silently degenerating
    // to the basic case. A real GPS-spoofing attacker would not need to know
    // both endpoints' exact positions to average them — it only needs to claim
    // to be near ONE endpoint (whichever is closer to its own real position,
    // the more plausible lie), with a small jitter modelling GPS spoofing
    // imprecision. This is realistic under the same "attacker forges its own
    // reported position" capability already assumed for the basic path, and
    // it is correct regardless of how far apart src/dst themselves are.
    auto meS1SpoofNearEndpoint = [&](const Vector& realPos) -> Vector {
        const double dSrc = std::sqrt(std::pow(realPos.x - vSrcPos.x, 2.0) + std::pow(realPos.y - vSrcPos.y, 2.0));
        const double dDst = std::sqrt(std::pow(realPos.x - vDstPos.x, 2.0) + std::pow(realPos.y - vDstPos.y, 2.0));
        const Vector& target = (dSrc <= dDst) ? vSrcPos : vDstPos;
        // Draw from AttackGetRng() (already-existing shared attacker-randomization
        // utility used elsewhere for topology/attacker selection), not a new RNG
        // object: creating a new Ptr<UniformRandomVariable> shifts NS-3's
        // auto-assigned stream index for every RandomVariableStream constructed
        // afterward — including AttackGetRng()'s own lazily-constructed static —
        // which perturbs topology/attacker selection for the WHOLE run, a far
        // bigger and less controlled side effect than the one being avoided.
        // AttackGetRng()'s topology-selection draws (AttackShuffleVector, called
        // from declare_attackers() in main()) all happen before Simulator::Run()
        // starts; this call happens later, inside a scheduled callback at
        // t≈10s, so it only ever consumes draws AFTER topology selection has
        // already completed — it cannot retroactively change it.
        const double jitter = AttackGetRng()->GetValue(0.0, 50.0);   // up to 50m GPS-spoof imprecision
        const double angle  = AttackGetRng()->GetValue(0.0, 2.0 * M_PI);
        return Vector(target.x + jitter * std::cos(angle), target.y + jitter * std::sin(angle), 0.0);
    };
    if (emit_v3)
    {
            const bool me_s1_v3_soph = (g_attacker_rng && g_attacker_rng->GetValue() < g_attacker_sophistication_prob);
            const Vector v3ReportPos = me_s1_v3_soph ? meS1SpoofNearEndpoint(v3Pos) : v3Pos;
                std::cout << "[ME-S1][t=" << now << "]  V" << echo_v3 << " sophistication: "
                  << (me_s1_v3_soph ? "SOPHISTICATED — forged near-link pos → locbind BYPASSED → LW+TGN"
                                    : "BASIC — actual pos, may be dropped at Stage-0 locbind") << "\n";
                PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, echo_v3, echo_v3, echo_v3, link_src, link_dst, now, now, v3ReportPos, vSrcPos, vDstPos, true);
        }
    if (emit_v4)
    {
            const bool me_s1_v4_soph = (g_attacker_rng && g_attacker_rng->GetValue() < g_attacker_sophistication_prob);
            const Vector v4ReportPos = me_s1_v4_soph ? meS1SpoofNearEndpoint(v4Pos) : v4Pos;
        std::cout << "[ME-S1][t=" << now << "]  V" << echo_v4 << " sophistication: "
                  << (me_s1_v4_soph ? "SOPHISTICATED — forged near-link pos → locbind BYPASSED → LW+TGN"
                                    : "BASIC — actual pos, may be dropped at Stage-0 locbind") << "\n";
            PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, echo_v4, echo_v4, echo_v4, link_src, link_dst, now, now, v4ReportPos, vSrcPos, vDstPos, true);
        }

    // Crypto latency: each echo reporter signs + controller verifies x2 + haversine x2
#ifdef HAVE_LIBOQS
    if (enable_crypto_latency == 3 && g_crypto_ready && (emit_v3 || emit_v4)) {
        // latency=3: chained events — V3 inject → V4 inject → detection → mitigation
        g_me_l3_ctx = {echo_v3, echo_v4, link_src, link_dst};
        ME_L3_Start(echo_v3, echo_v4, 0.0);
    } else if (enable_crypto_latency && g_crypto_ready) {
        uint8_t msg[64]; RAND_bytes(msg, 64);
        g_crypto_pending_delay_us = 0.0;
        if (emit_v3) {
            CryptoRecord(now, "HMAC_Sign_ME",         TimedHmacSign  (msg,64), echo_v3,  "Attack_Inject", true);
            CryptoRecord(now, "Dilithium_Sign_ME",    TimedDilSign   (msg,64), echo_v3,  "Attack_Inject", true);
            CryptoRecord(now, "HMAC_Verify_ME",       TimedHmacVerify(msg,64), link_src, "Attack_Inject", true);
            CryptoRecord(now, "Dilithium_Verify_ME",  TimedDilVerify (msg,64), link_src, "Attack_Inject", true);
            CryptoRecord(now, "Haversine",            TimedHaversine(),        link_src, "Attack_Inject", true);
        }
        if (emit_v4) {
            CryptoRecord(now, "HMAC_Sign_ME",         TimedHmacSign  (msg,64), echo_v4,  "Attack_Inject", true);
            CryptoRecord(now, "Dilithium_Sign_ME",    TimedDilSign   (msg,64), echo_v4,  "Attack_Inject", true);
            CryptoRecord(now, "HMAC_Verify_ME",       TimedHmacVerify(msg,64), link_dst, "Attack_Inject", true);
            CryptoRecord(now, "Dilithium_Verify_ME",  TimedDilVerify (msg,64), link_dst, "Attack_Inject", true);
            CryptoRecord(now, "Haversine",            TimedHaversine(),        link_dst, "Attack_Inject", true);
        }
        double det_t = g_crypto_inject_delay
                       ? now + g_crypto_pending_delay_us / 1e6
                       : now;
        g_crypto_pending_delay_us = 0.0;
        CryptoMeasureDetection(det_t, link_src, "ME", true);
        CryptoMeasureLKH(det_t, link_src, N_Vehicles);
    }
#endif

    if (pem_last_alert) {
        // Remove echo entries from controller topology table (both reporters)
        if (emit_v3) {
            std::string k3 = std::to_string(echo_v3) + "_echo_" +
                             std::to_string(link_src) + "_" + std::to_string(link_dst);
            ttw_controller_table.erase(k3);
            attack_E_matrix.erase(k3);
            if (topology_divergence_delta > 0) topology_divergence_delta--;
        }
        if (emit_v4) {
            std::string k4 = std::to_string(echo_v4) + "_echo_" +
                             std::to_string(link_src) + "_" + std::to_string(link_dst);
            ttw_controller_table.erase(k4);
            attack_E_matrix.erase(k4);
            if (topology_divergence_delta > 0) topology_divergence_delta--;
        }
        // Full claimed-reporter set R(eij,t) for Eq. 3.30: the two real
        // reporters plus whichever fabricated echo witnesses were injected.
        std::vector<uint32_t> me_s1_reporters{link_src, link_dst};
        if (emit_v3) me_s1_reporters.push_back(echo_v3);
        if (emit_v4) me_s1_reporters.push_back(echo_v4);
        const PemQuorumEvidence me_s1_ev{v3Pos, vSrcPos, vDstPos, link_src, link_dst, me_s1_reporters};
        std::string mit = PemApplyMitigation(echo_v3, now, "ME-S1", &me_s1_ev);
        me_log << "[t=" << now << "]  DETECTION + MITIGATION\n"
               << "  Echo reporters V" << echo_v3 << " and V" << echo_v4
               << " identified; phantom entries removed\n"
               << "  Score: " << pem_last_detection_score << "\n"
               << "  Latency: " << PemGetDetectionLatencyMs() << " ms\n"
               << "  delta after mitigation: " << topology_divergence_delta << "\n"
               << mit << "\n";
        me_log.flush();
    }
}


// =============================================================================
// ME single-attacker, 3-legitimate-vehicle case (V1,V2,V3 legit; one attacker)
// Shared by ME-S1..S4 (attacker identity = malicious vehicle for S1, or the
// impersonated vehicle identity used by the malicious RSU/controller for
// S2-S4 — mirrors how false_v3/false_v4 are already used as impersonated
// identities in the existing 2-attacker functions above).
//
// Which of the two topology cases applies is NOT hardcoded: it is measured
// from the vehicles' actual simulated positions (same TTW_COMM_RANGE rule
// already used for the existing v3v4_linked Path-4 check), exactly per the
// two cases the attack spec calls out:
//   CHAIN : V1<->V2 and V2<->V3 both real (V1,V2,V3 form a connected chain),
//           attacker physically isolated from all three. The attacker echoes
//           BOTH real hops, so the controller can insert it at any of the
//           4 positions around the 3-node chain.
//   SPLIT : only V1<->V2 real; V3 is a separate real pair with the attacker
//           itself (attacker <-> V3 is a genuine physical link). The
//           attacker echoes the V1<->V2 hop, letting the controller not only
//           insert it between V1/V2 but also stitch the two real components
//           together through its genuine V3 link.
// =============================================================================

struct MESingle3Topology {
    bool   chain;   // V1<->V2<->V3 fully real chain, attacker isolated from V1 AND V2
    bool   split;   // V1<->V2 real pair; attacker<->V3 real (attacker's own link);
                     // attacker isolated from V1 AND V2 so its V1<->V2 report is a
                     // genuine echo of a link it never physically observed
    double d12, d23, dA3, dA1, dA2;
};

static Vector MEGetVehiclePos(uint32_t vidx)
{
    if (vidx < Vehicle_Nodes.GetN()) {
        Ptr<MobilityModel> m = Vehicle_Nodes.Get(vidx)->GetObject<MobilityModel>();
        if (m) return m->GetPosition();
    }
    return Vector(0.0, 0.0, 0.0);
}

static double MEDist2D(const Vector& a, const Vector& b)
{
    double dx = a.x - b.x, dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}

static MESingle3Topology MEClassifySingle3(uint32_t v1_id, uint32_t v2_id,
                                            uint32_t v3_id, uint32_t atk_id)
{
    Vector p1 = MEGetVehiclePos(v1_id), p2 = MEGetVehiclePos(v2_id);
    Vector p3 = MEGetVehiclePos(v3_id), pA = MEGetVehiclePos(atk_id);
    MESingle3Topology t;
    t.d12 = MEDist2D(p1, p2);
    t.d23 = MEDist2D(p2, p3);
    t.dA3 = MEDist2D(pA, p3);
    t.dA1 = MEDist2D(pA, p1);
    t.dA2 = MEDist2D(pA, p2);
    bool link12 = t.d12 <= TTW_COMM_RANGE;
    bool link23 = t.d23 <= TTW_COMM_RANGE;
    bool linkA3 = t.dA3 <= TTW_COMM_RANGE;
    // Isolation from the actual echoed link (V1<->V2, and V2<->V3 for chain):
    // without this, the attacker could sit within range of the very link it
    // is echoing, in which case it would be a genuine third witness rather
    // than a false one — the ME-S1 (reporter-density) and ME-S3
    // (position/RSSI-out-of-range) signatures would then correctly find
    // nothing anomalous, silently making the attack undetectable.
    bool linkA1 = t.dA1 <= TTW_COMM_RANGE;
    bool linkA2 = t.dA2 <= TTW_COMM_RANGE;
    bool isolatedFromEchoedLink = !linkA1 && !linkA2;
    t.chain = link12 && link23 && isolatedFromEchoedLink;
    t.split = link12 && !link23 && linkA3 && isolatedFromEchoedLink;
    return t;
}

// mode: 1=ME-S1 (malicious vehicle, direct DSRC), 2=ME-S2 (malicious RSU),
//       3=ME-S3 (malicious controller, no RSU), 4=ME-S4 (malicious controller, with RSU)
void ME_Single3_LegitimateDiscovery(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id,
                                     uint32_t atk_id, double t, int mode, uint32_t rsu_id)
{
    double now = Simulator::Now().GetSeconds();
    MESingle3Topology topo = MEClassifySingle3(v1_id, v2_id, v3_id, atk_id);

    ttw_controller_table[std::to_string(v1_id)+"_"+std::to_string(v2_id)] = {v1_id, v2_id, t, false};
    ttw_controller_table[std::to_string(v2_id)+"_"+std::to_string(v1_id)] = {v2_id, v1_id, t, false};
    if (topo.chain) {
        ttw_controller_table[std::to_string(v2_id)+"_"+std::to_string(v3_id)] = {v2_id, v3_id, t, false};
        ttw_controller_table[std::to_string(v3_id)+"_"+std::to_string(v2_id)] = {v3_id, v2_id, t, false};
    }
    if (topo.split) {
        ttw_controller_table[std::to_string(atk_id)+"_"+std::to_string(v3_id)] = {atk_id, v3_id, t, false};
        ttw_controller_table[std::to_string(v3_id)+"_"+std::to_string(atk_id)] = {v3_id, atk_id, t, false};
    }

    uint32_t v1n = (v1_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v1_id)->GetId()  : v1_id;
    uint32_t v2n = (v2_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v2_id)->GetId()  : v2_id;
    uint32_t v3n = (v3_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v3_id)->GetId()  : v3_id;
    uint32_t an  = (atk_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(atk_id)->GetId() : atk_id;
    const char* tag = (mode == 1) ? "ME-S1" : (mode == 2) ? "ME-S2" : (mode == 3) ? "ME-S3" : "ME-S4";

    me_log << "[t=" << now << "]  STEP ①  3-LEGITIMATE-VEHICLE TOPOLOGY DISCOVERY (single attacker)\n"
           << "  Measured distances: d(V" << v1n << ",V" << v2n << ")=" << topo.d12
           << "m  d(V" << v2n << ",V" << v3n << ")=" << topo.d23
           << "m  d(V" << an << ",V" << v3n << ")=" << topo.dA3 << "m  (range=" << TTW_COMM_RANGE << "m)\n"
           << "  Topology detected: "
           << (topo.chain ? ("FULL CHAIN V" + std::to_string(v1n) + "<->V" + std::to_string(v2n) +
                             "<->V" + std::to_string(v3n) + " (attacker V" + std::to_string(an) + " isolated)\n")
                          : topo.split ? ("SPLIT — V" + std::to_string(v1n) + "<->V" + std::to_string(v2n) +
                             " real pair; attacker V" + std::to_string(an) + "<->V" + std::to_string(v3n) +
                             " is the attacker's own genuine link\n")
                                       : "SPLIT (fallback, unexpected placement) — treating V3 as unrelated bystander\n")
           << "  V" << v1n << " <-> V" << v2n << " : HELLO exchange (real V2V link)\n"
           << (topo.chain ? ("  V" + std::to_string(v2n) + " <-> V" + std::to_string(v3n) + " : HELLO exchange (real V2V link)\n") : "")
           << (topo.split ? ("  V" + std::to_string(an) + " <-> V" + std::to_string(v3n) + " : HELLO exchange (attacker's own genuine link)\n") : "")
           << "\n";

    // STEP②: legitimate topology reporting to the controller — transport differs per scenario mode
    me_log << "[t=" << now << "]  STEP ②  LEGITIMATE TOPOLOGY REPORTING (" << tag << ")\n";
    if (mode == 1) {
        me_log << "  V" << v1n << " -> Controller : <V" << v1n << " sees V" << v2n << ", t=" << t << ">  ACCEPTED\n"
               << "  V" << v2n << " -> Controller : <V" << v2n << " sees V" << v1n << ", t=" << t << ">  ACCEPTED\n"
               << (topo.chain ? ("  V" + std::to_string(v3n) + " -> Controller : <V" + std::to_string(v3n) +
                                 " sees V" + std::to_string(v2n) + ", t=" + std::to_string(t) + ">  ACCEPTED\n") : "")
               << (topo.split ? ("  V" + std::to_string(v3n) + " -> Controller : <V" + std::to_string(v3n) +
                                 " sees V" + std::to_string(an) + ", t=" + std::to_string(t) + ">  ACCEPTED\n") : "")
               << "\n";
    } else if (mode == 2 || mode == 4) {
        me_log << "  V" << v1n << " -> RSU_" << rsu_id << " : <V" << v1n << " sees V" << v2n << ", t=" << t << ">\n"
               << "  V" << v2n << " -> RSU_" << rsu_id << " : <V" << v2n << " sees V" << v1n << ", t=" << t << ">\n"
               << (topo.chain ? ("  V" + std::to_string(v3n) + " -> RSU_" + std::to_string(rsu_id) +
                                 " : <V" + std::to_string(v3n) + " sees V" + std::to_string(v2n) + ", t=" + std::to_string(t) + ">\n") : "")
               << (topo.split ? ("  V" + std::to_string(v3n) + " -> RSU_" + std::to_string(rsu_id) +
                                 " : <V" + std::to_string(v3n) + " sees V" + std::to_string(an) + ", t=" + std::to_string(t) + ">\n") : "")
               << "  RSU_" << rsu_id << " -> Controller : forwarding aggregated legitimate report\n\n";
    } else {
        me_log << "  V" << v1n << " -> Controller : <V" << v1n << " sees V" << v2n << ", t=" << t << ">  ACCEPTED\n"
               << "  V" << v2n << " -> Controller : <V" << v2n << " sees V" << v1n << ", t=" << t << ">  ACCEPTED\n"
               << (topo.chain ? ("  V" + std::to_string(v3n) + " -> Controller : <V" + std::to_string(v3n) +
                                 " sees V" + std::to_string(v2n) + ", t=" + std::to_string(t) + ">  ACCEPTED\n") : "")
               << (topo.split ? ("  V" + std::to_string(v3n) + " -> Controller : <V" + std::to_string(v3n) +
                                 " sees V" + std::to_string(an) + ", t=" + std::to_string(t) + ">  ACCEPTED\n") : "")
               << "\n";
    }

    std::cout << std::fixed << std::setprecision(3)
              << "[" << tag << "][t=" << now << "]  STEP①②  3-legit single-attacker topology: "
              << (topo.chain ? "CHAIN" : topo.split ? "SPLIT" : "SPLIT(fallback)") << std::endl;

    Vector pos1 = MEGetVehiclePos(v1_id), pos2 = MEGetVehiclePos(v2_id), pos3 = MEGetVehiclePos(v3_id);
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v1_id, v1_id, (mode==2||mode==4) ? rsu_id : v1_id, v1_id, v2_id, t, now, pos1, pos1, pos2, false);
    PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v2_id, v2_id, (mode==2||mode==4) ? rsu_id : v2_id, v2_id, v1_id, t, now, pos2, pos2, pos1, false);
    if (topo.chain)
        PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v3_id, v3_id, (mode==2||mode==4) ? rsu_id : v3_id, v3_id, v2_id, t, now, pos3, pos3, pos2, false);
    if (topo.split)
        PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, v3_id, v3_id, (mode==2||mode==4) ? rsu_id : v3_id, v3_id, atk_id, t, now, pos3, pos3, MEGetVehiclePos(atk_id), false);
    PemEmitVehicleBeacon(v1_id, v2_id);
    if (v1_id < Vehicle_Nodes.GetN() && v2_id < Vehicle_Nodes.GetN()) {
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v1_id), Vehicle_Nodes.Get(v2_id));
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v2_id), Vehicle_Nodes.Get(v1_id));
    }
    if (topo.chain && v2_id < Vehicle_Nodes.GetN() && v3_id < Vehicle_Nodes.GetN()) {
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v2_id), Vehicle_Nodes.Get(v3_id));
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v3_id), Vehicle_Nodes.Get(v2_id));
    }
    if (topo.split && atk_id < Vehicle_Nodes.GetN() && v3_id < Vehicle_Nodes.GetN()) {
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(atk_id), Vehicle_Nodes.Get(v3_id));
        AttackSendDSRCBeacon(Vehicle_Nodes.Get(v3_id), Vehicle_Nodes.Get(atk_id));
    }
    if (mode == 2 || mode == 4) AttackSendRSUToController(rsu_id);
}

void ME_Single3_EchoAttack(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id,
                           uint32_t atk_id, double t, int mode, uint32_t rsu_id)
{
    double now = Simulator::Now().GetSeconds();
    if (pem_attack_injection_time < 0.0) pem_attack_injection_time = now;
    pem_attack_active = true;
    pem_mitigation_active = false;

    MESingle3Topology topo = MEClassifySingle3(v1_id, v2_id, v3_id, atk_id);
    me_s1_actual_attackers.insert(atk_id);

    uint32_t v1n = (v1_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v1_id)->GetId()  : v1_id;
    uint32_t v2n = (v2_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v2_id)->GetId()  : v2_id;
    uint32_t v3n = (v3_id  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(v3_id)->GetId()  : v3_id;
    uint32_t an  = (atk_id < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(atk_id)->GetId() : atk_id;
    const char* tag = (mode == 1) ? "ME-S1" : (mode == 2) ? "ME-S2" : (mode == 3) ? "ME-S3" : "ME-S4";

    // The attacker echoes every real edge that does NOT already touch it —
    // one echo report per real edge, exactly the same "false reporter of an
    // existing real link" mechanic already used by the 2-attacker functions
    // above, just applied to however many real edges the detected topology has.
    std::vector<std::pair<uint32_t,uint32_t>> echoedEdges;
    echoedEdges.push_back({v1_id, v2_id});
    if (topo.chain) echoedEdges.push_back({v2_id, v3_id});

    for (auto& e : echoedEdges) {
        MEEchoReport r = {e.first, e.second, atk_id, t, true};
        me_echo_reports.push_back(r);
        std::string k = std::to_string(atk_id) + "_echo3_" + std::to_string(e.first) + "_" + std::to_string(e.second);
        ttw_controller_table[k] = {atk_id, e.second, t, true};
        attack_E_matrix.insert(k);
        topology_divergence_delta++;
    }

    Vector v1Pos = MEGetVehiclePos(v1_id), v2Pos = MEGetVehiclePos(v2_id);
    Vector v3Pos = MEGetVehiclePos(v3_id), aPos  = MEGetVehiclePos(atk_id);

    me_log << "[t=" << now << "]  STEP ③  ECHO INJECTION BY ATTACKER V" << an << " (" << tag << ")\n";
    for (auto& e : echoedEdges) {
        uint32_t en1 = (e.first  < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(e.first)->GetId()  : e.first;
        uint32_t en2 = (e.second < Vehicle_Nodes.GetN()) ? Vehicle_Nodes.Get(e.second)->GetId() : e.second;
        me_log << "  V" << an << " -> Controller : <V" << en1 << " sees V" << en2
               << ", t=" << t << ">  (ECHO — false reporter)\n";
    }
    me_log << "  Note: attacker duplicates existing real link(s) — no new physical link fabricated\n\n";

    me_log << "[t=" << now << "]  STEP ④  MULTIPATH INFERENCE AT CONTROLLER (Attack Effect)\n"
           << "  Controller incorrectly infers:\n";
    int pathNum = 1;
    if (topo.chain) {
        me_log << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << " -> V" << v3n << "  (REAL)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << " -> V" << an  << " -> V" << v3n << "  (PHANTOM)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << an  << " -> V" << v2n << " -> V" << v3n << "  (PHANTOM)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << " -> V" << v3n << " -> V" << an  << "  (PHANTOM)\n"
               << "    Path " << pathNum++ << ": V" << an  << " -> V" << v1n << " -> V" << v2n << " -> V" << v3n << "  (PHANTOM)\n";
    } else {
        me_log << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << "  (REAL)\n"
               << "    Path " << pathNum++ << ": V" << an  << " -> V" << v3n << "  (REAL — attacker's own genuine link)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << an  << " -> V" << v2n << "  (PHANTOM)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << " -> V" << an  << "  (PHANTOM)\n"
               << "    Path " << pathNum++ << ": V" << v1n << " -> V" << v2n << " -> V" << an  << " -> V" << v3n << "  (PHANTOM — stitched via attacker's real V3 link)\n";
    }
    me_log << "\n[t=" << now << "]  STEP ⑤  FAULTY ROUTING DECISIONS\n"
           << "  Controller installs routing rules relying on phantom paths through V" << an << "\n"
           << "  Expected impact: packet loss, increased delay, routing instability\n"
           << "  <- ATTACK SUCCESS\n\n";
    me_log.flush();

    std::cout << std::fixed << std::setprecision(3)
              << "[" << tag << "][t=" << now << "]  STEP③④  V" << an << " echoes "
              << echoedEdges.size() << " real edge(s) — "
              << (topo.chain ? "CHAIN 4-phantom-path" : "SPLIT 3-phantom-path")
              << " inference  *** ATTACK COMPLETE ***" << std::endl;

    // physical_sender/reporter conventions must match the legacy 2-attacker
    // functions above (ME_S2_InjectEchoReports / ME_S3_InjectPhantomPaths /
    // ME_S4_InjectPhantomPaths): mode 2 (malicious RSU) is physically injected
    // by the RSU itself, so physical_sender=reporter=rsu_id; modes 3 and 4
    // (malicious controller, with or without RSU in the legitimate-reporting
    // path) inject purely internally at the controller (sentinel 9999u), with
    // the impersonated vehicle identity as reporter — NOT the RSU, even in
    // mode 4, since the RSU there is legitimate and only carries real reports.
    const uint32_t echoPhysicalSender = (mode == 2) ? rsu_id : (mode == 3 || mode == 4) ? 9999u : atk_id;
    const uint32_t echoReporterId     = (mode == 2) ? rsu_id : atk_id;
    for (auto& e : echoedEdges) {
        PemEmitEvent(PEM_EVENT_TOPOLOGY_UPDATE, echoPhysicalSender, atk_id,
                     echoReporterId,
                     e.first, e.second, t, now, aPos,
                     MEGetVehiclePos(e.first), MEGetVehiclePos(e.second), true);
    }
    if (mode == 2 || mode == 4) AttackSendRSUToController(rsu_id);

    if (pem_last_alert) {
        for (auto& e : echoedEdges) {
            std::string k = std::to_string(atk_id) + "_echo3_" + std::to_string(e.first) + "_" + std::to_string(e.second);
            ttw_controller_table.erase(k);
            attack_E_matrix.erase(k);
            if (topology_divergence_delta > 0) topology_divergence_delta--;
        }
        // Single fabricated witness (echoReporterId) alongside the two real
        // link endpoints — full claimed-reporter set for Eq. 3.30.
        const std::vector<uint32_t> single3_reporters{v1_id, v2_id, echoReporterId};
        const PemQuorumEvidence ev{aPos, v1Pos, v2Pos, v1_id, v2_id, single3_reporters};
        std::string trust_single3;
        if (mode == 3 || mode == 4) {
            // Controller-origin modes: the real attacker is the controller, not
            // the impersonated vehicle atk_id (PemApplyMitigation's own guard
            // already protects atk_id from being zero-trusted here — see its
            // is_malicious_controller check). Without this, nothing else in
            // this shared 3-legit-vehicle path penalises the controller at all,
            // unlike the dedicated ME_S3_InjectPhantomPaths/ME_S4_... functions
            // which already call TrustReassignController themselves.
            uint32_t ctrl_single3 = (controller_Node.GetN() > 0)
                                     ? controller_Node.Get(0)->GetId() : 9999u;
            std::string ctrl_div_log_single3;
            if (PemControllerDivergenceGate(now, tag, ctrl_div_log_single3, v1_id, v2_id, now)) {
                TrustUpdateNode(ctrl_single3, false, true);
                trust_single3 = TrustReassignController(ctrl_single3, now);
            }
            trust_single3 = ctrl_div_log_single3 + trust_single3;
            TrustRunDemotionPipeline(now);
        }
        // Mode 2 (malicious RSU): the RSU is the real physical attacker
        // (echoPhysicalSender == rsu_id above), so mitigation/trust zeroing
        // must target the RSU, not the impersonated vehicle atk_id.
        const uint32_t mitigationTargetId = (mode == 2) ? echoPhysicalSender : atk_id;
        std::string mit = PemApplyMitigation(mitigationTargetId, now, tag, &ev);
        me_log << "[t=" << now << "]  DETECTION + MITIGATION\n"
               << "  Attacker V" << an << " identified; phantom entries removed\n"
               << "  Score: " << pem_last_detection_score << "\n"
               << "  Latency: " << PemGetDetectionLatencyMs() << " ms\n"
               << "  delta after mitigation: " << topology_divergence_delta << "\n"
               << mit << trust_single3 << "\n";
        me_log.flush();
    }
}

// Thin per-scenario wrappers with <=6 parameters — ns3::Simulator::Schedule's
// free-function template overload only supports up to 6 trailing arguments;
// the 7-argument core functions above (v1,v2,v3,atk,t,mode,rsu_id) cannot be
// passed to Schedule directly (the compiler otherwise silently falls back to
// the member-function-pointer overload and fails with an unrelated template
// error about EventMemberImplObjTraits).
void ME_Single3_LegitimateDiscovery_S1(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t)
{ ME_Single3_LegitimateDiscovery(v1_id, v2_id, v3_id, atk_id, t, 1, UINT32_MAX); }
void ME_Single3_LegitimateDiscovery_S2(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t, uint32_t rsu_id)
{ ME_Single3_LegitimateDiscovery(v1_id, v2_id, v3_id, atk_id, t, 2, rsu_id); }
void ME_Single3_LegitimateDiscovery_S3(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t)
{ ME_Single3_LegitimateDiscovery(v1_id, v2_id, v3_id, atk_id, t, 3, UINT32_MAX); }
void ME_Single3_LegitimateDiscovery_S4(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t, uint32_t rsu_id)
{ ME_Single3_LegitimateDiscovery(v1_id, v2_id, v3_id, atk_id, t, 4, rsu_id); }

void ME_Single3_EchoAttack_S1(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t)
{ ME_Single3_EchoAttack(v1_id, v2_id, v3_id, atk_id, t, 1, UINT32_MAX); }
void ME_Single3_EchoAttack_S2(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t, uint32_t rsu_id)
{ ME_Single3_EchoAttack(v1_id, v2_id, v3_id, atk_id, t, 2, rsu_id); }
void ME_Single3_EchoAttack_S3(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t)
{ ME_Single3_EchoAttack(v1_id, v2_id, v3_id, atk_id, t, 3, UINT32_MAX); }
void ME_Single3_EchoAttack_S4(uint32_t v1_id, uint32_t v2_id, uint32_t v3_id, uint32_t atk_id, double t, uint32_t rsu_id)
{ ME_Single3_EchoAttack(v1_id, v2_id, v3_id, atk_id, t, 4, rsu_id); }


