void write_csv_status()
{
	fstream fout;
	fout.open("/home/sdvn_echo_topology/ns-allinone-3.35/ns-3.35/scratch/optimization_link_lifetime_data.csv",ios::out|ios::trunc);
	for (uint32_t i=2; i<total_size+2 ;i++)
	{
		Ptr <Node> node;
		if ((i-2) < N_Vehicles)
		{	
			node = DynamicCast <Node> (Vehicle_Nodes.Get(i-2));
		}
		else
		{
			node = DynamicCast <Node> (RSU_Nodes.Get(i-N_Vehicles-2));
		}
		
		Ptr<ConstantVelocityMobilityModel> mdl = DynamicCast <ConstantVelocityMobilityModel> (node->GetObject<MobilityModel>());
        	Vector position = mdl->GetPosition();
        	Vector velocity = mdl->GetVelocity();
		//cout<<"writing status "<<i<<endl;
		fout << total_size << ", "
		     << position.x << ", "
		     <<	position.y << ", "
		     << velocity.x<< ", "
		     << velocity.y << ", "
		     << data_at_manager_inst[i].acceleration.x << ", "
		     << data_at_manager_inst[i].acceleration.y << ", "
		     << mobility_scenario << ", "
		     << N_Vehicles << ", "
		     << N_RSUs << ", "
		     << "\n";
	}
	fout.close();
	cout<<"finished writing status"<<endl;
}


void read_csv()
{
    fstream fin;
    fin.open("/home/sdvn_echo_topology/ns-allinone-3.35/ns-3.35/scratch/optimization_results.csv", ios::in);
    vector<string> row;
    string line;
    string temp;
    int j=0;
    while (fin >> temp) 
    {
        row.clear();
        getline(fin, line);
        int n = line.length();
        char line_char[n+1];
        strcpy(line_char,line.c_str());
        //cout<<line<<endl;
        int int_val;
        char * ptr;
        ptr = strtok(line_char,",");
        int i =0;
        while(ptr != NULL)
        {
        	stringstream ss;
		ss << ptr;
		ss >> int_val;
		if (i==0)
		{
			X_gurobi[j+2] = int_val;
			//cout<<"x"<<j<<" value "<<int_val<<endl;
		}
		if (i==1)
		{
			Z_gurobi[j+2] = int_val;
			//cout<<"z"<<j<<"value "<<int_val<<endl;
		}
        	
        	ptr = strtok(NULL,",");   
        	i++;	
        }
        j++;
    }
    if (j == 0)
        cout << "Solution not found\n";
}

